INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ec599ce-9488-40fe-b59e-607e7e4a50c5', '懷仙三首 一', '懷仙三首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["聞道陽都女，連娟耳細長。","自非黃犢客，不得到雲房。"]', '["闻道陽都女，連娟耳細长。","自非黄犢客，不得到云房。"]', '诗', 'shi', '', NULL, '懷仙三首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d9d59d0-5d1b-4b34-90c9-2131f6950abb', '懷仙三首 二', '懷仙三首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["但服鐶剛子，兼吟曲素詞。","須知臣漢客，還見布龍兒。"]', '["但服鐶剛子，兼吟曲素词。","須知臣漢客，還见布龙兒。"]', '诗', 'shi', '', NULL, '懷仙三首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d59e145a-1f94-481f-9264-e4c966b28285', '懷仙三首 三', '懷仙三首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["神燭光華麗，靈祛羽翼生。","已傳餐玉粒，猶自買雲英。"]', '["神燭光华丽，靈祛羽翼生。","已傳餐玉粒，猶自買云英。"]', '诗', 'shi', '', NULL, '懷仙三首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f0c8230-edc7-490a-a67e-a4004fb1b8af', '芙蓉', '芙蓉', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["閑吟鮑照賦，更起屈平愁。","莫引西風動，紅衣不耐秋。"]', '["闲吟鲍照賦，更起屈平愁。","莫引西风动，紅衣不耐秋。"]', '诗', 'shi', '', NULL, '芙蓉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ce33e92-d9f4-4732-9202-9354d152ce85', '春思', '春思', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["怨鶯新語澀，雙蝶鬬飛高。","作箇名春恨，浮生百倍勞。"]', '["怨鶯新語澀，雙蝶鬬飞高。","作箇名春恨，浮生百倍勞。"]', '诗', 'shi', '', NULL, '春思 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87354c2e-c690-454f-b0b0-6644bc4e2274', '風人詩四首 一', '风人诗四首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["十萬全師出，遙知正憶君。","一心如瑞麥，長作兩岐分。"]', '["十万全師出，遙知正憶君。","一心如瑞麦，长作兩岐分。"]', '诗', 'shi', '', NULL, '風人詩四首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('674ea966-fc1a-4286-8198-6ee4455c3d78', '風人詩四首 二', '风人诗四首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["破檗供朝爨，須憐是苦辛。","曉天窺落宿，誰識獨醒人。"]', '["破檗供朝爨，須怜是苦辛。","晓天窺落宿，誰識独醒人。"]', '诗', 'shi', '', NULL, '風人詩四首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f93d2980-a094-4e55-a4f2-793d14167b7b', '風人詩四首 三', '风人诗四首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["旦日思雙屨，明時願早諧。","丹青傳四瀆，難寫是秋懷。"]', '["旦日思雙屨，明时願早諧。","丹青傳四瀆，难寫是秋懷。"]', '诗', 'shi', '', NULL, '風人詩四首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48f3aa8-c87b-470d-8fa1-bdcb18d7266c', '風人詩四首 四', '风人诗四首 四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["聞道更新幟，多應廢舊旗。","征衣無伴擣，獨處自然悲。"]', '["闻道更新幟，多應廢旧旗。","征衣無伴擣，独处自然悲。"]', '诗', 'shi', '', NULL, '風人詩四首 四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edac24e0-5be7-4bf7-bd30-85dc65038e36', '樂府雜詠六首 雙吹管', '乐府杂詠六首 雙吹管', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["長短裁浮筠，參差作飛鳳。","高樓微月夜，吹出江南弄。"]', '["长短裁浮筠，參差作飞鳳。","高楼微月夜，吹出江南弄。"]', '诗', 'shi', '', NULL, '樂府雜詠六首 雙吹管 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4edf6eb1-e47b-4b36-8e01-a237c1f003e0', '樂府雜詠六首 東飛鳧', '乐府杂詠六首 东飞鳧', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["裁得尺錦書，欲寄東飛鳧。","脛短翅亦短，雌雄戀菰蒲。"]', '["裁得尺錦书，欲寄东飞鳧。","脛短翅亦短，雌雄戀菰蒲。"]', '诗', 'shi', '', NULL, '樂府雜詠六首 東飛鳧 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a819d324-f31d-4d62-952e-54d9909c7e92', '樂府雜詠六首 花成子', '乐府杂詠六首 花成子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["春風等君意，亦解欺桃李。","寫得去時真，歸來不相似。"]', '["春风等君意，亦解欺桃李。","寫得去时真，归来不相似。"]', '诗', 'shi', '', NULL, '樂府雜詠六首 花成子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0746f78a-81c6-40f9-bef4-e161e512cccb', '樂府雜詠六首 月成弦', '乐府杂詠六首 月成弦', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["孤光照還沒，轉益傷離別。","妾若是嫦娥，長圓不教缺。"]', '["孤光照還沒，轉益傷離別。","妾若是嫦娥，长圓不教缺。"]', '诗', 'shi', '', NULL, '樂府雜詠六首 月成弦 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa5f5f2-f7db-45c3-94c1-8ad5ed5a9168', '樂府雜詠六首 孤燭怨', '乐府杂詠六首 孤燭怨', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["前回邊使至，聞道交河戰。","坐想鼓鞞聲，寸心攢百箭。"]', '["前回邊使至，闻道交河戰。","坐想鼓鞞声，寸心攢百箭。"]', '诗', 'shi', '', NULL, '樂府雜詠六首 孤燭怨 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b36b1ff-2f5e-430f-9fb9-e88a8a640fd2', '樂府雜詠六首 金吾子', '乐府杂詠六首 金吾子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["嫁得金吾子，常聞輕薄名。","君心如不重，妾腰徒自輕。"]', '["嫁得金吾子，常闻轻薄名。","君心如不重，妾腰徒自轻。"]', '诗', 'shi', '', NULL, '樂府雜詠六首 金吾子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70b3b2d-7cc7-40c7-a6f7-0b67bcd13b60', '子夜四時歌 春', '子夜四时歌 春', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山連翠羽屏，草接煙華席。","望盡南飛燕，佳人斷消息。"]', '["山連翠羽屏，草接煙华席。","望尽南飞燕，佳人斷消息。"]', '诗', 'shi', '', NULL, '子夜四時歌 春 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9973e24-b93a-4089-8859-251515f67048', '子夜四時歌 夏', '子夜四时歌 夏', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["蘭眼擡路斜，鶯脣映花老。","金龍傾漏盡，玉井敲冰早。"]', '["蘭眼擡路斜，鶯脣映花老。","金龙傾漏尽，玉井敲冰早。"]', '诗', 'shi', '', NULL, '子夜四時歌 夏 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2e3400-3d53-4861-bc08-87dc6ab32491', '子夜四時歌 秋', '子夜四时歌 秋', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["涼漢清泬寥，衰林怨風雨。","愁聽絡緯唱，似與羈魂語。"]', '["涼漢清泬寥，衰林怨风雨。","愁听絡緯唱，似與羈魂語。"]', '诗', 'shi', '', NULL, '子夜四時歌 秋 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4d7c58b-e4bf-4ae2-ab00-a5a0b32aead6', '子夜四時歌 冬', '子夜四时歌 冬', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["南雲走冷圭，北籟號空木。","年年任霜霰，不減篔簹綠。"]', '["南云走冷圭，北籟號空木。","年年任霜霰，不減篔簹綠。"]', '诗', 'shi', '', NULL, '子夜四時歌 冬 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4e56461-deab-4929-8e27-4f47d96c7c4c', '大子夜歌二首 一', '大子夜歌二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["歌謠數百種，子夜最可憐。","慷慨吐清音，明轉出天然。"]', '["歌謠數百種，子夜最可怜。","慷慨吐清音，明轉出天然。"]', '诗', 'shi', '', NULL, '大子夜歌二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d49f730-87b9-48b4-b9bc-7c621678e0cd', '大子夜歌二首 二', '大子夜歌二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["絲竹發歌響，假器揚清音。","不知歌謠妙，聲勢出口心。"]', '["絲竹發歌响，假器揚清音。","不知歌謠妙，声勢出口心。"]', '诗', 'shi', '', NULL, '大子夜歌二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('403e8f20-dcdd-44d7-b7c1-3c5ec1abf4ab', '子夜警歌二首 一', '子夜警歌二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鏤椀傳綠酒，雕鑪薰紫煙。","誰知苦寒調，共作白雪弦。"]', '["鏤椀傳綠酒，雕鑪薰紫煙。","誰知苦寒調，共作白雪弦。"]', '诗', 'shi', '', NULL, '子夜警歌二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c98398-c0a0-4aa9-b8d5-4b90a5829691', '子夜警歌二首 二', '子夜警歌二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["恃愛如欲進，含羞出不前。","朱口發豔歌，玉指弄嬌弦。"]', '["恃愛如欲進，含羞出不前。","朱口發豔歌，玉指弄嬌弦。"]', '诗', 'shi', '', NULL, '子夜警歌二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f6681d-8878-4750-8c48-419de11051a0', '子夜變歌三首 一', '子夜变歌三首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["人傳歡負情，我自未嘗見。","三更開門去，始知子夜變。"]', '["人傳歡負情，我自未嘗见。","三更开门去，始知子夜变。"]', '诗', 'shi', '', NULL, '子夜變歌三首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28adf1a8-645e-47b1-9932-45f1b0dd42d3', '子夜變歌三首 二', '子夜变歌三首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["歲月如流邁，春盡秋已至。","熒熒條上花，零落何乃駛。"]', '["歲月如流邁，春尽秋已至。","熒熒條上花，零落何乃駛。"]', '诗', 'shi', '', NULL, '子夜變歌三首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6663b515-bde1-48c4-b75e-7bb9f87c5d5b', '子夜變歌三首 三', '子夜变歌三首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["歲月如流邁，行已及素秋。","蟋蟀吟堂前，惆悵使儂愁。"]', '["歲月如流邁，行已及素秋。","蟋蟀吟堂前，惆悵使儂愁。"]', '诗', 'shi', '', NULL, '子夜變歌三首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe698c24-3a34-40db-aac3-8e04885874b1', '江南曲五首 一', '江南曲五首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉間，參差隱葉扇。","鵁鶄𪈺鳿窺，瀲灩無因見。"]', '["鱼戲蓮葉间，參差隐葉扇。","鵁鶄𪈺鳿窺，瀲灩無因见。"]', '诗', 'shi', '', NULL, '江南曲五首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df8ced00-ce5f-42dd-a6a6-a0b50f2ce120', '江南曲五首 二', '江南曲五首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉東，初霞射紅尾。","傍臨謝山側，恰值清風起。"]', '["鱼戲蓮葉东，初霞射紅尾。","傍臨謝山側，恰值清风起。"]', '诗', 'shi', '', NULL, '江南曲五首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e008984d-a77e-4a4f-99c0-f815160ff378', '江南曲五首 三', '江南曲五首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉西，盤盤舞波急。","潛依曲岸涼，正直斜光入。"]', '["鱼戲蓮葉西，盤盤舞波急。","潛依曲岸涼，正直斜光入。"]', '诗', 'shi', '', NULL, '江南曲五首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8bdca89-9aa6-4849-a6a5-78047b9bc559', '江南曲五首 四', '江南曲五首 四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉南，欹危舞煙疊。","光搖越鳥巢，影亂吳娃檝。"]', '["鱼戲蓮葉南，欹危舞煙叠。","光搖越鸟巢，影亂吳娃檝。"]', '诗', 'shi', '', NULL, '江南曲五首 四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0371cfd-d737-4403-bb5c-34ba53cbbaa1', '江南曲五首 五', '江南曲五首 五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉北，澄陽動微漣。","回看帝子渚，稍背鄂君船。"]', '["鱼戲蓮葉北，澄陽动微漣。","回看帝子渚，稍背鄂君船。"]', '诗', 'shi', '', NULL, '江南曲五首 五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc2696e2-2be8-4278-ae40-059f1703c0f4', '陌上桑', '陌上桑', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["皓齒還如貝色含，長眉亦似煙華貼。","鄰娃盡著繡襠襦，獨自提筐採蠶葉。"]', '["皓齒還如貝色含，长眉亦似煙华貼。","鄰娃尽著繡襠襦，独自提筐採蠶葉。"]', '诗', 'shi', '', NULL, '陌上桑 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de49723-2a54-4bdc-870d-99ffacf6cf8a', '自遣詩三十首 一', '自遣诗三十首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["五年重別舊山村，樹有交柯犢有孫。","更感卞峰顏色好，曉雲纔散便當門。"]', '["五年重別旧山村，樹有交柯犢有孫。","更感卞峰顏色好，晓云纔散便當门。"]', '诗', 'shi', '', NULL, '自遣詩三十首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888ddaa6-1f62-4f20-8ae5-788c346d5278', '自遣詩三十首 二', '自遣诗三十首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雪下孤村淅淅鳴，病魂無睡灑來清。","心搖秖待東窗曉，長媿寒雞第一聲。"]', '["雪下孤村淅淅鳴，病魂無睡灑来清。","心搖秖待东窗晓，长媿寒雞第一声。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c1ae605-59cb-4b3d-ac6a-094049812cbe', '自遣詩三十首 三', '自遣诗三十首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["多情多感自難忘，秖有風流共古長。","座上不遺金帶枕，陳王詞賦爲誰傷。"]', '["多情多感自难忘，秖有风流共古长。","座上不遺金带枕，陳王词賦爲誰傷。"]', '诗', 'shi', '', NULL, '自遣詩三十首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('928637c2-0cdc-43fe-881b-3581759f2aab', '自遣詩三十首 四', '自遣诗三十首 四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["甫里先生未白頭，酒旗猶可戰高樓。","長鯨好鱠無因得，乞取艅艎作釣舟。"]', '["甫里先生未白头，酒旗猶可戰高楼。","长鯨好鱠無因得，乞取艅艎作釣舟。"]', '诗', 'shi', '', NULL, '自遣詩三十首 四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c226cbc-b4f5-4b07-a0d4-c02cd93e49b2', '自遣詩三十首 五', '自遣诗三十首 五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["花瀨濛濛紫氣昏，水邊山曲更深村。","終須揀取幽棲處，老檜成雙便作門。"]', '["花瀨濛濛紫氣昏，水邊山曲更深村。","終須揀取幽棲处，老檜成雙便作门。"]', '诗', 'shi', '', NULL, '自遣詩三十首 五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ffaebd-baa7-46c3-ba69-aa95f1eaaa40', '自遣詩三十首 六', '自遣诗三十首 六', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["陰洞曾爲採藥行，冷雲凝絕燭微明。","玉芝敲折琤然墮，合有真人上姓名。"]', '["陰洞曾爲採藥行，冷云凝絕燭微明。","玉芝敲折琤然墮，合有真人上姓名。"]', '诗', 'shi', '', NULL, '自遣詩三十首 六 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd88f6e-8b78-4b18-958c-c3acb0393944', '自遣詩三十首 七', '自遣诗三十首 七', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["長歎人間髪易華，暗將心事許煙霞。","病來前約分明在，藥鼎書囊便是家。"]', '["长歎人间髪易华，暗將心事許煙霞。","病来前約分明在，藥鼎书囊便是家。"]', '诗', 'shi', '', NULL, '自遣詩三十首 七 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ebcd55-1c55-4b7d-b1e0-2082896b24cd', '自遣詩三十首 八', '自遣诗三十首 八', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["醞得秋泉似玉容，比于雲液更應濃。","思量北海徐劉輩，枉向人間號酒龍。"]', '["醞得秋泉似玉容，比于云液更應濃。","思量北海徐劉輩，枉向人间號酒龙。"]', '诗', 'shi', '', NULL, '自遣詩三十首 八 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2717ca7-2011-4240-90a4-82786b1a025c', '自遣詩三十首 九', '自遣诗三十首 九', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["羊侃多應自古豪，解盤金矟置纖腰。","縱然此事教雙得，不博溪田二頃苗。"]', '["羊侃多應自古豪，解盤金矟置纖腰。","縱然此事教雙得，不博溪田二頃苗。"]', '诗', 'shi', '', NULL, '自遣詩三十首 九 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e9ab1c-247f-4156-8f4c-9a00578da8b2', '自遣詩三十首 十', '自遣诗三十首 十', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["偶然攜稚看微波，臨水春寒一倍多。","便使筆精如逸少，嬾能書字換羣鵝。"]', '["偶然携稚看微波，臨水春寒一倍多。","便使笔精如逸少，嬾能书字換羣鵝。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ebadf4-3edc-46f8-9842-c959ce59e0a4', '自遣詩三十首 十一', '自遣诗三十首 十一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["昔聞莊叟迢迢夢，又道韓生苒苒飛。","知有姓名聊寄問，更無言語抱斜暉。"]', '["昔闻莊叟迢迢梦，又道韓生苒苒飞。","知有姓名聊寄问，更無言語抱斜暉。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('390e066d-4831-49e7-b192-ad29d6f06d6c', '自遣詩三十首 十二', '自遣诗三十首 十二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雪侵春事太無端，舞急微還近臘寒。","應是也疑真宰怪，休時猶未徧林巒。"]', '["雪侵春事太無端，舞急微還近臘寒。","應是也疑真宰怪，休时猶未徧林巒。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebdcfb1a-6fe4-4e33-83a0-698416684771', '自遣詩三十首 十三', '自遣诗三十首 十三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["數尺遊絲墮碧空，年年長是惹東風。","爭知天上無人住，亦有春愁鶴髪翁。"]', '["數尺游絲墮碧空，年年长是惹东风。","爭知天上無人住，亦有春愁鹤髪翁。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8bdbccd-b637-484f-be81-5b9fe693a52f', '自遣詩三十首 十四', '自遣诗三十首 十四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["誰使寒鴉意緒嬌，雲情山晚動情憀。","亂和殘照紛紛舞，應索陽烏次第饒。"]', '["誰使寒鴉意緒嬌，云情山晚动情憀。","亂和殘照紛紛舞，應索陽烏次第饒。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc510bb3-4344-4ee7-a6c2-356040385470', '自遣詩三十首 十五', '自遣诗三十首 十五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["古往天高事渺茫，爭知靈媛不淒涼。","月娥如有相思淚，秖待方諸寄兩行。"]', '["古往天高事渺茫，爭知靈媛不淒涼。","月娥如有相思泪，秖待方諸寄兩行。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262f9d37-d179-4c2d-b225-2dc550ab11d6', '自遣詩三十首 十六', '自遣诗三十首 十六', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["本來雲外寄閑身，遂與溪雲作主人。","一夜逆風愁四散，曉來零落傍衣巾。"]', '["本来云外寄闲身，遂與溪云作主人。","一夜逆风愁四散，晓来零落傍衣巾。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十六 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f7d34a8-c590-4387-9e0b-62e601ccd541', '自遣詩三十首 十七', '自遣诗三十首 十七', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["淵明不待公田熟，乘興先秋解印歸。","我爲餘糧春未去，到頭誰是復誰非。"]', '["淵明不待公田熟，乘兴先秋解印归。","我爲餘糧春未去，到头誰是复誰非。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十七 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458e54ea-f2a2-48c0-ac52-8cfd1df86586', '自遣詩三十首 十八', '自遣诗三十首 十八', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雲擁根株抱石危，斲來文似瘦蛟螭。","幽人帶病慵朝起，秖向春山盡日欹。"]', '["云擁根株抱石危，斲来文似瘦蛟螭。","幽人带病慵朝起，秖向春山尽日欹。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十八 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c5a465b-2bf3-4e88-96f7-78caefb7ef04', '自遣詩三十首 十九', '自遣诗三十首 十九', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["月澹花閑夜已深，宋家微詠若遺音。","重思萬古無人賞，露濕清香獨滿襟。"]', '["月澹花闲夜已深，宋家微詠若遺音。","重思万古無人賞，露濕清香独满襟。"]', '诗', 'shi', '', NULL, '自遣詩三十首 十九 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56ddd590-95c5-4387-95be-8d92bdbe4f8f', '自遣詩三十首 二十', '自遣诗三十首 二十', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["南岸春田手自農，往來橫截半江風。","有時不耐輕橈興，暫欲蓬山訪洛公。"]', '["南岸春田手自農，往来橫截半江风。","有时不耐轻橈兴，暫欲蓬山訪洛公。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ad7924-4519-432b-bd5d-150238917a90', '自遣詩三十首 二十一', '自遣诗三十首 二十一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["賢達垂竿小隱中，我來真作捕魚翁。","前溪一夜春流急，已學嚴灘下釣筒。"]', '["賢達垂竿小隐中，我来真作捕鱼翁。","前溪一夜春流急，已学嚴灘下釣筒。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2849f48-84c1-4b3a-81e9-01e8fa0ac013', '自遣詩三十首 二十二', '自遣诗三十首 二十二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水國君王又姓蕭，風情由是冠南朝。","靈和殿下巴江柳，十二旒前舞翠條。"]', '["水国君王又姓蕭，风情由是冠南朝。","靈和殿下巴江柳，十二旒前舞翠條。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64bef918-37a9-434a-af3b-fcfa1c4829bf', '自遣詩三十首 二十三', '自遣诗三十首 二十三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["強梳蓬鬢整斜冠，片燭光微夜思闌。","天意最饒惆悵事，單棲分付與春寒。"]', '["強梳蓬鬢整斜冠，片燭光微夜思闌。","天意最饒惆悵事，單棲分付與春寒。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733095ab-652b-4772-af79-1c2ed70428aa', '自遣詩三十首 二十四', '自遣诗三十首 二十四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["無多藥圃近南榮，合有新苗次第生。","稚子不知名品上，恐隨春草鬬輸贏。"]', '["無多藥圃近南榮，合有新苗次第生。","稚子不知名品上，恐隨春草鬬輸贏。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89cbfd89-6bec-4576-83de-1de7dea9eb4d', '自遣詩三十首 二十五', '自遣诗三十首 二十五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一派溪隨箬下流，春來無處不汀洲。","漪瀾未碧蒲猶短，不見鴛鴦正自由。"]', '["一派溪隨箬下流，春来無处不汀洲。","漪瀾未碧蒲猶短，不见鴛鴦正自由。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a65ca4f-de9c-4841-8687-43ab4f86a1fc', '自遣詩三十首 二十六', '自遣诗三十首 二十六', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山下花明水上曛，一橈青翰破霞文。","越人但愛風流客，繡被何須屬鄂君。"]', '["山下花明水上曛，一橈青翰破霞文。","越人但愛风流客，繡被何須屬鄂君。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十六 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7347f28c-61ad-4266-84f7-7b61cdac2d67', '自遣詩三十首 二十七', '自遣诗三十首 二十七', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["妍華須是占時生，準擬差肩不近情。","佳麗幾時腰不細，荆王辛苦致宮名。"]', '["妍华須是占时生，準擬差肩不近情。","佳丽幾时腰不細，荆王辛苦致宮名。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十七 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1a8fed-61c3-426f-991e-06c8de9514f6', '自遣詩三十首 二十八', '自遣诗三十首 二十八', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["奼女精神似月孤，敢將容易入洪爐。","人間縱道鉛華少，蝶翅新篁未肯無。"]', '["奼女精神似月孤，敢將容易入洪爐。","人间縱道鉛华少，蝶翅新篁未肯無。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十八 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063ab752-d1c2-4e7b-8e54-91642e206717', '自遣詩三十首 二十九', '自遣诗三十首 二十九', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["貞白求丹變姓名，主恩潛助亦無成。","侯家竟換梁天子，王整徒勞作外兵。"]', '["貞白求丹变姓名，主恩潛助亦無成。","侯家竟換梁天子，王整徒勞作外兵。"]', '诗', 'shi', '', NULL, '自遣詩三十首 二十九 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c55f75d-b8ec-47a9-b3f4-440b2177539b', '自遣詩三十首 三十', '自遣诗三十首 三十', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["春雨能膏草木肥，就中林野碧含滋。","唯餘病客相逢背，一夜寒聲減四肢。"]', '["春雨能膏草木肥，就中林野碧含滋。","唯餘病客相逢背，一夜寒声減四肢。"]', '诗', 'shi', '', NULL, '自遣詩三十首 三十 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f862c87-04df-4655-8d1e-d1851a898bad', '別墅懷歸', '別墅懷归', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["東去滄溟百里餘，沿江潮信到吾廬。","就中家在蓬山下，一日堪憑兩寄書。"]', '["东去滄溟百里餘，沿江潮信到吾廬。","就中家在蓬山下，一日堪憑兩寄书。"]', '诗', 'shi', '', NULL, '別墅懷歸 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95983ea-584a-4600-9e8b-d89e4d3eca3a', '野井', '野井', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朱閣前頭露井多，碧梧桐下美人過。","寒泉未必能如此，奈有銀缾素綆何。"]', '["朱閣前头露井多，碧梧桐下美人過。","寒泉未必能如此，奈有銀缾素綆何。"]', '诗', 'shi', '', NULL, '野井 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8ccffc-763c-46fa-91ca-3bf95dc47441', '南征', '南征', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["丞相南征定有無，幕中誰是騁良圖。","遙知賊膽縱橫破，繞帳生犀一萬株。"]', '["丞相南征定有無，幕中誰是騁良圖。","遙知賊膽縱橫破，繞帳生犀一万株。"]', '诗', 'shi', '', NULL, '南征 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b6e401a-5ffd-49e6-9c08-7fbb8056fc82', '北渡', '北渡', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江客柴門枕浪花，鳴機寒艣任嘔啞。","輕舟過去真堪畫，驚起鸕鷀一陣斜。"]', '["江客柴门枕浪花，鳴機寒艣任嘔啞。","轻舟過去真堪畫，驚起鸕鷀一陣斜。"]', '诗', 'shi', '', NULL, '北渡 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a30b7548-6489-4a68-902b-1a6407efd5e5', '夜泊詠棲鴻', '夜泊詠棲鴻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["可憐霜月暫相依，莫向衡陽趁逐飛。","同是江南寒夜客，羽毛單薄稻粱微。"]', '["可怜霜月暫相依，莫向衡陽趁逐飞。","同是江南寒夜客，羽毛單薄稻粱微。"]', '诗', 'shi', '', NULL, '夜泊詠棲鴻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b3f92d-bca6-4157-af28-471830377f4d', '早行', '早行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水寒孤櫂觸天文，直似乘槎去問津。","縱使碧虛無限好，客星名字也愁人。"]', '["水寒孤櫂觸天文，直似乘槎去问津。","縱使碧虛無限好，客星名字也愁人。"]', '诗', 'shi', '', NULL, '早行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19995d5b-2058-4a1b-9c76-6a6101d50638', '木蘭堂', '木蘭堂', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["洞庭波浪渺無津，日日征帆送遠人。","幾度木蘭舟上望，不知元是此花身。"]', '["洞庭波浪渺無津，日日征帆送远人。","幾度木蘭舟上望，不知元是此花身。"]', '诗', 'shi', '', NULL, '木蘭堂 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9b9cb8b-294a-417a-a4cc-ef2320361369', '和襲美春夕陪崔諫議櫻桃園宴', '和襲美春夕陪崔諫議櫻桃园宴', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["佳人芳樹雜春蹊，花外煙濛月漸低。","幾度豔歌清欲轉，流鶯驚起不成棲。"]', '["佳人芳樹杂春蹊，花外煙濛月漸低。","幾度豔歌清欲轉，流鶯驚起不成棲。"]', '诗', 'shi', '', NULL, '和襲美春夕陪崔諫議櫻桃園宴 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08573e06-9ca8-4fa5-afa6-1d27660143d5', '和襲美松江早春', '和襲美松江早春', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["柳下江餐待好風，暫時還得狎漁翁。","一生無事煙波足，唯有沙邊水勃公。"]', '["柳下江餐待好风，暫时還得狎漁翁。","一生無事煙波足，唯有沙邊水勃公。"]', '诗', 'shi', '', NULL, '和襲美松江早春 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('381f7ef1-7b9a-4493-929e-71b93d0c1c77', '和襲美女墳湖', '和襲美女墳湖', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水平波淡遶迴塘，鶴殉人沈萬古傷。","應是離魂雙不得，至今沙上少鴛鴦。"]', '["水平波淡遶迴塘，鹤殉人沈万古傷。","應是離魂雙不得，至今沙上少鴛鴦。"]', '诗', 'shi', '', NULL, '和襲美女墳湖 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60dfc732-a45d-499e-845a-61e80f16a373', '和襲美泰伯廟', '和襲美泰伯廟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["故國城荒德未荒，年年椒奠濕中堂。","邇來父子爭天下，不信人間有讓王。"]', '["故国城荒德未荒，年年椒奠濕中堂。","邇来父子爭天下，不信人间有讓王。"]', '诗', 'shi', '', NULL, '和襲美泰伯廟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffa279bb-440b-4bc1-b837-f1eaa9fa3cf8', '和襲美木蘭院次韻', '和襲美木蘭院次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["苦吟清漏迢迢極，月過花西尚未眠。","猶憶故山欹警枕，夜來嗚咽似流泉。"]', '["苦吟清漏迢迢極，月過花西尚未眠。","猶憶故山欹警枕，夜来嗚咽似流泉。"]', '诗', 'shi', '', NULL, '和襲美木蘭院次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2755618d-b7a3-49cd-9053-ffe848ec06c1', '和襲美重題薔薇', '和襲美重題薔薇', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["穠華自古不得久，況是倚春春已空。","更被夜來風雨惡，滿階狼籍沒多紅。"]', '["穠华自古不得久，況是倚春春已空。","更被夜来风雨惡，满階狼籍沒多紅。"]', '诗', 'shi', '', NULL, '和襲美重題薔薇 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('726f4bb7-d18e-4b1e-beb4-f23abb1ebfb5', '和襲美春夕酒醒', '和襲美春夕酒醒', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["幾年無事傍江湖，醉倒黃公舊酒壚。","覺後不知明月上，滿身花影倩人扶。"]', '["幾年無事傍江湖，醉倒黄公旧酒壚。","覺後不知明月上，满身花影倩人扶。"]', '诗', 'shi', '', NULL, '和襲美春夕酒醒 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('313e5762-6765-4ea3-b42b-e3825eb551c4', '和襲美木蘭後池三詠 重臺蓮花', '和襲美木蘭後池三詠 重台蓮花', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水國煙鄉足芰荷，就中芳瑞此難過。","風情爲與吳王近，紅萼常教一倍多。"]', '["水国煙乡足芰荷，就中芳瑞此难過。","风情爲與吳王近，紅萼常教一倍多。"]', '诗', 'shi', '', NULL, '和襲美木蘭後池三詠 重臺蓮花 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea1091a5-3b3e-47fa-9125-2cfd8c5d9508', '和襲美木蘭後池三詠 浮萍', '和襲美木蘭後池三詠 浮萍', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["晚來風約半池明，重疊侵沙綠罽成。","不用臨池更相笑，最無根蔕是浮名。"]', '["晚来风約半池明，重叠侵沙綠罽成。","不用臨池更相笑，最無根蔕是浮名。"]', '诗', 'shi', '', NULL, '和襲美木蘭後池三詠 浮萍 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400f34be-4bbf-449e-8d31-8c8c821318b0', '和襲美木蘭後池三詠 白蓮', '和襲美木蘭後池三詠 白蓮', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["素蘤多蒙別豔欺，此花真合在瑤池。","還應有恨無人覺，月曉風清欲墮時。"]', '["素蘤多蒙別豔欺，此花真合在瑤池。","還應有恨無人覺，月晓风清欲墮时。"]', '诗', 'shi', '', NULL, '和襲美木蘭後池三詠 白蓮 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d4c576-825d-4c62-aa27-80216fd710f6', '和襲美重題後池', '和襲美重題後池', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曉煙清露暗相和，浴雁浮鷗意緒多。","却是陳王詞賦錯，枉將心事托微波。"]', '["晓煙清露暗相和，浴雁浮鷗意緒多。","却是陳王词賦錯，枉將心事托微波。"]', '诗', 'shi', '', NULL, '和襲美重題後池 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2bcbaa-e4cb-4194-b543-19ce5352966a', '和胥門閑泛', '和胥门闲泛', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["細槳輕撶下白蘋，故城花謝綠陰新。","豈無今日逃名士，試問南塘著屧人。"]', '["細槳轻撶下白蘋，故城花謝綠陰新。","豈無今日逃名士，試问南塘著屧人。"]', '诗', 'shi', '', NULL, '和胥門閑泛 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c89607-bb89-44cf-b2e1-652232775751', '襲美初植松桂偶題', '襲美初植松桂偶題', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["軒陰冉冉移斜日，寒韻泠泠入晚風。","煙格月姿曾不改，至今猶似在山中。"]', '["軒陰冉冉移斜日，寒韻泠泠入晚风。","煙格月姿曾不改，至今猶似在山中。"]', '诗', 'shi', '', NULL, '襲美初植松桂偶題 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3577d4d6-680b-4568-ac9d-2a375b5f0675', '和襲美館娃宮懷古五絕 一', '和襲美館娃宮懷古五絕 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["三千雖衣水犀珠，半夜夫差國暗屠。","猶有八人皆二八，獨教西子占亡吳。"]', '["三千雖衣水犀珠，半夜夫差国暗屠。","猶有八人皆二八，独教西子占亡吳。"]', '诗', 'shi', '', NULL, '和襲美館娃宮懷古五絕 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b1beccf-0444-44f1-b134-ee09277350ef', '和襲美館娃宮懷古五絕 二', '和襲美館娃宮懷古五絕 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一宮花渚漾漣漪，俀墮鴉鬟出繭眉。","可料座中歌舞袖，便將殘節拂降旗。"]', '["一宮花渚漾漣漪，俀墮鴉鬟出繭眉。","可料座中歌舞袖，便將殘節拂降旗。"]', '诗', 'shi', '', NULL, '和襲美館娃宮懷古五絕 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff281e4e-f43f-4475-b3de-e8b824cf7820', '和襲美館娃宮懷古五絕 三', '和襲美館娃宮懷古五絕 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["幾多雲榭倚青冥，越燄燒來一片平。","此地最應沾恨血，至今春草不勻生。"]', '["幾多云榭倚青冥，越燄燒来一片平。","此地最應沾恨血，至今春草不勻生。"]', '诗', 'shi', '', NULL, '和襲美館娃宮懷古五絕 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9a785c-abea-485a-892c-7ce39cc017e9', '和襲美館娃宮懷古五絕 四', '和襲美館娃宮懷古五絕 四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江色分明練繞臺，戰帆遙隔綺疏開。","波神自厭荒淫主，句踐樓船穩帖來。"]', '["江色分明練繞台，戰帆遙隔綺疏开。","波神自厭荒淫主，句踐楼船穩帖来。"]', '诗', 'shi', '', NULL, '和襲美館娃宮懷古五絕 四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7628fd27-a6e2-4947-8245-b12aa668a818', '和襲美館娃宮懷古五絕 五', '和襲美館娃宮懷古五絕 五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["寶袜香綦碎曉塵，亂兵誰惜似花人。","伯勞應是精靈使，猶向殘陽泣暮春。"]', '["寶袜香綦碎晓塵，亂兵誰惜似花人。","伯勞應是精靈使，猶向殘陽泣暮春。"]', '诗', 'shi', '', NULL, '和襲美館娃宮懷古五絕 五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc6b560-9b4b-4458-a401-775d71090413', '和襲美虎丘寺西小溪閑泛三絕 一', '和襲美虎丘寺西小溪闲泛三絕 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["樹號相思枝拂地，鳥語提壺聲滿溪。","雲涯一里千萬曲，直是漁翁行也迷。"]', '["樹號相思枝拂地，鸟語提壺声满溪。","云涯一里千万曲，直是漁翁行也迷。"]', '诗', 'shi', '', NULL, '和襲美虎丘寺西小溪閑泛三絕 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1750b1c9-94ee-414a-811f-6cc812a68dc6', '和襲美虎丘寺西小溪閑泛三絕 二', '和襲美虎丘寺西小溪闲泛三絕 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["荒柳臥波渾似困，宿雲遮塢未全癡。","雲情柳意蕭蕭會，若問諸餘總不知。"]', '["荒柳臥波渾似困，宿云遮塢未全癡。","云情柳意蕭蕭會，若问諸餘總不知。"]', '诗', 'shi', '', NULL, '和襲美虎丘寺西小溪閑泛三絕 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a00127-6217-4e6f-a202-49a62ab725b5', '和襲美虎丘寺西小溪閑泛三絕 三', '和襲美虎丘寺西小溪闲泛三絕 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["每逢孤嶼一倚檝，便欲狂歌同採薇。","任是煙蘿中待月，不妨欹枕扣舷歸。"]', '["每逢孤嶼一倚檝，便欲狂歌同採薇。","任是煙蘿中待月，不妨欹枕扣舷归。"]', '诗', 'shi', '', NULL, '和襲美虎丘寺西小溪閑泛三絕 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a40a60-0040-4cde-b0e8-09a229763d46', '和襲美天竺寺八月十五夜桂子', '和襲美天竺寺八月十五夜桂子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["霜實常聞秋半夜，天台天竺墮雲岑。","如何兩地無人種，却是湘灕是桂林。"]', '["霜實常闻秋半夜，天台天竺墮云岑。","如何兩地無人種，却是湘灕是桂林。"]', '诗', 'shi', '', NULL, '和襲美天竺寺八月十五夜桂子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1654cf68-8d15-4799-aa0f-154eff544789', '戲題襲美書印囊', '戲題襲美书印囊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鵲銜龜顧妙無餘，不愛封侯愛石渠。","應笑休文過萬卷，至今誰道沈家書。"]', '["鵲銜龟顧妙無餘，不愛封侯愛石渠。","應笑休文過万卷，至今誰道沈家书。"]', '诗', 'shi', '', NULL, '戲題襲美書印囊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dcce550-1d79-490f-8e1f-48e09a97deb3', '和襲美釣侶二章 一', '和襲美釣侶二章 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一艇輕撶看曉濤，接䍦拋下漉春醪。","相逢便倚蒹葭泊，更唱菱歌擘蟹螯。"]', '["一艇轻撶看晓濤，接䍦拋下漉春醪。","相逢便倚蒹葭泊，更唱菱歌擘蟹螯。"]', '诗', 'shi', '', NULL, '和襲美釣侶二章 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e37088c-9b5b-4640-b7ed-023521f6b26f', '和襲美釣侶二章 二', '和襲美釣侶二章 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雨後沙虛古岸崩，魚梁移入亂雲層。","歸時月墮汀洲暗，認得妻兒結網燈。"]', '["雨後沙虛古岸崩，鱼梁移入亂云層。","归时月墮汀洲暗，認得妻兒結網灯。"]', '诗', 'shi', '', NULL, '和襲美釣侶二章 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac567c2-efd6-42ff-b2a4-03055e7a407e', '和襲美寄同年韋校書', '和襲美寄同年韋校书', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["萬古風煙滿故都，清才搜括妙無餘。","可中寄與芸香客，便是江南地里書。"]', '["万古风煙满故都，清才搜括妙無餘。","可中寄與芸香客，便是江南地里书。"]', '诗', 'shi', '', NULL, '和襲美寄同年韋校書 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb51486-4eb0-48d5-b773-e412f6696b3e', '和襲美初冬偶作', '和襲美初冬偶作', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["桐下空階疊綠錢，貂裘初綻擁高眠。","小爐低幌還遮掩，酒滴灰香似去年。"]', '["桐下空階叠綠錢，貂裘初綻擁高眠。","小爐低幌還遮掩，酒滴灰香似去年。"]', '诗', 'shi', '', NULL, '和襲美初冬偶作 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9ec6c6-9a9f-40e8-8404-c989fd067785', '襲美醉中寄一壺幷一絕走筆次韻奉酬', '襲美醉中寄一壺幷一絕走笔次韻奉酬', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["酒痕衣上雜莓苔，猶憶紅螺一兩杯。","正被遶籬荒菊笑，日斜還有白衣來。"]', '["酒痕衣上杂莓苔，猶憶紅螺一兩杯。","正被遶籬荒菊笑，日斜還有白衣来。"]', '诗', 'shi', '', NULL, '襲美醉中寄一壺幷一絕走筆次韻奉酬 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f515636-417f-4ce2-9885-dd0d4f771cdf', '再和次韻', '再和次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["堦下飢禽啄嫩苔，野人方倒病中杯。","寒蔬賣却還沽喫，可有金貂換得來。"]', '["堦下飢禽啄嫩苔，野人方倒病中杯。","寒蔬賣却還沽喫，可有金貂換得来。"]', '诗', 'shi', '', NULL, '再和次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96fd1816-81cf-4b81-89ed-986a68d6b580', '和襲美重玄寺雙矮檜', '和襲美重玄寺雙矮檜', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["可憐煙刺是青螺，如到雙林誤禮多。","更憶早秋登北固，海門蒼翠出晴波。"]', '["可怜煙刺是青螺，如到雙林誤禮多。","更憶早秋登北固，海门蒼翠出晴波。"]', '诗', 'shi', '', NULL, '和襲美重玄寺雙矮檜 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cdf3421-5446-4a46-a570-510fb4b04b5b', '醉中戲贈襲美', '醉中戲贈襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["南北風流舊不同，傖吳今日若相通。","病來猶伴金杯滿，欲得人呼小褚公。"]', '["南北风流旧不同，傖吳今日若相通。","病来猶伴金杯满，欲得人呼小褚公。"]', '诗', 'shi', '', NULL, '醉中戲贈襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eced53c7-c14f-4162-bdf8-288f66004a5b', '潤卿遺青䭀飯兼之一絕聊用荅謝', '潤卿遺青䭀飯兼之一絕聊用荅謝', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["舊聞香積金仙食，今見青精玉斧餐。","自笑鏡中無骨錄，可能飛上紫雲端。"]', '["旧闻香積金仙食，今见青精玉斧餐。","自笑镜中無骨錄，可能飞上紫云端。"]', '诗', 'shi', '', NULL, '潤卿遺青䭀飯兼之一絕聊用荅謝 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09daacc-508c-47aa-90e1-010967b8547d', '文讌招潤卿博士辭以道侶將至一絕寄之', '文讌招潤卿博士辞以道侶將至一絕寄之', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["仙客何時下鶴翎，方瞳如水腦華清。","不過傳達楊君夢，從許人間小兆聽。"]', '["仙客何时下鹤翎，方瞳如水腦华清。","不過傳達楊君梦，從許人间小兆听。"]', '诗', 'shi', '', NULL, '文讌招潤卿博士辭以道侶將至一絕寄之 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c520bf77-4fcf-4d8c-bae3-30d1520e2877', '再招', '再招', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["遙知道侶談玄次，又是文交麗事時。","雖是寒輕雲重日，也留花簟待徐摛。"]', '["遙知道侶談玄次，又是文交丽事时。","雖是寒轻云重日，也留花簟待徐摛。"]', '诗', 'shi', '', NULL, '再招 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('121897d3-e790-471b-8126-4550c254d016', '玩金鸂𪆟戲贈襲美', '玩金鸂𪆟戲贈襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曾向溪邊泊暮雲，至今猶憶浪花羣。","不知鏤羽凝香霧，堪與鴛鴦覺後聞。"]', '["曾向溪邊泊暮云，至今猶憶浪花羣。","不知鏤羽凝香霧，堪與鴛鴦覺後闻。"]', '诗', 'shi', '', NULL, '玩金鸂𪆟戲贈襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc003682-c409-4f08-a836-b1792fad07c1', '子規一首', '子規一首', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["碧竿微露月玲瓏，謝豹傷心獨叫風。","高處已應聞滴血，山榴一夜幾枝紅。"]', '["碧竿微露月玲瓏，謝豹傷心独叫风。","高处已應闻滴血，山榴一夜幾枝紅。"]', '诗', 'shi', '', NULL, '子規一首 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e06fcc07-fe70-4748-a51e-ecc0eabe9e0f', '寄題天台國清寺齊梁體', '寄題天台国清寺齊梁體', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["峰帶樓臺天外立，明河色近罘罳濕。","松間石上定僧寒，半夜楢溪水聲急。"]', '["峰带楼台天外立，明河色近罘罳濕。","松间石上定僧寒，半夜楢溪水声急。"]', '诗', 'shi', '', NULL, '寄題天台國清寺齊梁體 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284295e3-3fc4-4afb-a38b-d5ae9bccc0b1', '奉和諫議酬先輩霜菊', '奉和諫議酬先輩霜菊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["紫莖芳豔照西風，秖怕霜華掠斷叢。","爭奈病夫難強飲，應須速自召車公。"]', '["紫莖芳豔照西风，秖怕霜华掠斷叢。","爭奈病夫难強饮，應須速自召车公。"]', '诗', 'shi', '', NULL, '奉和諫議酬先輩霜菊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e12cf063-dfc5-4d66-83de-3a1ccaca5193', '和襲美詠臯橋', '和襲美詠臯橋', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["橫截春流架斷虹，凭欄猶思五噫風。","今來未必非梁孟，却是無人斷伯通。"]', '["橫截春流架斷虹，凭欄猶思五噫风。","今来未必非梁孟，却是無人斷伯通。"]', '诗', 'shi', '', NULL, '和襲美詠臯橋 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7c58bd-b591-4b1a-b837-50d631129ea6', '和襲美悼鶴', '和襲美悼鹤', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["酆都香稻字重思，遙想飛魂去未飢。","爭奈野鴉無數健，黃昏來占舊棲枝。"]', '["酆都香稻字重思，遙想飞魂去未飢。","爭奈野鴉無數健，黄昏来占旧棲枝。"]', '诗', 'shi', '', NULL, '和襲美悼鶴 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654209a2-638e-476f-bce6-ec736230d006', '和醉中襲美先起次韻', '和醉中襲美先起次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["莫唱豔歌凝翠黛，已通仙籍在金閨。","他時若寄相思淚，紅粉痕應伴紫泥。"]', '["莫唱豔歌凝翠黛，已通仙籍在金閨。","他时若寄相思泪，紅粉痕應伴紫泥。"]', '诗', 'shi', '', NULL, '和醉中襲美先起次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30835f4-a653-4a52-a6a2-19031e9796d1', '和襲美酒病偶作次韻', '和襲美酒病偶作次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["柳疎桐下晚窗明，秖有微風爲析酲。","唯欠白綃籠解散，洛生閑詠兩三聲。"]', '["柳疎桐下晚窗明，秖有微风爲析酲。","唯欠白綃籠解散，洛生闲詠兩三声。"]', '诗', 'shi', '', NULL, '和襲美酒病偶作次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5400406f-949f-4793-8c52-8cb59b47ac61', '憶白菊', '憶白菊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["稚子書傳白菊開，西成相滯未容迴。","月明階下窗紗薄，多少清香透入來。"]', '["稚子书傳白菊开，西成相滯未容迴。","月明階下窗紗薄，多少清香透入来。"]', '诗', 'shi', '', NULL, '憶白菊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da3521b-4d62-4098-8f17-30b425ccd717', '和同潤卿寒夜訪襲美各惜其志次韻', '和同潤卿寒夜訪襲美各惜其志次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["醉韻飄飄不可親，掉頭吟側華陽巾。","如能跂脚南窗下，便是羲皇世上人。"]', '["醉韻飄飄不可親，掉头吟側华陽巾。","如能跂脚南窗下，便是羲皇世上人。"]', '诗', 'shi', '', NULL, '和同潤卿寒夜訪襲美各惜其志次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb90013b-eda3-4f43-825b-b5fe3820fdf9', '和襲美寒夜文讌潤卿有期不至', '和襲美寒夜文讌潤卿有期不至', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["細雨輕觴玉漏終，上清詞句落吟中。","松齋一夜懷貞白，霜外空聞五粒風。"]', '["細雨轻觴玉漏終，上清词句落吟中。","松斋一夜懷貞白，霜外空闻五粒风。"]', '诗', 'shi', '', NULL, '和襲美寒夜文讌潤卿有期不至 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05dfb7df-5b29-48bb-a9e7-e8e9c59d3904', '移石盆', '移石盆', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["移得龍泓瀲灩寒，月輪初下白雲端。","無人盡日澄心坐，倒影新篁一兩竿。"]', '["移得龙泓瀲灩寒，月輪初下白云端。","無人尽日澄心坐，倒影新篁一兩竿。"]', '诗', 'shi', '', NULL, '移石盆 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54c3d5c8-adbc-4b44-a288-1f8305e727bb', '石竹花詠', '石竹花詠', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曾看南朝畫國娃，古蘿衣上碎明霞。","而今莫共金錢鬬，買却春風是此花。"]', '["曾看南朝畫国娃，古蘿衣上碎明霞。","而今莫共金錢鬬，買却春风是此花。"]', '诗', 'shi', '', NULL, '石竹花詠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd3ffb9-9c79-4ac4-aa3f-fd5d3f03b1d7', '和襲美友人許惠酒以詩徵之', '和襲美友人許惠酒以诗徵之', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["凍醪初漉嫩如春，輕蟻漂漂雜蘂塵。","得伴方平同一醉，明朝應作蔡經身。"]', '["凍醪初漉嫩如春，轻蟻漂漂杂蘂塵。","得伴方平同一醉，明朝應作蔡經身。"]', '诗', 'shi', '', NULL, '和襲美友人許惠酒以詩徵之 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737a4ee9-f795-4d91-91e9-81f656854d28', '聞圓載上人挾儒書洎釋典歸日本國更作一絕以送', '闻圓載上人挾儒书洎釋典归日本国更作一絕以送', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["九流三藏一時傾，萬軸光凌渤澥聲。","從此遺編東去後，却應荒外有諸生。"]', '["九流三藏一时傾，万軸光凌渤澥声。","從此遺編东去後，却應荒外有諸生。"]', '诗', 'shi', '', NULL, '聞圓載上人挾儒書洎釋典歸日本國更作一絕以送 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130d429c-25a2-454e-9282-d80949d2c851', '閑吟', '闲吟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["閑吟料得三更盡，始把孤燈背竹窗。","一夜西風高浪起，不教歸夢過寒江。"]', '["闲吟料得三更尽，始把孤灯背竹窗。","一夜西风高浪起，不教归梦過寒江。"]', '诗', 'shi', '', NULL, '閑吟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a652563c-bb47-4375-881d-f448afc0e86e', '秘色越器', '秘色越器', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["九秋風露越窑開，奪得千峰翠色來。","好向中宵盛沆瀣，共嵇中散鬬遺杯。"]', '["九秋风露越窑开，奪得千峰翠色来。","好向中宵盛沆瀣，共嵇中散鬬遺杯。"]', '诗', 'shi', '', NULL, '秘色越器 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a1db59-2468-478f-bb72-b8b1be10021c', '景陽宮井', '景陽宮井', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["古堞煙埋宮井樹，陳主吳姬墮泉處。","舜沒蒼梧萬里雲，却不聞將二妃去。"]', '["古堞煙埋宮井樹，陳主吳姬墮泉处。","舜沒蒼梧万里云，却不闻將二妃去。"]', '诗', 'shi', '', NULL, '景陽宮井 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b9d67c3-b517-4b15-bc75-b97a1306eb3b', '江南二首 一', '江南二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["便風船尾香秔熟，細雨層頭赤鯉跳。","待得江餐閑望足，日斜方動木蘭橈。"]', '["便风船尾香秔熟，細雨層头赤鯉跳。","待得江餐闲望足，日斜方动木蘭橈。"]', '诗', 'shi', '', NULL, '江南二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3073e82-5eb9-4bf3-ae46-1482a2fc1a7c', '江南二首 二', '江南二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["村邊紫豆花垂次，岸上紅梨葉戰初。","莫怪煙中重回首，酒家青紵一行書。"]', '["村邊紫豆花垂次，岸上紅梨葉戰初。","莫怪煙中重回首，酒家青紵一行书。"]', '诗', 'shi', '', NULL, '江南二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330ea0fb-814c-4be7-b109-8981f700a931', '溪思雨中', '溪思雨中', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雨映前山萬絇絲，樐聲衝破似鳴機。","無端織得愁成段，堪作騷人酒病衣。"]', '["雨映前山万絇絲，樐声衝破似鳴機。","無端织得愁成段，堪作騷人酒病衣。"]', '诗', 'shi', '', NULL, '溪思雨中 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65accb14-35d6-4061-9a1b-f1e2bb8a4de7', '江城夜泊', '江城夜泊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["漏移寒箭丁丁急，月挂虛弓靄靄明。","此夜離魂堪射斷，更須江笛兩三聲。"]', '["漏移寒箭丁丁急，月挂虛弓靄靄明。","此夜離魂堪射斷，更須江笛兩三声。"]', '诗', 'shi', '', NULL, '江城夜泊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4c2019-e289-4a7e-b809-6a281645c400', '宮人斜', '宮人斜', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["草著愁煙似不春，晚鶯哀怨問行人。","須知一種埋香骨，猶勝昭君作虜塵。"]', '["草著愁煙似不春，晚鶯哀怨问行人。","須知一種埋香骨，猶勝昭君作虜塵。"]', '诗', 'shi', '', NULL, '宮人斜 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe90b63e-fdda-4c58-b2c9-87101f845d80', '送棊客', '送棊客', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["滿目山川似勢棊，況當秋雁正斜飛。","金門若召羊玄保，賭取江東太守歸。"]', '["满目山川似勢棊，況當秋雁正斜飞。","金门若召羊玄保，賭取江东太守归。"]', '诗', 'shi', '', NULL, '送棊客 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5317d7ab-bd36-43c7-9074-2ffe3124d13f', '漢宮詞', '漢宮词', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["招靈閣上霓旌絕，柏梁臺中珠翠稠。","一身三十六宮夜，露滴玉盤青桂秋。"]', '["招靈閣上霓旌絕，柏梁台中珠翠稠。","一身三十六宮夜，露滴玉盤青桂秋。"]', '诗', 'shi', '', NULL, '漢宮詞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b041518e-6fc3-46f2-aad6-cef0e7815c0d', '上清', '上清', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["玉林風露寂寥清，仙妃對月閑吹笙。","新篁冷澀曲未盡，細拂雲枝棲鳳驚。"]', '["玉林风露寂寥清，仙妃对月闲吹笙。","新篁冷澀曲未尽，細拂云枝棲鳳驚。"]', '诗', 'shi', '', NULL, '上清 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae25367e-d401-44ba-9b22-141298d8b097', '秋荷', '秋荷', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["蒲茸承露有佳色，茭葉束煙如效顰。","盈盈一水不得渡，冷翠遺香愁向人。"]', '["蒲茸承露有佳色，茭葉束煙如效顰。","盈盈一水不得渡，冷翠遺香愁向人。"]', '诗', 'shi', '', NULL, '秋荷 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f53213f-a551-49e4-81e3-b2a6f0e46c86', '有別二首 一', '有別二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["且將絲䋏繫蘭舟，醉下煙汀減去愁。","江上有樓君莫上，落花隨浪正東流。"]', '["且將絲䋏繫蘭舟，醉下煙汀減去愁。","江上有楼君莫上，落花隨浪正东流。"]', '诗', 'shi', '', NULL, '有別二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c427e1c-b5ce-438b-8859-c90826479c4d', '有別二首 二', '有別二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["池上已看鶯舌默，雲間應即雁翰開。","唯愁別後當風立，萬樹將秋入恨來。"]', '["池上已看鶯舌默，云间應即雁翰开。","唯愁別後當风立，万樹將秋入恨来。"]', '诗', 'shi', '', NULL, '有別二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b36ef015-d2ec-48f9-af9b-1e99efffa0b4', '病中曉思', '病中晓思', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["月墮霜西竹井寒，轆轤絲凍下缾難。","幽人病久渾成渴，愁見龍書一鼎乾。"]', '["月墮霜西竹井寒，轆轤絲凍下缾难。","幽人病久渾成渴，愁见龙书一鼎乾。"]', '诗', 'shi', '', NULL, '病中曉思 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91884e1f-1dde-409b-b121-a810b5adbd35', '送友人之湖上', '送友人之湖上', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["故人溪上有漁舟，竿倚風蘋夜不收。","欲寄一函聊問訊，洪喬寧作置書郵。"]', '["故人溪上有漁舟，竿倚风蘋夜不收。","欲寄一函聊问訊，洪喬寧作置书郵。"]', '诗', 'shi', '', NULL, '送友人之湖上 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70fc628c-69f5-4cd2-aef8-07691994652e', '寒日逢僧', '寒日逢僧', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["瘦脛高褰梵屧輕，野塘風勁錫環鳴。","如何不向深山裏，坐擁閑雲過一生。"]', '["瘦脛高褰梵屧轻，野塘风勁錫环鳴。","如何不向深山裏，坐擁闲云過一生。"]', '诗', 'shi', '', NULL, '寒日逢僧 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e964cd0-ecf3-4104-920e-084a0648228c', '冬柳', '冬柳', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["柳汀斜對野人窗，零落衰條傍曉江。","正是霜風飄斷處，寒鷗驚起一雙雙。"]', '["柳汀斜对野人窗，零落衰條傍晓江。","正是霜风飄斷处，寒鷗驚起一雙雙。"]', '诗', 'shi', '', NULL, '冬柳 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7bc9683-48bc-4e86-a48f-22def1268427', '寄友人', '寄友人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["敬亭寒夜溪聲裏，同聽先生講太玄。","上得雲梯不回首，釣竿猶在五湖邊。"]', '["敬亭寒夜溪声裏，同听先生講太玄。","上得云梯不回首，釣竿猶在五湖邊。"]', '诗', 'shi', '', NULL, '寄友人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311c5e11-e9e6-46d0-829c-7809f3db9098', '島樹', '島樹', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["波濤漱苦盤根淺，風雨飄多著葉遲。","迥出孤煙殘照裏，鷺鶿相對立高枝。"]', '["波濤漱苦盤根淺，风雨飄多著葉遲。","迥出孤煙殘照裏，鷺鶿相对立高枝。"]', '诗', 'shi', '', NULL, '島樹 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768baf3b-065d-4ee6-a91c-65ed8aea9e71', '頭陀僧', '头陀僧', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["萬峰圍繞一峰深，向此長修苦行心。","自埽雪中歸鹿跡，天明恐被獵人尋。"]', '["万峰圍繞一峰深，向此长修苦行心。","自埽雪中归鹿跡，天明恐被獵人尋。"]', '诗', 'shi', '', NULL, '頭陀僧 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68e99d2-5bb4-45e2-9d13-f8cdeda4ba80', '晚渡', '晚渡', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["半波風雨半波晴，漁曲飄秋野調清。","各樣蓮船逗村去，笠簷衰袂有殘聲。"]', '["半波风雨半波晴，漁曲飄秋野調清。","各樣蓮船逗村去，笠簷衰袂有殘声。"]', '诗', 'shi', '', NULL, '晚渡 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eee40627-2ad8-49c3-a04a-9ced056e6125', '贈老僧二首 一', '贈老僧二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["枯貌自同霜裏木，餘生唯指佛前燈。","少時寫得坐禪影，今見問人何處僧。"]', '["枯貌自同霜裏木，餘生唯指佛前灯。","少时寫得坐禪影，今见问人何处僧。"]', '诗', 'shi', '', NULL, '贈老僧二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6112110-7b97-4aa0-92b2-bbd7e127b169', '贈老僧二首 二', '贈老僧二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["自有家山供衲線，不離溪曲取菴茅。","舊曾聞說林中鳥，定後長來頂上巢。"]', '["自有家山供衲線，不離溪曲取菴茅。","旧曾闻说林中鸟，定後长来頂上巢。"]', '诗', 'shi', '', NULL, '贈老僧二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ffd34bd-0cd6-46bc-bcb4-961314b0d15f', '憶山泉', '憶山泉', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一夜寒聲來夢裏，平明著屐到聲邊。","心期盛夏同過此，脫却荷衣石上眠。"]', '["一夜寒声来梦裏，平明著屐到声邊。","心期盛夏同過此，脫却荷衣石上眠。"]', '诗', 'shi', '', NULL, '憶山泉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e45b6ee-67b5-4eaa-829d-77db212692a4', '白芙蓉', '白芙蓉', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["澹然相對却成勞，月染風裁箇箇高。","似說玉皇親謫墮，至今猶著水霜袍。"]', '["澹然相对却成勞，月染风裁箇箇高。","似说玉皇親謫墮，至今猶著水霜袍。"]', '诗', 'shi', '', NULL, '白芙蓉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c2d3240-245c-4050-9c04-cba2eaba7557', '嚴光釣臺', '嚴光釣台', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["片帆竿外揖清風，石立雲孤萬古中。","不是狂奴爲故態，仲華爭得黑頭公。"]', '["片帆竿外揖清风，石立云孤万古中。","不是狂奴爲故態，仲华爭得黑头公。"]', '诗', 'shi', '', NULL, '嚴光釣臺 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ab0b2a-2853-4bdb-a5d7-945ce0064ede', '讀陳拾遺集', '读陳拾遺集', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["蓬顆何時與恨平，蜀江衣帶蜀山輕。","尋聞騎士梟黃祖，自是無人祭禰衡。"]', '["蓬顆何时與恨平，蜀江衣带蜀山轻。","尋闻騎士梟黄祖，自是無人祭禰衡。"]', '诗', 'shi', '', NULL, '讀陳拾遺集 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b29f92-9053-465d-a3da-97c4b8cad515', '吳宮懷古', '吳宮懷古', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["香逕長洲盡棘叢，奢雲豔雨秖悲風。","吳王事事須亡國，未必西施勝六宮。"]', '["香逕长洲尽棘叢，奢云豔雨秖悲风。","吳王事事須亡国，未必西施勝六宮。"]', '诗', 'shi', '', NULL, '吳宮懷古 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfda4067-e9c7-4c31-a3f8-1beeeaee6148', '送琴客之建康', '送琴客之建康', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["蕙風杉露共泠泠，三峽寒泉漱玉清。","君到南朝訪遺事，柳家雙鎖舊知名。"]', '["蕙风杉露共泠泠，三峽寒泉漱玉清。","君到南朝訪遺事，柳家雙鎖旧知名。"]', '诗', 'shi', '', NULL, '送琴客之建康 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e516d79d-ad48-4da5-a082-9968c86dd605', '閨怨', '閨怨', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["白袷行人又遠遊，日斜空上映花樓。","愁絲墮絮相逢著，絆惹春風卒未休。"]', '["白袷行人又远游，日斜空上映花楼。","愁絲墮絮相逢著，絆惹春风卒未休。"]', '诗', 'shi', '', NULL, '閨怨 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9733224-1030-4815-ad10-3cabb7495773', '丁香', '丁香', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江上悠悠人不問，十年雲外醉中身。","殷勤解却丁香結，縱放繁枝散誕春。"]', '["江上悠悠人不问，十年云外醉中身。","殷勤解却丁香結，縱放繁枝散誕春。"]', '诗', 'shi', '', NULL, '丁香 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04420bf-009a-4a6c-be29-2d78d01ad9fd', '種蒲', '種蒲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["杜若溪邊手自移，旋抽煙劒碧參差。","何時織得孤帆去，懸向秋風訪所思。"]', '["杜若溪邊手自移，旋抽煙劒碧參差。","何时织得孤帆去，懸向秋风訪所思。"]', '诗', 'shi', '', NULL, '種蒲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7118591b-a3ef-4d85-87ed-28c35721910a', '范蠡', '范蠡', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["平吳專越禍胎深，豈是功成有去心。","句踐不知嫌鳥喙，歸來猶自鑄良金。"]', '["平吳專越禍胎深，豈是功成有去心。","句踐不知嫌鸟喙，归来猶自鑄良金。"]', '诗', 'shi', '', NULL, '范蠡 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febecdd8-ee32-4c9b-a64e-6dad0db84062', '山僧二首 一', '山僧二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山蘚幾重生草履，澗泉長自滿銅缾。","時將如意敲眠虎，遣向林間坐聽經。"]', '["山蘚幾重生草履，澗泉长自满銅缾。","时將如意敲眠虎，遣向林间坐听經。"]', '诗', 'shi', '', NULL, '山僧二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e612149d-2039-4552-be6c-d06e09f371bd', '山僧二首 二', '山僧二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一夏不離蒼島上，秋來頻話石城南。","思歸瀑布聲前坐，却把松枝拂舊菴。"]', '["一夏不離蒼島上，秋来頻話石城南。","思归瀑布声前坐，却把松枝拂旧菴。"]', '诗', 'shi', '', NULL, '山僧二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f3e96e-fe6c-4966-9520-0fe3b3ae781f', '上雲樂', '上云乐', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["青絲作筰桂爲船，白兔搗藥蝦蟇丸。","便浮天漢泊星渚，回首笑君承露盤。"]', '["青絲作筰桂爲船，白兔捣藥蝦蟇丸。","便浮天漢泊星渚，回首笑君承露盤。"]', '诗', 'shi', '', NULL, '上雲樂 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12736d5-05bf-4cb3-9a43-fb6c1812edb1', '新秋雜題六首 眠', '新秋杂題六首 眠', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一簟臨窗薤葉秋，小簾風蕩半離鉤。","魂清雨急夢難到，身在五湖波上頭。"]', '["一簟臨窗薤葉秋，小簾风蕩半離鉤。","魂清雨急梦难到，身在五湖波上头。"]', '诗', 'shi', '', NULL, '新秋雜題六首 眠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de658e31-f157-412a-ae65-78327c2191ea', '新秋雜題六首 行', '新秋杂題六首 行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["尋人直到月塢北，覓鶴便過雲峰西。","只今猶有疎野調，但繞莓苔風雨畦。"]', '["尋人直到月塢北，覓鹤便過云峰西。","只今猶有疎野調，但繞莓苔风雨畦。"]', '诗', 'shi', '', NULL, '新秋雜題六首 行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2123d5a-1067-4302-b720-5ee00bb410b2', '新秋雜題六首 倚', '新秋杂題六首 倚', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["橘下凝情香染巾，竹邊留思露搖身。","背煙垂首盡日立，憶得山中無事人。"]', '["橘下凝情香染巾，竹邊留思露搖身。","背煙垂首尽日立，憶得山中無事人。"]', '诗', 'shi', '', NULL, '新秋雜題六首 倚 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d620b86-c0a1-4f60-a284-e27ec5d36010', '新秋雜題六首 吟', '新秋杂題六首 吟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["憶山搖膝石上晚，懷古掉頭溪畔涼。","有時得句一聲發，驚起鷺鶿和夕陽。"]', '["憶山搖膝石上晚，懷古掉头溪畔涼。","有时得句一声發，驚起鷺鶿和夕陽。"]', '诗', 'shi', '', NULL, '新秋雜題六首 吟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29092c62-c99d-46aa-86a3-d7829e696f98', '新秋雜題六首 食', '新秋杂題六首 食', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["日午空齋帶睡痕，水蔬山藥薦盤[飧]。","林烏信我無機事，長到而今下石盆。"]', '["日午空斋带睡痕，水蔬山藥薦盤[飧]。","林烏信我無機事，长到而今下石盆。"]', '诗', 'shi', '', NULL, '新秋雜題六首 食 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c7ef4e1-ce3d-4237-8b21-3b5f85ad86de', '新秋雜題六首 坐', '新秋杂題六首 坐', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["偶避蟬聲來隙地，忽隨鴻影入遼天。","閑僧不會寂寥意，道學西方人坐禪。"]', '["偶避蟬声来隙地，忽隨鴻影入遼天。","闲僧不會寂寥意，道学西方人坐禪。"]', '诗', 'shi', '', NULL, '新秋雜題六首 坐 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a92f96c-4e74-41a3-adf3-045c0a9d9f40', '新沙', '新沙', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["渤澥聲中漲小隄，官家知後海鷗知。","蓬萊有路教人到，應亦年年稅紫芝。"]', '["渤澥声中漲小隄，官家知後海鷗知。","蓬萊有路教人到，應亦年年稅紫芝。"]', '诗', 'shi', '', NULL, '新沙 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8448c893-1619-40dc-85e7-2bc0a3ee289f', '鄴宮詞二首 一', '鄴宮词二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魏武平生不好香，楓膠蕙炷潔宮房。","可知遺令非前事，却有餘薰在繡囊。"]', '["魏武平生不好香，楓膠蕙炷潔宮房。","可知遺令非前事，却有餘薰在繡囊。"]', '诗', 'shi', '', NULL, '鄴宮詞二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f697f55e-5316-4cd0-9bd5-aaf3f3613dbf', '鄴宮詞二首 二', '鄴宮词二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["花飛蝶駭不愁人，水殿雲廊別置春。","曉日靚妝千騎女，白櫻桃下紫綸巾。"]', '["花飞蝶駭不愁人，水殿云廊別置春。","晓日靚妝千騎女，白櫻桃下紫綸巾。"]', '诗', 'shi', '', NULL, '鄴宮詞二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce9becd7-4b4e-4c26-898d-96f6b95c18b4', '古別離', '古別離', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["仙人左手把長箭，欲射日烏烏不棲。","何事離情畏明發，一心唯恨汝南雞。"]', '["仙人左手把长箭，欲射日烏烏不棲。","何事離情畏明發，一心唯恨汝南雞。"]', '诗', 'shi', '', NULL, '古別離 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7abaf8c9-8e07-48b7-9449-a7e0c2a148a0', '高道士', '高道士', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["峨眉道士風骨峻，手把玉皇書一通。","東遊借得琴高鯉，騎人蓬萊清淺中。"]', '["峨眉道士风骨峻，手把玉皇书一通。","东游借得琴高鯉，騎人蓬萊清淺中。"]', '诗', 'shi', '', NULL, '高道士 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f610ef74-1695-402a-98ec-e39c9c1623c5', '蔬食', '蔬食', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["孔融不要留殘膾，庾悅無端恡子鵝。","香稻熟來秋菜嫩，伴僧餐了聽雲和。"]', '["孔融不要留殘膾，庾悅無端恡子鵝。","香稻熟来秋菜嫩，伴僧餐了听云和。"]', '诗', 'shi', '', NULL, '蔬食 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a000bc-c6d5-4161-9b85-36d76a4895fa', '寄遠', '寄远', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["縹梨花謝鶯口喫，黃犢少年人未歸。","畫扇紅弦相掩映，獨看斜月下簾衣。"]', '["縹梨花謝鶯口喫，黄犢少年人未归。","畫扇紅弦相掩映，独看斜月下簾衣。"]', '诗', 'shi', '', NULL, '寄遠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c63df6-b94b-4054-ab86-eac20fc4a4e2', '山中僧', '山中僧', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["手關一室翠微裏，日暮白雲棲半間。","白雲朝出天際去，若比老僧猶未閑。"]', '["手关一室翠微裏，日暮白云棲半间。","白云朝出天際去，若比老僧猶未闲。"]', '诗', 'shi', '', NULL, '山中僧 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07dbca08-b1e9-48a5-8636-99722e6eb4dc', '洞宮秋夕', '洞宮秋夕', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["濃霜打葉落地聲，南溪石泉細泠泠。","洞宮寂寞人不去，坐見月生雲母屏。"]', '["濃霜打葉落地声，南溪石泉細泠泠。","洞宮寂寞人不去，坐见月生云母屏。"]', '诗', 'shi', '', NULL, '洞宮秋夕 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6989689-c57f-49c9-839d-2bba39cf0d27', '連昌宮詞二首 門', '連昌宮词二首 门', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["金鋪零落獸鐶空，斜揜雙扉細草中。","日暮鳥歸宮樹綠，不聞鴉軋閉春風。"]', '["金鋪零落獸鐶空，斜揜雙扉細草中。","日暮鸟归宮樹綠，不闻鴉軋閉春风。"]', '诗', 'shi', '', NULL, '連昌宮詞二首 門 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0239690b-456f-4a5b-a455-2006802e7865', '連昌宮詞二首 階', '連昌宮词二首 階', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["草沒苔封疊翠斜，墜紅千葉擁殘霞。","年年直爲秋霖苦，滴陷青珉隱起花。"]', '["草沒苔封叠翠斜，墜紅千葉擁殘霞。","年年直爲秋霖苦，滴陷青珉隐起花。"]', '诗', 'shi', '', NULL, '連昌宮詞二首 階 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b374441-66b2-4933-93ab-5b34bfea6461', '懷宛陵舊遊', '懷宛陵旧游', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["陵陽佳地昔年遊，謝朓青山李白樓。","唯有日斜溪上思，酒旗風影落春流。"]', '["陵陽佳地昔年游，謝朓青山李白楼。","唯有日斜溪上思，酒旗风影落春流。"]', '诗', 'shi', '', NULL, '懷宛陵舊遊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e38d0d-17f1-4345-8f78-bbfc024d1be8', '松石曉景圖', '松石晓景圖', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["霜骨雲根慘澹愁，宿煙封著未全收。","將歸與說文通後，寫得松江岸上秋。"]', '["霜骨云根慘澹愁，宿煙封著未全收。","將归與说文通後，寫得松江岸上秋。"]', '诗', 'shi', '', NULL, '松石曉景圖 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e5f988-4a76-452a-9733-36167acc0325', '釣車', '釣车', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["小輪輕線妙無雙，曾伴幽人酒一缸。","洛客見詩如有問，輾煙衝雨過桐江。"]', '["小輪轻線妙無雙，曾伴幽人酒一缸。","洛客见诗如有问，輾煙衝雨過桐江。"]', '诗', 'shi', '', NULL, '釣車 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b53269-8685-4517-964b-384ea3ea1ac5', '漉酒巾', '漉酒巾', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["靖節高風不可攀，此巾猶墜凍醪間。","偏宜雪夜山中戴，認取時情與醉顏。"]', '["靖節高风不可攀，此巾猶墜凍醪间。","偏宜雪夜山中戴，認取时情與醉顏。"]', '诗', 'shi', '', NULL, '漉酒巾 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed161f9-9524-40cd-8e40-c5a6aba45589', '華陽巾', '华陽巾', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["蓮花峰下得佳名，雲褐相兼上鶴翎。","須是古壇秋霽後，靜焚香炷禮寒星。"]', '["蓮花峰下得佳名，云褐相兼上鹤翎。","須是古壇秋霽後，静焚香炷禮寒星。"]', '诗', 'shi', '', NULL, '華陽巾 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9788800b-ab08-4c78-9ceb-26d4b7045001', '方響', '方响', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["擊霜寒玉亂丁丁，花[底]秋風拂坐生。","王母閑看漢天子，滿猗蘭殿佩環聲。"]', '["擊霜寒玉亂丁丁，花[底]秋风拂坐生。","王母闲看漢天子，满猗蘭殿佩环声。"]', '诗', 'shi', '', NULL, '方響 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c68e56a-b8ce-4574-ab1d-94a8ea337501', '白鷺', '白鷺', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雪然飛下立蒼苔，應伴江鷗拒我來。","見欲扁舟搖蕩去，倩君先作水雲媒。"]', '["雪然飞下立蒼苔，應伴江鷗拒我来。","见欲扁舟搖蕩去，倩君先作水云媒。"]', '诗', 'shi', '', NULL, '白鷺 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb58f26-6891-4129-a052-5e36a34ae316', '溪行', '溪行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["晚天寒雨上灘時，他已揚舲我尚遲。","自是檣低帆幅少，溪風終不兩般吹。"]', '["晚天寒雨上灘时，他已揚舲我尚遲。","自是檣低帆幅少，溪风終不兩般吹。"]', '诗', 'shi', '', NULL, '溪行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1c9f22-a566-451c-b593-1fe9b79b2ab3', '太湖叟', '太湖叟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["細槳輕船賣石歸，酒痕狼籍徧苔衣。","攻車戰艦繁如織，不肯回頭問是非。"]', '["細槳轻船賣石归，酒痕狼籍徧苔衣。","攻车戰艦繁如织，不肯回头问是非。"]', '诗', 'shi', '', NULL, '太湖叟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5825c218-af6b-458e-a1ce-c6df37a0049f', '荅友人', '荅友人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["荆卿雄骨化爲塵，燕市應無共飲人。","能說鷫鸘來換酒，五湖賒與一年春。"]', '["荆卿雄骨化爲塵，燕市應無共饮人。","能说鷫鸘来換酒，五湖賒與一年春。"]', '诗', 'shi', '', NULL, '荅友人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0b079b-4662-4e48-a67e-7a5fa4a31813', '偶作', '偶作', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["酒信巧爲繰病緒，花音長作嫁愁媒。","也知愁病堪回避，爭奈流鶯喚起來。"]', '["酒信巧爲繰病緒，花音长作嫁愁媒。","也知愁病堪回避，爭奈流鶯喚起来。"]', '诗', 'shi', '', NULL, '偶作 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea39a073-dec0-45e8-815d-f37beffa2683', '春思二首 一', '春思二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["竹外麥煙愁漠漠，短翅啼禽飛魄魄。","此時憶著千里人，獨坐支頤看花落。"]', '["竹外麦煙愁漠漠，短翅啼禽飞魄魄。","此时憶著千里人，独坐支頤看花落。"]', '诗', 'shi', '', NULL, '春思二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6834ee40-c389-4afa-955e-e786be14e8ab', '春思二首 二', '春思二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江南酒熟清明天，高高綠斾當風懸。","誰家無事少年子，滿面落花猶醉眠。"]', '["江南酒熟清明天，高高綠斾當风懸。","誰家無事少年子，满面落花猶醉眠。"]', '诗', 'shi', '', NULL, '春思二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36a9435-e418-4cc0-a566-3dd15f627e52', '訪僧不遇', '訪僧不遇', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["櫂倚東林欲問禪，遠公飛錫未應還。","蒙莊弟子相看笑，何事空門亦有關。"]', '["櫂倚东林欲问禪，远公飞錫未應還。","蒙莊弟子相看笑，何事空门亦有关。"]', '诗', 'shi', '', NULL, '訪僧不遇 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5ff721-0983-4095-8feb-38859a60f902', '謝山泉', '謝山泉', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["決決春泉出洞霞，石壜封寄野人家。","草堂盡日留僧坐，自向前溪摘茗芽。"]', '["決決春泉出洞霞，石壜封寄野人家。","草堂尽日留僧坐，自向前溪摘茗芽。"]', '诗', 'shi', '', NULL, '謝山泉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f254a579-91a2-4a36-a182-8e1a83eb17fe', '洞宮夕', '洞宮夕', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["月午山空桂花落，華陽道士雲衣薄。","石壇香散步虛聲，杉雲清泠滴栖鶴。"]', '["月午山空桂花落，华陽道士云衣薄。","石壇香散步虛声，杉云清泠滴栖鹤。"]', '诗', 'shi', '', NULL, '洞宮夕 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc34dc5-462a-40b5-8b31-d1cc7cadd337', '峽客行', '峽客行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["萬仞峰排千劒束，孤舟夜繫峰頭宿。","蠻溪雪壞蜀江傾，灩澦朝來大如屋。"]', '["万仞峰排千劒束，孤舟夜繫峰头宿。","蠻溪雪壞蜀江傾，灩澦朝来大如屋。"]', '诗', 'shi', '', NULL, '峽客行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516a8e61-5285-4666-82be-7a93c75496c8', '江邊', '江邊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江邊日晚潮煙上，樹裏鴉鴉桔槔響。","無因得似灌園翁，十畝春蔬一藜杖。"]', '["江邊日晚潮煙上，樹裏鴉鴉桔槔响。","無因得似灌园翁，十畝春蔬一藜杖。"]', '诗', 'shi', '', NULL, '江邊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90400319-f6a6-4456-9f52-90993e0ae093', '簾', '簾', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["枕映疎容晚向欹，秋煙脉脉雨微微。","逆風障燕尋常事，不學人前當妓衣。"]', '["枕映疎容晚向欹，秋煙脉脉雨微微。","逆风障燕尋常事，不学人前當妓衣。"]', '诗', 'shi', '', NULL, '簾 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b6ff3e-ede2-4ee0-9447-04ded6408cfd', '開元雜題七首 玉龍子', '开元杂題七首 玉龙子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["何代奇工碾玉英，細髯纖角盡雕成。","煙乾霧悄君心苦，風雨長隨一擲聲。"]', '["何代奇工碾玉英，細髯纖角尽雕成。","煙乾霧悄君心苦，风雨长隨一擲声。"]', '诗', 'shi', '', NULL, '開元雜題七首 玉龍子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f348129a-f81d-4b9f-aabf-c542aa390e67', '開元雜題七首 照夜白', '开元杂題七首 照夜白', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雪蚪輕駿步如飛，一練騰光透月旗。","應笑穆王拋萬乘，踏風鞭露向瑤池。"]', '["雪蚪轻駿步如飞，一練腾光透月旗。","應笑穆王拋万乘，踏风鞭露向瑤池。"]', '诗', 'shi', '', NULL, '開元雜題七首 照夜白 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8391aa6d-002b-4672-89f4-eb38328b7066', '開元雜題七首 舞馬', '开元杂題七首 舞马', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["月窟龍孫四百蹄，驕驤輕步應金鞞。","曲終似要君王寵，回望紅樓不敢嘶。"]', '["月窟龙孫四百蹄，驕驤轻步應金鞞。","曲終似要君王寵，回望紅楼不敢嘶。"]', '诗', 'shi', '', NULL, '開元雜題七首 舞馬 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae79ebe6-e7e0-4166-9bb5-31759dacd172', '開元雜題七首 雜伎', '开元杂題七首 杂伎', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["拜象馴犀角觝豪，星丸霜劒出花高。","六宮爭近乘輿望，珠翠三千擁赭袍。"]', '["拜象馴犀角觝豪，星丸霜劒出花高。","六宮爭近乘輿望，珠翠三千擁赭袍。"]', '诗', 'shi', '', NULL, '開元雜題七首 雜伎 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56577b6e-7fd0-41eb-8285-a0e768a3461f', '開元雜題七首 雪衣女', '开元杂題七首 雪衣女', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["嫩紅鉤曲雪花攢，月殿棲時片影殘。","自說夜來春夢惡，學持金偈玉欄干。"]', '["嫩紅鉤曲雪花攢，月殿棲时片影殘。","自说夜来春梦惡，学持金偈玉欄干。"]', '诗', 'shi', '', NULL, '開元雜題七首 雪衣女 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64dde076-4d4f-45e3-af90-a352676fc1f9', '開元雜題七首 繡嶺宮', '开元杂題七首 繡嶺宮', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["繡嶺花殘翠倚空，碧窗瑤砌舊行宮。","閑乘小駟濃陰下，時舉金鞭半袖風。"]', '["繡嶺花殘翠倚空，碧窗瑤砌旧行宮。","闲乘小駟濃陰下，时舉金鞭半袖风。"]', '诗', 'shi', '', NULL, '開元雜題七首 繡嶺宮 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75683a4f-d948-41ac-bd9a-19453c96f94e', '開元雜題七首 湯泉', '开元杂題七首 湯泉', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["暖殿流湯數十間，玉渠香細浪回環。","上皇初解雲衣浴，珠櫂時敲瑟瑟山。"]', '["暖殿流湯數十间，玉渠香細浪回环。","上皇初解云衣浴，珠櫂时敲瑟瑟山。"]', '诗', 'shi', '', NULL, '開元雜題七首 湯泉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd6aba6-7ec2-4258-854b-462afc8abed8', '題杜秀才水亭', '題杜秀才水亭', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曉和風露立晴煙，秖恐腥魂涴洞天。","雲肆有龍君若買，便敲初日鑄金錢。"]', '["晓和风露立晴煙，秖恐腥魂涴洞天。","云肆有龙君若買，便敲初日鑄金錢。"]', '诗', 'shi', '', NULL, '題杜秀才水亭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('625dc6c3-7f7c-42c4-b034-c30a993fa3b6', '翠碧', '翠碧', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["紅襟翠翰兩參差，徑拂煙華上細枝。","春水漸生魚易得，莫辭風雨坐多時。"]', '["紅襟翠翰兩參差，徑拂煙华上細枝。","春水漸生鱼易得，莫辞风雨坐多时。"]', '诗', 'shi', '', NULL, '翠碧 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('185d244a-7c99-4ff9-851b-a3b35db552fa', '水國詩', '水国诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水國不堪旱，斯民生甚微。","直至葭菼少，敢言魚蟹肥。","我到荒村無食啗，對案又非梁謝覽。","況是乾苗結子疎，歸時祗得藜羹糝。"]', '["水国不堪旱，斯民生甚微。","直至葭菼少，敢言鱼蟹肥。","我到荒村無食啗，对案又非梁謝覽。","況是乾苗結子疎，归时祗得藜羹糝。"]', '诗', 'shi', '', NULL, '水國詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c060870-df3e-43d8-b8fa-3920a66d6470', '井上桐', '井上桐', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["美人傷別離，汲井長待曉。","愁因轆轤轉，驚起雙棲鳥。","獨立傍銀牀，碧桐風嫋嫋。"]', '["美人傷別離，汲井长待晓。","愁因轆轤轉，驚起雙棲鸟。","独立傍銀牀，碧桐风嫋嫋。"]', '诗', 'shi', '', NULL, '井上桐 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b715c3ca-9306-4c64-a487-34456199d6b4', '門前路', '门前路', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["門前向城路，一直復一曲。","曲去日中還，直行日暮宿。","何必日中還，曲途荆棘間。"]', '["门前向城路，一直复一曲。","曲去日中還，直行日暮宿。","何必日中還，曲途荆棘间。"]', '诗', 'shi', '', NULL, '門前路 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c807f0fa-06da-43fa-a014-3ebf8a3cdb48', '彼農二章 一', '彼農二章 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["世路澆險，淳風蕩除。","彼農家流，猶存厥初。","藁焉而席，茨焉而居。","首亂如葆，形枯若腒。","大耋既鮐，童子未𪘯。","以負以載，悉薅悉鉏。","我慕聖道，我躭古書。","小倦於學，時遊汝廬。","有飯一盛，莫鹽莫蔬。","有繻一緹，不襟不袪。","所謂飢寒，汝何逭歟。"]', '["世路澆險，淳风蕩除。","彼農家流，猶存厥初。","藁焉而席，茨焉而居。","首亂如葆，形枯若腒。","大耋既鮐，童子未𪘯。","以負以載，悉薅悉鉏。","我慕聖道，我躭古书。","小倦於学，时游汝廬。","有飯一盛，莫鹽莫蔬。","有繻一緹，不襟不袪。","所謂飢寒，汝何逭歟。"]', '诗', 'shi', '', NULL, '彼農二章 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f9553e-a574-4a16-9432-f5e3b9db0844', '彼農二章 二', '彼農二章 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["禹貢厥田，上下各異。","善人爲邦，民受其賜。","去年西成，野有遺穗。","今夏南畝，旱氣赤地。","遭其豐凶，概歛無二。","退輸弗供，進訴弗視。","號于旻天，以血爲淚。","孟子有言，王無罪歲。","詩以窮辭，以嫉悍吏。"]', '["禹貢厥田，上下各異。","善人爲邦，民受其賜。","去年西成，野有遺穗。","今夏南畝，旱氣赤地。","遭其豐凶，概歛無二。","退輸弗供，進訴弗視。","號于旻天，以血爲泪。","孟子有言，王無罪歲。","诗以窮辞，以嫉悍吏。"]', '诗', 'shi', '', NULL, '彼農二章 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf27b6c-aa71-4894-827b-a476752b3105', '奉酬襲美苦雨見寄', '奉酬襲美苦雨见寄', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["松篁交加午陰黑，別是江南煙靄國。","頑雲猛雨更相欺，聲似虓號色如墨。","茅茨裛爛簷生衣，夜夜化爲螢火飛。","螢飛漸多屋漸薄，一注愁霖當面落。","愁霖愁霖爾何錯，滅頂於余奚所作。","既不能賦似陳思王，又不能詩似謝康樂。","昔年嘗過杜子美，亦得高歌破印紙。","慣曾掀攪大筆多，爲我才情也如此。","高揖愁霖詞未已，披文忽自皮夫子。","哀弦怨柱合爲吟，㤞我窮棲蓬藋裏。","初悲濕翼何由起，末欲牋天叩天耳。","其如玉女正投壺，笑電霏霏作天喜。","我本曾無一稜田，平生嘯傲空漁船。","有時赤腳弄明月，踏破五湖光底天。","去歲王師東下急，輸兵粟盡民相泣。","伊予不戰不耕人，敢怨烝黎無糝粒。","不然受性圓如規，千姿萬態分毫釐。","唾壺虎子盡能執，舐痔折枝無所辭。","有頭強方心強直，撐拄頹風不量力。","自愛垂名野史中，寧論抱困荒城側。","唯君浩歎非庸人，分衣輟飲來相親。","橫眠木榻忘華薦，對食露葵輕八珍。","欲窮玄，鳳未白，欲懷仙，鯨尚隔。","不如驅入醉鄉中，只恐醉鄉田地窄。"]', '["松篁交加午陰黑，別是江南煙靄国。","頑云猛雨更相欺，声似虓號色如墨。","茅茨裛爛簷生衣，夜夜化爲螢火飞。","螢飞漸多屋漸薄，一注愁霖當面落。","愁霖愁霖爾何錯，滅頂於余奚所作。","既不能賦似陳思王，又不能诗似謝康乐。","昔年嘗過杜子美，亦得高歌破印紙。","慣曾掀攪大笔多，爲我才情也如此。","高揖愁霖词未已，披文忽自皮夫子。","哀弦怨柱合爲吟，㤞我窮棲蓬藋裏。","初悲濕翼何由起，末欲牋天叩天耳。","其如玉女正投壺，笑電霏霏作天喜。","我本曾無一稜田，平生嘯傲空漁船。","有时赤腳弄明月，踏破五湖光底天。","去歲王師东下急，輸兵粟尽民相泣。","伊予不戰不耕人，敢怨烝黎無糝粒。","不然受性圓如規，千姿万態分毫釐。","唾壺虎子尽能執，舐痔折枝無所辞。","有头強方心強直，撐拄頹风不量力。","自愛垂名野史中，寧論抱困荒城側。","唯君浩歎非庸人，分衣輟饮来相親。","橫眠木榻忘华薦，对食露葵轻八珍。","欲窮玄，鳳未白，欲懷仙，鯨尚隔。","不如驱入醉乡中，只恐醉乡田地窄。"]', '诗', 'shi', '', NULL, '奉酬襲美苦雨見寄 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfbf97c4-9382-4157-bf56-24737be61dfe', '夏日閑居作四聲詩寄襲美 平聲', '夏日闲居作四声诗寄襲美 平声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["荒池菰蒲深，閑階莓苔平。","江邊松篁多，人家簾櫳清。","爲書凌遺編，調弦夸新聲。","求歡雖殊途，探幽聊怡情。"]', '["荒池菰蒲深，闲階莓苔平。","江邊松篁多，人家簾櫳清。","爲书凌遺編，調弦夸新声。","求歡雖殊途，探幽聊怡情。"]', '诗', 'shi', '', NULL, '夏日閑居作四聲詩寄襲美 平聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a23e103-053b-482e-a6e9-61d45a316af3', '夏日閑居作四聲詩寄襲美 平上聲', '夏日闲居作四声诗寄襲美 平上声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朝煙淹樓臺，晚雨染島嶼。","漁童驚狂歌，艇子喜野語。","山容堪停杯，柳影好隱暑。","年華如飛鴻，斗酒幸且舉。"]', '["朝煙淹楼台，晚雨染島嶼。","漁童驚狂歌，艇子喜野語。","山容堪停杯，柳影好隐暑。","年华如飞鴻，斗酒幸且舉。"]', '诗', 'shi', '', NULL, '夏日閑居作四聲詩寄襲美 平上聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50eb6d3d-42a2-4e2d-a745-ee07fd602abb', '夏日閑居作四聲詩寄襲美 平去聲', '夏日闲居作四声诗寄襲美 平去声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["新開窗猶偏，自種蕙未徧。","書籤風搖聞，釣榭霧破見。","耕耘閑之資，嘯詠性最便。","希夷全天真，詎要問貴賤。"]', '["新开窗猶偏，自種蕙未徧。","书籤风搖闻，釣榭霧破见。","耕耘闲之資，嘯詠性最便。","希夷全天真，詎要问貴賤。"]', '诗', 'shi', '', NULL, '夏日閑居作四聲詩寄襲美 平去聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('777c723b-849d-42ab-9aca-d6543f475e6b', '夏日閑居作四聲詩寄襲美 平入聲', '夏日闲居作四声诗寄襲美 平入声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["端居愁無涯，一夕髪欲白。","因爲鸞章吟，忽憶鶴骨客。","手披丹臺文，脚著赤玉舃。","如蒙清音酬，若渴吸月液。"]', '["端居愁無涯，一夕髪欲白。","因爲鸾章吟，忽憶鹤骨客。","手披丹台文，脚著赤玉舃。","如蒙清音酬，若渴吸月液。"]', '诗', 'shi', '', NULL, '夏日閑居作四聲詩寄襲美 平入聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d5bfbdc-0498-4094-a17c-fbd2ecac01b7', '奉酬襲美苦雨四聲重寄三十二句 平聲', '奉酬襲美苦雨四声重寄三十二句 平声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["幽棲眠疎窗，豪居憑高樓。","浮漚驚跳丸，寒聲思重裘。","牀前垂文竿，巢邊登輕舟。","雖無東臯田，還生魚乎憂。"]', '["幽棲眠疎窗，豪居憑高楼。","浮漚驚跳丸，寒声思重裘。","牀前垂文竿，巢邊登轻舟。","雖無东臯田，還生鱼乎憂。"]', '诗', 'shi', '', NULL, '奉酬襲美苦雨四聲重寄三十二句 平聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c747e9-33c3-43ec-a59e-cd5c2ab1a9fa', '奉酬襲美苦雨四聲重寄三十二句 平上聲', '奉酬襲美苦雨四声重寄三十二句 平上声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["層雲愁天低，久雨倚檻冷。","絲禽藏荷香，錦鯉繞島影。","心將時人乖，道與隱者靜。","桐陰無深泉，所以逞短綆。"]', '["層云愁天低，久雨倚檻冷。","絲禽藏荷香，錦鯉繞島影。","心將时人乖，道與隐者静。","桐陰無深泉，所以逞短綆。"]', '诗', 'shi', '', NULL, '奉酬襲美苦雨四聲重寄三十二句 平上聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c34b667a-2284-40ad-9639-74e61ed6ea9b', '奉酬襲美苦雨四聲重寄三十二句 平去聲', '奉酬襲美苦雨四声重寄三十二句 平去声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["烏蟾俱沈光，晝夜恨暗度。","何當乘雲螭，面見上帝愬。","臣言陰雲欺，詔用利劒付。","迴車誅羣姦，自散萬籟怒。"]', '["烏蟾俱沈光，晝夜恨暗度。","何當乘云螭，面见上帝愬。","臣言陰云欺，詔用利劒付。","迴车誅羣姦，自散万籟怒。"]', '诗', 'shi', '', NULL, '奉酬襲美苦雨四聲重寄三十二句 平去聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e30d332-309d-43af-8ac6-3351954a8101', '奉酬襲美苦雨四聲重寄三十二句 平入聲', '奉酬襲美苦雨四声重寄三十二句 平入声', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["危簷仍空堦，十日滴不歇。","青莎看成狂，白菊即欲沒。","吳王荒金尊，越妾挾玉瑟。","當時雖愁霖，亦若惜落月。"]', '["危簷仍空堦，十日滴不歇。","青莎看成狂，白菊即欲沒。","吳王荒金尊，越妾挾玉瑟。","當时雖愁霖，亦若惜落月。"]', '诗', 'shi', '', NULL, '奉酬襲美苦雨四聲重寄三十二句 平入聲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78693577-76f1-44cb-b44f-dbe1de507d3b', '曉起即事因成迴文寄襲美', '晓起即事因成迴文寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["平波落月吟閑景，暗幌浮煙思起人。","清露曉垂花謝半，遠風微動蕙抽新。","城荒上處樵童小，石蘚分來宿鷺馴。","晴寺野尋同去好，古碑苔字細書勻。"]', '["平波落月吟闲景，暗幌浮煙思起人。","清露晓垂花謝半，远风微动蕙抽新。","城荒上处樵童小，石蘚分来宿鷺馴。","晴寺野尋同去好，古碑苔字細书勻。"]', '诗', 'shi', '', NULL, '曉起即事因成迴文寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de4e1c3-9b08-49c3-9df3-26d4895fecbe', '回文', '回文', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["靜煙臨碧樹，殘雪背晴樓。","冷天侵極戍，寒月對行舟。"]', '["静煙臨碧樹，殘雪背晴楼。","冷天侵極戍，寒月对行舟。"]', '诗', 'shi', '', NULL, '回文 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9cd1bb-826a-4d94-b177-3036b7475599', '疊韻山中吟', '叠韻山中吟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["瓊英輕明生，石脉滴瀝碧。","玄鉛仙偏憐，白幘客亦惜。"]', '["瓊英轻明生，石脉滴瀝碧。","玄鉛仙偏怜，白幘客亦惜。"]', '诗', 'shi', '', NULL, '疊韻山中吟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c136e8f5-02dc-472b-ada7-97c60588b0ac', '雙聲溪上思', '雙声溪上思', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["溪空唯容雲，木密不隕雨。","迎漁隱映間，安問謳鴉樐。"]', '["溪空唯容云，木密不隕雨。","迎漁隐映间，安问謳鴉樐。"]', '诗', 'shi', '', NULL, '雙聲溪上思 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca1a684-5e75-4435-aa73-8b6745b5e2f1', '疊韻吳宮詞二首 一', '叠韻吳宮词二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["膚愉吳都姝，眷戀便殿宴。","逡巡新春人，轉面見戰箭。"]', '["膚愉吳都姝，眷戀便殿宴。","逡巡新春人，轉面见戰箭。"]', '诗', 'shi', '', NULL, '疊韻吳宮詞二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4ae0a7-d6ff-4196-b042-eb06f8c9d519', '疊韻吳宮詞二首 二', '叠韻吳宮词二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["紅櫳通東風，翠珥醉易墜。","平明兵盈城，棄置遂至地。"]', '["紅櫳通东风，翠珥醉易墜。","平明兵盈城，棄置遂至地。"]', '诗', 'shi', '', NULL, '疊韻吳宮詞二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8916ad-9f2b-4012-bd24-6ba97b6789e7', '和胥口即事 一', '和胥口即事 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雨後山容若動，天寒樹色如消。","目送迴汀隱隱，心隨挂鹿搖搖。","白蔣知秋露裛，青楓欲暮煙饒。","莫問吳趨行樂，酒旗竿倚河橋。"]', '["雨後山容若动，天寒樹色如消。","目送迴汀隐隐，心隨挂鹿搖搖。","白蔣知秋露裛，青楓欲暮煙饒。","莫问吳趨行乐，酒旗竿倚河橋。"]', '诗', 'shi', '', NULL, '和胥口即事 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e8c10c-e6ee-42ae-ab72-96e09894da25', '和胥口即事 二', '和胥口即事 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["把釣絲隨浪遠，采蓮衣染香濃。","綠倒紅飄欲盡，風斜雨細相逢。","斷岸沈漁𦋥𦊲，鄰村送客𦪽{舟卭}。","即是清霜剖野，乘閑莫厭來重。"]', '["把釣絲隨浪远，采蓮衣染香濃。","綠倒紅飄欲尽，风斜雨細相逢。","斷岸沈漁𦋥𦊲，鄰村送客𦪽{舟卭}。","即是清霜剖野，乘闲莫厭来重。"]', '诗', 'shi', '', NULL, '和胥口即事 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807f3ad3-1df4-43dd-857f-f944fc7c2921', '齊梁怨別', '齊梁怨別', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["寥寥缺月看將落，簷外霜華染羅幕。","不知蘭櫂到何山，應倚相思樹邊泊。"]', '["寥寥缺月看將落，簷外霜华染羅幕。","不知蘭櫂到何山，應倚相思樹邊泊。"]', '诗', 'shi', '', NULL, '齊梁怨別 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3273a61f-c50d-4dd0-a8af-309ad228d869', '閑居雜題五首 鳴蜩早', '闲居杂題五首 鳴蜩早', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["閑來倚杖柴門口，鳥下深枝啄晚蟲。","周步一池銷半日，十年聽此鬢如蓬。"]', '["闲来倚杖柴门口，鸟下深枝啄晚蟲。","周步一池銷半日，十年听此鬢如蓬。"]', '诗', 'shi', '', NULL, '閑居雜題五首 鳴蜩早 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28f68d4-2cfa-46f9-9bd4-55e0fb9eae2a', '閑居雜題五首 野態真', '闲居杂題五首 野態真', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["君如有意躭田里，予亦無機向藝能。","心跡所便唯是直，人間聞道最先憎。"]', '["君如有意躭田里，予亦無機向藝能。","心跡所便唯是直，人间闻道最先憎。"]', '诗', 'shi', '', NULL, '閑居雜題五首 野態真 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee26e12e-b0e8-423b-9852-eebbe27c2385', '閑居雜題五首 松間斟', '闲居杂題五首 松间斟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["子山園靜憐幽木，公幹詞清詠蓽門。","月上風微蕭灑甚，斗醪何惜置盈尊。"]', '["子山园静怜幽木，公幹词清詠蓽门。","月上风微蕭灑甚，斗醪何惜置盈尊。"]', '诗', 'shi', '', NULL, '閑居雜題五首 松間斟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ed5d8c-b7a4-401c-ba13-248b9eec4c12', '閑居雜題五首 飲巖泉', '闲居杂題五首 饮巖泉', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["已甘茅洞三君食，欠買桐江一朵山。","嚴子瀨高秋浪白，水禽飛盡釣舟還。"]', '["已甘茅洞三君食，欠買桐江一朵山。","嚴子瀨高秋浪白，水禽飞尽釣舟還。"]', '诗', 'shi', '', NULL, '閑居雜題五首 飲巖泉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097c8634-6299-430a-9c02-ce4ecca68b5a', '閑居雜題五首 當軒鶴', '闲居杂題五首 當軒鹤', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["自笑與人乖好尚，田家山客共柴車。","干時未似棲廬雀，鳥道閑攜相爾書。"]', '["自笑與人乖好尚，田家山客共柴车。","干时未似棲廬雀，鸟道闲携相爾书。"]', '诗', 'shi', '', NULL, '閑居雜題五首 當軒鶴 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bcd5975-60f6-4a37-819c-a163bc824b36', '藥名離合夏日即事三首 一', '藥名離合夏日即事三首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["乘屐著來幽砌滑，石甖煎得遠泉甘。","草堂祗待新秋景，天色微涼酒半酣。"]', '["乘屐著来幽砌滑，石甖煎得远泉甘。","草堂祗待新秋景，天色微涼酒半酣。"]', '诗', 'shi', '', NULL, '藥名離合夏日即事三首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6726a84b-1506-4d8b-84f9-0e7836c9a639', '藥名離合夏日即事三首 二', '藥名離合夏日即事三首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["避暑最須從樸野，葛巾筠席更相當。","歸來又好乘涼釣，藤蔓陰陰著雨香。"]', '["避暑最須從樸野，葛巾筠席更相當。","归来又好乘涼釣，藤蔓陰陰著雨香。"]', '诗', 'shi', '', NULL, '藥名離合夏日即事三首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d717d5a-440e-4126-a86c-b3fc63a7b1a2', '藥名離合夏日即事三首 三', '藥名離合夏日即事三首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["窗外曉簾還自卷，柏煙蘭露思晴空。","青箱有意終須續，斷簡遺編一半通。"]', '["窗外晓簾還自卷，柏煙蘭露思晴空。","青箱有意終須續，斷簡遺編一半通。"]', '诗', 'shi', '', NULL, '藥名離合夏日即事三首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbe3432c-649b-4caa-a8ed-b09f44fc3346', '和襲美懷錫山藥名離合二首 一', '和襲美懷錫山藥名離合二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鶴伴前溪栽白杏，人來陰洞寫枯松。","蘿深境靜日欲落，石上未眠聞遠鐘。"]', '["鹤伴前溪栽白杏，人来陰洞寫枯松。","蘿深境静日欲落，石上未眠闻远鐘。"]', '诗', 'shi', '', NULL, '和襲美懷錫山藥名離合二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0104af5c-11d7-4187-aaeb-15c74a543981', '和襲美懷錫山藥名離合二首 二', '和襲美懷錫山藥名離合二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["佳句成來誰不伏，神丹偷去亦須防。","風前莫怪攜詩藁，本是吳吟蕩槳郎。"]', '["佳句成来誰不伏，神丹偷去亦須防。","风前莫怪携诗藁，本是吳吟蕩槳郎。"]', '诗', 'shi', '', NULL, '和襲美懷錫山藥名離合二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a95f90d2-6817-4810-8db5-e5ec8901062a', '和襲美懷鹿門縣名離合二首 一', '和襲美懷鹿门縣名離合二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雲容覆枕無非白，水色侵磯直是藍。","田種紫芝餐可壽，春來何事戀江南。"]', '["云容覆枕無非白，水色侵磯直是藍。","田種紫芝餐可壽，春来何事戀江南。"]', '诗', 'shi', '', NULL, '和襲美懷鹿門縣名離合二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf2b140-3b34-4225-bb4b-61784e90a90e', '和襲美懷鹿門縣名離合二首 二', '和襲美懷鹿门縣名離合二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["竹溪深處猿同宿，松閣秋來客共登。","封逕古苔侵石鹿，城中誰解訪山僧。"]', '["竹溪深处猿同宿，松閣秋来客共登。","封逕古苔侵石鹿，城中誰解訪山僧。"]', '诗', 'shi', '', NULL, '和襲美懷鹿門縣名離合二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d48c99-ce50-476f-b794-51b36685d814', '寒日古人名', '寒日古人名', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["初寒朗詠裴回立，欲謝玄關早晚開。","昨日登樓望江色，魚梁鴻雁幾多來。"]', '["初寒朗詠裴回立，欲謝玄关早晚开。","昨日登楼望江色，鱼梁鴻雁幾多来。"]', '诗', 'shi', '', NULL, '寒日古人名 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf1d337-0015-4290-8f89-baab9ff81ace', '句', '句', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["幾點社翁雨，一番花信風。","水鳥歌婦女，衣襟便佞舌。","溪山自是清涼國，松竹合封蕭灑侯。","山上花明水上曛，一橈青翰破霞文。","白帝霜輿欲御秋，但說漱流幷枕石。","不辭蟬腹與龜腸，頭方不會王門事。","塵土空緇白苧衣，秋來嬾上向吳亭。"]', '["幾点社翁雨，一番花信风。","水鸟歌婦女，衣襟便佞舌。","溪山自是清涼国，松竹合封蕭灑侯。","山上花明水上曛，一橈青翰破霞文。","白帝霜輿欲御秋，但说漱流幷枕石。","不辞蟬腹與龟腸，头方不會王门事。","塵土空緇白苧衣，秋来嬾上向吳亭。"]', '诗', 'shi', '', NULL, '句 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57129e3e-10f9-4ab2-b911-dd7cca65a624', '旅泊吳門', '旅泊吳门', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["一舸吳江晚，堪憂病廣文。","鱸魚誰與伴，鷗鳥自成羣。","反照縱橫水，斜空斷續雲。","異鄉無限思，盡付酒醺醺。"]', '["一舸吳江晚，堪憂病廣文。","鱸鱼誰與伴，鷗鸟自成羣。","反照縱橫水，斜空斷續云。","異乡無限思，尽付酒醺醺。"]', '诗', 'shi', '', NULL, '旅泊吳門 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e30a622-74ae-45e9-80a6-9446cead945a', '賁中間有吳門旅泊之什蒙魯望垂和更作一章以伸詶謝', '賁中间有吳门旅泊之什蒙魯望垂和更作一章以伸詶謝', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["偶發陶匏響，皆蒙組繡文。","清秋將落帽，子夏正離羣。","有恨書燕雁，無聊賦郢雲。","徧看心自醉，不是酒能醺。"]', '["偶發陶匏响，皆蒙組繡文。","清秋將落帽，子夏正離羣。","有恨书燕雁，無聊賦郢云。","徧看心自醉，不是酒能醺。"]', '诗', 'shi', '', NULL, '賁中間有吳門旅泊之什蒙魯望垂和更作一章以伸詶謝 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdf0988e-4e02-4515-b868-ea7217af50de', '酬襲美先見寄倒來韻', '酬襲美先见寄倒来韻', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["尋疑天意喪斯文，故選茅峰寄白雲。","酒後只留滄海客，香前唯見紫陽君。","近年已絕詩書癖，今日兼將筆硯焚。","爲有此身猶苦患，不知何者是玄纁。"]', '["尋疑天意喪斯文，故選茅峰寄白云。","酒後只留滄海客，香前唯见紫陽君。","近年已絕诗书癖，今日兼將笔硯焚。","爲有此身猶苦患，不知何者是玄纁。"]', '诗', 'shi', '', NULL, '酬襲美先見寄倒來韻 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b100c8-843d-48a0-8670-2e933691d636', '奉和襲美醉中即席見贈次韻', '奉和襲美醉中即席见贈次韻', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["桂枝新下月中仙，學海詞鋒譽藹然。","文陣已推忠信甲，窮波猶認孝廉船。","清標稱住羊車上，俗韻慚居鶴氅前。","共許逢蒙快弓箭，再穿楊葉在明年。"]', '["桂枝新下月中仙，学海词鋒譽藹然。","文陣已推忠信甲，窮波猶認孝廉船。","清標稱住羊车上，俗韻慚居鹤氅前。","共許逢蒙快弓箭，再穿楊葉在明年。"]', '诗', 'shi', '', NULL, '奉和襲美醉中即席見贈次韻 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ac8f5c-8a4f-461d-a472-d943b2434eff', '奉和襲美題褚家林亭', '奉和襲美題褚家林亭', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["疎野林亭震澤西，朗吟閑步喜相攜。","時時風折蘆花亂，處處霜摧稻穗低。","百本敗荷魚不動，一枝寒菊蝶空迷。","今朝偶得高陽伴，從放山翁醉似泥。"]', '["疎野林亭震澤西，朗吟闲步喜相携。","时时风折蘆花亂，处处霜摧稻穗低。","百本敗荷鱼不动，一枝寒菊蝶空迷。","今朝偶得高陽伴，從放山翁醉似泥。"]', '诗', 'shi', '', NULL, '奉和襲美題褚家林亭 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5a94d1-9d72-4b8b-84cb-3c537cb906ae', '奉和襲美傷開元觀顧道士', '奉和襲美傷开元观顧道士', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["鳳麟膠盡夜如何，共歎先生劒解多。","幾度弔來唯白鶴，此時乘去必青騾。","圖中含景隨殘照，琴裏流泉寄逝波。","惆悵真靈又空返，玉書誰授紫微歌。"]', '["鳳麟膠尽夜如何，共歎先生劒解多。","幾度弔来唯白鹤，此时乘去必青騾。","圖中含景隨殘照，琴裏流泉寄逝波。","惆悵真靈又空返，玉书誰授紫微歌。"]', '诗', 'shi', '', NULL, '奉和襲美傷開元觀顧道士 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c09aa73-453f-4edb-953d-0f72a14a1e5c', '和魯望白菊', '和魯望白菊', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["雪彩冰姿號女華，寄身多是地仙家。","有時南國和霜立，幾處東籬伴月斜。","謝客瓊枝空貯恨，袁郎金鈿不成誇。","自知終古清香在，更出梅粧弄晚霞。"]', '["雪彩冰姿號女华，寄身多是地仙家。","有时南国和霜立，幾处东籬伴月斜。","謝客瓊枝空貯恨，袁郎金鈿不成誇。","自知終古清香在，更出梅粧弄晚霞。"]', '诗', 'shi', '', NULL, '和魯望白菊 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c441adbc-85b9-4657-8beb-99578b8c9694', '奉和襲美先輩悼鶴', '奉和襲美先輩悼鹤', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["池塘蕭索掩空籠，玉樹同嗟一土中。","莎徑罷鳴唯泣露，松軒休舞但悲風。","丹臺舊氅難重緝，紫府新書豈更通。","雲減霧消無處問，只留華髪與衰翁。"]', '["池塘蕭索掩空籠，玉樹同嗟一土中。","莎徑罷鳴唯泣露，松軒休舞但悲风。","丹台旧氅难重緝，紫府新书豈更通。","云減霧消無处问，只留华髪與衰翁。"]', '诗', 'shi', '', NULL, '奉和襲美先輩悼鶴 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd90c1b8-1fc1-45d2-a271-7bf75d00ed91', '偶約道流終乖文會荅皮陸', '偶約道流終乖文會荅皮陸', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["僊侶無何訪蔡經，兩煩韶濩出彤庭。","人間若有登樓望，應怪文星近客星。"]', '["僊侶無何訪蔡經，兩煩韶濩出彤庭。","人间若有登楼望，應怪文星近客星。"]', '诗', 'shi', '', NULL, '偶約道流終乖文會荅皮陸 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b442473d-d223-4395-b96d-f03b8a654147', '和襲美寒夜見訪', '和襲美寒夜见訪', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["雲孤鶴獨且相親，倣効從它折角巾。","不用吳江歎留滯，風姿俱是玉清人。"]', '["云孤鹤独且相親，倣効從它折角巾。","不用吳江歎留滯，风姿俱是玉清人。"]', '诗', 'shi', '', NULL, '和襲美寒夜見訪 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a251de-a717-42fd-89e9-f280c842b76d', '和襲美醉中先起次韻', '和襲美醉中先起次韻', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["何事桃源路忽迷，惟留雲雨怨空閨。","僊郎共許多情調，莫遣重歌濁水泥。"]', '["何事桃源路忽迷，惟留云雨怨空閨。","僊郎共許多情調，莫遣重歌濁水泥。"]', '诗', 'shi', '', NULL, '和襲美醉中先起次韻 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1ba039-5aec-4134-8ff6-d725283a3661', '和皮陸酒病偶作', '和皮陸酒病偶作', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["白編椰席鏤冰明，應助楊青解宿酲。","難繼二賢金玉唱，可憐空作斷猿聲。"]', '["白編椰席鏤冰明，應助楊青解宿酲。","难繼二賢金玉唱，可怜空作斷猿声。"]', '诗', 'shi', '', NULL, '和皮陸酒病偶作 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c12f0d1-54d9-4333-8e5c-ed76e5f4d35a', '送浙東德師侍御罷府西歸', '送浙东德師侍御罷府西归', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["孤雲獨鳥本無依，江海重逢故舊稀。","楊柳漸疏蘆葦白，可憐斜日送君歸。"]', '["孤云独鸟本無依，江海重逢故旧稀。","楊柳漸疏蘆葦白，可怜斜日送君归。"]', '诗', 'shi', '', NULL, '送浙東德師侍御罷府西歸 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad6eee4-da47-45db-b543-8c78aea16a34', '以青䭀飯分送襲美魯望因成一絕', '以青䭀飯分送襲美魯望因成一絕', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["誰屑瓊瑤事青䭀，舊傳名品出華陽。","應宜仙子胡麻拌，因送劉郎與阮郎。"]', '["誰屑瓊瑤事青䭀，旧傳名品出华陽。","應宜仙子胡麻拌，因送劉郎與阮郎。"]', '诗', 'shi', '', NULL, '以青䭀飯分送襲美魯望因成一絕 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6125ff1b-4d83-4c92-96fd-5344c5159797', '玩金鸂鶒和陸魯望', '玩金鸂鶒和陸魯望', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["翠羽紅襟鏤彩雲，雙飛常笑白鷗羣。","誰憐化作彫金質，從倩沈檀十里聞。"]', '["翠羽紅襟鏤彩云，雙飞常笑白鷗羣。","誰怜化作彫金質，從倩沈檀十里闻。"]', '诗', 'shi', '', NULL, '玩金鸂鶒和陸魯望 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d65a3a-d979-4192-8cf5-d5f3032963f4', '悼鶴和襲美', '悼鹤和襲美', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["渥頂鮮毛品格馴，莎庭閑暇重難羣。","無端日暮東風起，飄散春空一片雲。"]', '["渥頂鲜毛品格馴，莎庭闲暇重难羣。","無端日暮东风起，飄散春空一片云。"]', '诗', 'shi', '', NULL, '悼鶴和襲美 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7001442d-0f58-4800-a025-b65f78bcc03d', '覽皮先輩盛製因作十韻以寄用伸欵仰', '覽皮先輩盛製因作十韻以寄用伸欵仰', 'a7401622-79ff-4796-b537-3ffc0c55f78a', '唐', '["河嶽挺靈異，星辰精氣殊。","在人爲英傑，與國作禎符。","襄陽得奇士，俊邁真龍駒。","勇果魯仲由，文賦蜀相如。","渾浩江海廣，葩華桃李敷。","小言入無間，大言塞空虛。","幾人游赤水，夫子得玄珠。","鬼神爭奧秘，天地惜洪鑪。","既有曾參行，仍兼君子儒。","吾知上帝意，將使居黃樞。","好保千金體須爲萬姓謨。"]', '["河嶽挺靈異，星辰精氣殊。","在人爲英傑，與国作禎符。","襄陽得奇士，俊邁真龙駒。","勇果魯仲由，文賦蜀相如。","渾浩江海廣，葩华桃李敷。","小言入無间，大言塞空虛。","幾人游赤水，夫子得玄珠。","鬼神爭奧秘，天地惜洪鑪。","既有曾參行，仍兼君子儒。","吾知上帝意，將使居黄樞。","好保千金體須爲万姓謨。"]', '诗', 'shi', '', NULL, '覽皮先輩盛製因作十韻以寄用伸欵仰 崔璐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('791dd72a-e767-4777-a4f2-6e67ff1c194f', '浙東罷府西歸酬別張廣文皮先輩陸秀才', '浙东罷府西归酬別張廣文皮先輩陸秀才', '04e94cb5-6976-4d7d-9b2d-c5b73b7d80ab', '唐', '["豈有頭風筆下痊，浪成蠻語向初筵。","蘭亭舊趾雖曾見，柯笛遺音更不傳。","照曜文星吳分野，留連花月晉名賢。","相逢只恨相知晚，一曲驪歌又幾年。"]', '["豈有头风笔下痊，浪成蠻語向初筵。","蘭亭旧趾雖曾见，柯笛遺音更不傳。","照曜文星吳分野，留連花月晉名賢。","相逢只恨相知晚，一曲驪歌又幾年。"]', '诗', 'shi', '', NULL, '浙東罷府西歸酬別張廣文皮先輩陸秀才 李縠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee9ec1c-d9d7-4071-b15f-c345c7af94d3', '和皮日休悼鸖 一', '和皮日休悼鸖 一', '04e94cb5-6976-4d7d-9b2d-c5b73b7d80ab', '唐', '["才子襟期本上清，陸雲家鸖伴閑情。","猶憐反顧五六里，何意忽歸十二城。","露滴誰聞高葉墜，月沈休藉半階明。","人聞華表堪留語，剩向秋風寄一聲。"]', '["才子襟期本上清，陸云家鸖伴闲情。","猶怜反顧五六里，何意忽归十二城。","露滴誰闻高葉墜，月沈休藉半階明。","人闻华表堪留語，剩向秋风寄一声。"]', '诗', 'shi', '', NULL, '和皮日休悼鸖 一 李縠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b706a48-98a7-4885-8e6d-0d171601bddf', '和皮日休悼鸖 二', '和皮日休悼鸖 二', '04e94cb5-6976-4d7d-9b2d-c5b73b7d80ab', '唐', '["道林曾放雪翎飛，應悔庭除閉羽衣。","料得王恭披鶴氅，倚吟猶待月中歸。"]', '["道林曾放雪翎飞，應悔庭除閉羽衣。","料得王恭披鹤氅，倚吟猶待月中归。"]', '诗', 'shi', '', NULL, '和皮日休悼鸖 二 李縠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4888f87e-e982-4290-8f21-4d4daceffeda', '醉中襲美先月中歸', '醉中襲美先月中归', '04e94cb5-6976-4d7d-9b2d-c5b73b7d80ab', '唐', '["休文雖即逃瓊液，阿鶩還須掩玉閨。","月落金雞一聲後，不知誰悔醉如泥。"]', '["休文雖即逃瓊液，阿鶩還須掩玉閨。","月落金雞一声後，不知誰悔醉如泥。"]', '诗', 'shi', '', NULL, '醉中襲美先月中歸 李縠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc64d79-0672-454c-9255-e48d063e44f6', '奉酬皮先輩霜菊見贈', '奉酬皮先輩霜菊见贈', '28cfb3d9-6d7e-48eb-8909-f0f241602879', '唐', '["菊花開晚過秋風，聞道芳香正滿叢。","爭奈病夫難強飲，應須速自召車公。"]', '["菊花开晚過秋风，闻道芳香正满叢。","爭奈病夫难強饮，應須速自召车公。"]', '诗', 'shi', '', NULL, '奉酬皮先輩霜菊見贈 崔璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10352a8-0550-4d3c-84eb-2d827df74664', '蒙恩除替將還京洛偶敘所懷因成六韻呈軍事院諸公郡中一二秀才', '蒙恩除替將還京洛偶敘所懷因成六韻呈軍事院諸公郡中一二秀才', '28cfb3d9-6d7e-48eb-8909-f0f241602879', '唐', '["兩載求人瘼，三春受代歸。","務繁多簿籍，才短乏恩威。","共理乖天獎，分憂值歲饑。","遽蒙交郡印，安敢整朝衣。","作牧慙爲政，思鄉念式微。","儻容還故里，高臥掩柴扉。"]', '["兩載求人瘼，三春受代归。","務繁多簿籍，才短乏恩威。","共理乖天獎，分憂值歲饑。","遽蒙交郡印，安敢整朝衣。","作牧慙爲政，思乡念式微。","儻容還故里，高臥掩柴扉。"]', '诗', 'shi', '', NULL, '蒙恩除替將還京洛偶敘所懷因成六韻呈軍事院諸公郡中一二秀才 崔璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc57590-dfe1-4b77-8c07-9602fee81d15', '和皮日休悼鶴 一', '和皮日休悼鹤 一', 'dc807801-222f-496f-99dd-162816e42a52', '唐', '["直欲裁詩問杳冥，豈教靈化亦浮生。","風林月動疑留魄，沙島香愁似蘊情。","雪骨夜封蒼蘚冷，練衣寒在碧塘輕。","人間飛去猶堪恨，況是泉臺遠玉京。"]', '["直欲裁诗问杳冥，豈教靈化亦浮生。","风林月动疑留魄，沙島香愁似蘊情。","雪骨夜封蒼蘚冷，練衣寒在碧塘轻。","人间飞去猶堪恨，況是泉台远玉京。"]', '诗', 'shi', '', NULL, '和皮日休悼鶴 一 魏朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029ea817-db6d-4bc7-ba4a-c41ac89f1906', '和皮日休悼鶴 二', '和皮日休悼鹤 二', 'dc807801-222f-496f-99dd-162816e42a52', '唐', '["經秋宋玉已悲傷，況報胎禽昨夜亡。","霜曉起來無問處，伴僧彈指遶荷塘。"]', '["經秋宋玉已悲傷，況報胎禽昨夜亡。","霜晓起来無问处，伴僧彈指遶荷塘。"]', '诗', 'shi', '', NULL, '和皮日休悼鶴 二 魏朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c30208b-3ac6-4db4-b192-5c8fba086632', '皮襲美見留小讌次韻', '皮襲美见留小讌次韻', 'cc208f91-d834-4e9d-bac9-0b8d8bc9a52c', '唐', '["澤國春來少遇晴，有花開日且飛觥。","王戎似電休推病，周顗纔醒衆却驚。","芳景漸濃偏屬酒，煖風初暢欲調鶯。","知君不肯然官燭，爭得華筵徹夜明。"]', '["澤国春来少遇晴，有花开日且飞觥。","王戎似電休推病，周顗纔醒衆却驚。","芳景漸濃偏屬酒，煖风初暢欲調鶯。","知君不肯然官燭，爭得华筵徹夜明。"]', '诗', 'shi', '', NULL, '皮襲美見留小讌次韻 羊昭業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f8fbad-d2ff-4a46-bfe9-2f6edb420a5e', '送羊振文歸覲桂陽', '送羊振文归覲桂陽', 'ec399b1f-f239-468b-afa3-a779307ba600', '唐', '["高掛吳帆喜動容，問安歸去指湘峯。","懸魚庭內芝蘭秀，馭鶴門前薜荔封。","紅斾正憐棠影茂，綵衣偏帶桂香濃。","臨岐獨有霑襟戀，南巷當年共化龍。"]', '["高掛吳帆喜动容，问安归去指湘峯。","懸鱼庭內芝蘭秀，馭鹤门前薜荔封。","紅斾正怜棠影茂，綵衣偏带桂香濃。","臨岐独有霑襟戀，南巷當年共化龙。"]', '诗', 'shi', '', NULL, '送羊振文歸覲桂陽 顏萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d7f7e19-b14c-4c13-82f1-57183806eb6f', '送圓載上人', '送圓載上人', 'ec399b1f-f239-468b-afa3-a779307ba600', '唐', '["師來一世恣經行，却泛滄波問去程。","心靜已能防渴鹿，鼙喧時爲駭長鯨。","禪林幾結金桃重，梵室重修鐵瓦輕。","料得還鄉無別利，只應先見日華生。"]', '["師来一世恣經行，却泛滄波问去程。","心静已能防渴鹿，鼙喧时爲駭长鯨。","禪林幾結金桃重，梵室重修鐵瓦轻。","料得還乡無別利，只應先见日华生。"]', '诗', 'shi', '', NULL, '送圓載上人 顏萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9becd08a-f601-41fd-89f9-8525bc304752', '過張祜處士丹陽故居', '過張祜处士丹陽故居', 'ec399b1f-f239-468b-afa3-a779307ba600', '唐', '["憶昔爲兒逐我兄，曾拋竹馬拜先生。","書齋已換當時主，詩壁空題故友名。","豈是爭權留怨敵，可憐當路盡公卿。","柴扉草屋無人問，猶向荒田責地征。"]', '["憶昔爲兒逐我兄，曾拋竹马拜先生。","书斋已換當时主，诗壁空題故友名。","豈是爭權留怨敵，可怜當路尽公卿。","柴扉草屋無人问，猶向荒田責地征。"]', '诗', 'shi', '', NULL, '過張祜處士丹陽故居 顏萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b02fa792-0e36-435c-a10c-03a63da22044', '和襲美傷顧道士', '和襲美傷顧道士', '9b301366-d1f3-435e-8892-7210be165ee6', '唐', '["斜漢銀瀾一夜東，飄飄何處五雲中。","空留華表千年約，纔畢丹爐九轉功。","形蛻遠山孤壙月，影寒深院曉松風。","門人不覩飛昇去，猶與浮生哭恨同。"]', '["斜漢銀瀾一夜东，飄飄何处五云中。","空留华表千年約，纔畢丹爐九轉功。","形蛻远山孤壙月，影寒深院晓松风。","门人不覩飞昇去，猶與浮生哭恨同。"]', '诗', 'shi', '', NULL, '和襲美傷顧道士 鄭璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecec8663-2b01-4419-9fdd-9627999cac71', '奉和陸魯望白菊', '奉和陸魯望白菊', '9b301366-d1f3-435e-8892-7210be165ee6', '唐', '["白豔輕明帶露痕，始知佳色重難羣。","終朝疑笑梁王雪，盡日慵飛蜀帝魂。","燕雨似翻瑤渚浪，雁風疑卷玉綃紋。","瓊妃若會寬裁剪，堪作蟾宮夜舞裙。"]', '["白豔轻明带露痕，始知佳色重难羣。","終朝疑笑梁王雪，尽日慵飞蜀帝魂。","燕雨似翻瑤渚浪，雁风疑卷玉綃紋。","瓊妃若會寬裁剪，堪作蟾宮夜舞裙。"]', '诗', 'shi', '', NULL, '奉和陸魯望白菊 鄭璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c5bb29-e46d-4ba8-804f-f5cb33797a97', '和襲美索友人酒', '和襲美索友人酒', '9b301366-d1f3-435e-8892-7210be165ee6', '唐', '["乘興閑來小謝家，便裁詩句乞榴花。","邴原雖不無端醉，也愛臨風從鹿車。"]', '["乘兴闲来小謝家，便裁诗句乞榴花。","邴原雖不無端醉，也愛臨风從鹿车。"]', '诗', 'shi', '', NULL, '和襲美索友人酒 鄭璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb3e1096-96d8-42f2-b280-0d9752865453', '文燕潤卿不至', '文燕潤卿不至', '9b301366-d1f3-435e-8892-7210be165ee6', '唐', '["已知羽駕朝金闕，不用燒蘭望玉京。","應是易遷明月好，玉皇留看舞雙成。"]', '["已知羽駕朝金闕，不用燒蘭望玉京。","應是易遷明月好，玉皇留看舞雙成。"]', '诗', 'shi', '', NULL, '文燕潤卿不至 鄭璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a021c72-51ec-44f4-9e77-54ca743e6828', '塞上', '塞上', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["萬里隋城在，三邊虜氣衰。","沙填孤障角，燒斷故關碑。","馬色經寒慘，鵰聲帶晚悲。","將軍正閑暇，留客換歌辭。"]', '["万里隋城在，三邊虜氣衰。","沙填孤障角，燒斷故关碑。","马色經寒慘，鵰声带晚悲。","將軍正闲暇，留客換歌辞。"]', '诗', 'shi', '', NULL, '塞上 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d64b6b4-e16e-45a5-a0aa-2735a4f8e215', '寄永嘉崔道融', '寄永嘉崔道融', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["旅寓雖難定，乘閑是勝遊。","碧雲蕭寺霽，紅樹謝邨秋。","戍鼓和潮暗，船燈照島幽。","詩家多滯此，風景似相留。"]', '["旅寓雖难定，乘闲是勝游。","碧云蕭寺霽，紅樹謝邨秋。","戍鼓和潮暗，船灯照島幽。","诗家多滯此，风景似相留。"]', '诗', 'shi', '', NULL, '寄永嘉崔道融 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b00e90b-87ca-4af0-9d8e-67a84e99e1f0', '下方', '下方', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["三十年來往，中間京洛塵。","倦行今白首，歸臥已清神。","坡暖冬抽筍，松涼夏健人。","更慚徵詔起，避世迹非真。"]', '["三十年来往，中间京洛塵。","倦行今白首，归臥已清神。","坡暖冬抽筍，松涼夏健人。","更慚徵詔起，避世迹非真。"]', '诗', 'shi', '', NULL, '下方 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf3942c-5309-4e6c-b68b-4afc31727a30', '華下', '华下', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["日炙旱雲裂，迸爲千道血。","天地沸一鑊，竟自烹妖孽。","堯湯遇災數，災數還中輟。","何事姦與邪，古來難撲滅。"]', '["日炙旱云裂，迸爲千道血。","天地沸一鑊，竟自烹妖孽。","堯湯遇災數，災數還中輟。","何事姦與邪，古来难撲滅。"]', '诗', 'shi', '', NULL, '華下 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37aef846-ba0c-4581-a27b-647f0ed6dd46', '僧舍貽友', '僧舍貽友', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["笑破人間事，吾徒莫自欺。","解吟僧亦俗，愛舞鶴終卑。","竹上題幽夢，溪邊約敵棋。","舊山歸有阻，不是故遲遲。"]', '["笑破人间事，吾徒莫自欺。","解吟僧亦俗，愛舞鹤終卑。","竹上題幽梦，溪邊約敵棋。","旧山归有阻，不是故遲遲。"]', '诗', 'shi', '', NULL, '僧舍貽友 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab6916a7-d810-4493-bac0-8c5011d97b9d', '下方', '下方', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["昏旦松軒下，怡然對一瓢。","雨微吟思足，花落夢無聊。","細事當棋遣，衰容喜鏡饒。","溪僧有深趣，書至又相邀。"]', '["昏旦松軒下，怡然对一瓢。","雨微吟思足，花落梦無聊。","細事當棋遣，衰容喜镜饒。","溪僧有深趣，书至又相邀。"]', '诗', 'shi', '', NULL, '下方 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf5461f-d960-4d7a-8a73-ceeca751aba9', '華下送文浦', '华下送文浦', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["郊居謝名利，何事最相親。","漸與論詩久，皆知得句新。","川明虹照雨，樹密鳥衝人。","應念從今去，還來嶽下頻。"]', '["郊居謝名利，何事最相親。","漸與論诗久，皆知得句新。","川明虹照雨，樹密鸟衝人。","應念從今去，還来嶽下頻。"]', '诗', 'shi', '', NULL, '華下送文浦 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca42972-dd6a-4289-9f4e-342f57724d9e', '自誡', '自誡', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["我祖銘座右，嘉謀貽厥孫。","勤此苟不怠，令名日可存。","媒衒士所耻，慈儉道所尊。","松柏豈不茂，桃李亦自繁。","衆人皆察察，而我獨昏昏。","取訓於老氏，大辯欲訥言。"]', '["我祖銘座右，嘉謀貽厥孫。","勤此苟不怠，令名日可存。","媒衒士所耻，慈儉道所尊。","松柏豈不茂，桃李亦自繁。","衆人皆察察，而我独昏昏。","取訓於老氏，大辯欲訥言。"]', '诗', 'shi', '', NULL, '自誡 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54663fd-b928-46f0-bb5d-bd1945944b9c', '效陳拾遺子昂感遇二首 一', '效陳拾遺子昂感遇二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["高燕飛何捷，啄害恣羣雛。","人豈玩其暴，華軒容爾居。","強欺自天稟，剛吐信吾徒。","乃知不平者，矯世道終孤。"]', '["高燕飞何捷，啄害恣羣雛。","人豈玩其暴，华軒容爾居。","強欺自天稟，剛吐信吾徒。","乃知不平者，矯世道終孤。"]', '诗', 'shi', '', NULL, '效陳拾遺子昂感遇二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bdd9b51-383d-432b-a92d-186f6c2dfffa', '效陳拾遺子昂感遇二首 二', '效陳拾遺子昂感遇二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["陽和含煦潤，卉木競紛華。","當爲衆所悅，私已汝何誇。","北里祕穠豔，東園鎖名花。","豪奪乃常理，笑君徒咄嗟。"]', '["陽和含煦潤，卉木競紛华。","當爲衆所悅，私已汝何誇。","北里祕穠豔，东园鎖名花。","豪奪乃常理，笑君徒咄嗟。"]', '诗', 'shi', '', NULL, '效陳拾遺子昂感遇二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d00d47e5-01b3-4f6d-aca4-4fd98ad42ff6', '效陳拾遺子昂', '效陳拾遺子昂', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["醜婦競簪花，花多映愈醜。","鄰女恃其姿，掇之不盈手。","量已苟自私，招損乃誰咎。","寵祿既非安，於吾竟何有。"]', '["醜婦競簪花，花多映愈醜。","鄰女恃其姿，掇之不盈手。","量已苟自私，招損乃誰咎。","寵祿既非安，於吾竟何有。"]', '诗', 'shi', '', NULL, '效陳拾遺子昂 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6030294-408d-4a87-97e1-09351beea88c', '感時', '感时', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["好鳥無惡聲，仁獸肯狂噬。","寧教鸚鵡啞，不遣麒麟細。","人人語與默，唯觀利與勢。","愛毀亦自遭，掩謗終失計。"]', '["好鸟無惡声，仁獸肯狂噬。","寧教鸚鵡啞，不遣麒麟細。","人人語與默，唯观利與勢。","愛毀亦自遭，掩謗終失計。"]', '诗', 'shi', '', NULL, '感時 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c3f808-d989-4378-8294-5cbea8c14dd9', '秋思', '秋思', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["身病時亦危，逢秋多慟哭。","風波一搖蕩，天地幾翻覆。","孤螢出荒池，落葉穿破屋。","勢利長草草，何人訪幽獨。"]', '["身病时亦危，逢秋多慟哭。","风波一搖蕩，天地幾翻覆。","孤螢出荒池，落葉穿破屋。","勢利长草草，何人訪幽独。"]', '诗', 'shi', '', NULL, '秋思 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b1ff3a-4f6f-4fbf-8c44-8bba127d9f66', '早春', '早春', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["傷懷同客處，病眼却花朝。","草嫩侵沙短，冰輕著雨消。","風光知可愛，容髪不相饒。","早晚丹丘去，飛書肯見招。"]', '["傷懷同客处，病眼却花朝。","草嫩侵沙短，冰轻著雨消。","风光知可愛，容髪不相饒。","早晚丹丘去，飞书肯见招。"]', '诗', 'shi', '', NULL, '早春 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03d611e-5d89-4095-9eac-6a385e0fb095', '上陌梯寺懷舊僧二首 一', '上陌梯寺懷旧僧二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["雲根禪客居，皆說舊無廬。","松日明金像，山風嚮木魚。","依棲應不阻，名利本來疎。","縱有人相問，林間懶拆書。"]', '["云根禪客居，皆说旧無廬。","松日明金像，山风嚮木鱼。","依棲應不阻，名利本来疎。","縱有人相问，林间懶拆书。"]', '诗', 'shi', '', NULL, '上陌梯寺懷舊僧二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94c5527-f273-49a9-82dc-73ed7fb42a62', '上陌梯寺懷舊僧二首 二', '上陌梯寺懷旧僧二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["高鴉隔谷見，路轉寺西門。","塔影蔭泉脉，山苗侵燒痕。","鐘疎含杳靄，閤迥亙黃昏。","更待他僧到，長如前信存。"]', '["高鴉隔谷见，路轉寺西门。","塔影蔭泉脉，山苗侵燒痕。","鐘疎含杳靄，閤迥亙黄昏。","更待他僧到，长如前信存。"]', '诗', 'shi', '', NULL, '上陌梯寺懷舊僧二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efcfa628-fff4-437f-a738-c9b1fe44a009', '寄懷元秀上人', '寄懷元秀上人', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["悠悠干祿利，草草廢漁樵。","身世堪惆悵，風騷頓寂寥。","高秋期步野，積雨放趨朝。","得句如相憶，莎齋且見招。"]', '["悠悠干祿利，草草廢漁樵。","身世堪惆悵，风騷頓寂寥。","高秋期步野，積雨放趨朝。","得句如相憶，莎斋且见招。"]', '诗', 'shi', '', NULL, '寄懷元秀上人 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66fea6aa-a90c-4a06-bdad-c83c241ddbcb', '次韻和秀上人遊南五臺', '次韻和秀上人游南五台', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["中峰曾到處，題記沒蒼苔。","振錫傳深谷，翻經想舊臺。","危松臨砌偃，驚鹿驀溪來。","內殿御詩切，身迴心未迴。"]', '["中峰曾到处，題記沒蒼苔。","振錫傳深谷，翻經想旧台。","危松臨砌偃，驚鹿驀溪来。","內殿御诗切，身迴心未迴。"]', '诗', 'shi', '', NULL, '次韻和秀上人遊南五臺 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c151dd4-1277-4d8d-a593-ca7051f16f93', '贈圓昉公', '贈圓昉公', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["天階讓紫衣，冷格鶴猶卑。","道勝嫌名出，身閑覺老遲。","曉香延宿火，寒磬度高枝。","每說長松寺，他年與我期。"]', '["天階讓紫衣，冷格鹤猶卑。","道勝嫌名出，身闲覺老遲。","晓香延宿火，寒磬度高枝。","每说长松寺，他年與我期。"]', '诗', 'shi', '', NULL, '贈圓昉公 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6200f915-f9f1-4e37-b582-3e3257312600', '贈信美寺岑上人', '贈信美寺岑上人', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["巡禮諸方遍，湘南頻有緣。","焚香老山寺，乞食向江船。","紗碧籠名畫，燈寒照淨禪。","我來能永日，蓮漏滴寒泉。"]', '["巡禮諸方遍，湘南頻有緣。","焚香老山寺，乞食向江船。","紗碧籠名畫，灯寒照淨禪。","我来能永日，蓮漏滴寒泉。"]', '诗', 'shi', '', NULL, '贈信美寺岑上人 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66dd272d-28ba-4a9e-ab1f-c782204ba6e8', '江行二首 一', '江行二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["地闊分吳塞，楓高映楚天。","曲塘春盡雨，方響夜深船。","行紀添新夢，羇愁甚往年。","何時京洛路，馬上見人煙。"]', '["地闊分吳塞，楓高映楚天。","曲塘春尽雨，方响夜深船。","行紀添新梦，羇愁甚往年。","何时京洛路，马上见人煙。"]', '诗', 'shi', '', NULL, '江行二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324bdea3-0134-40ec-919b-f634e53db080', '江行二首 二', '江行二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["初程風信好，迴望失津樓。","日帶潮聲晚，煙含楚色秋。","戍旗當遠客，島樹轉驚鷗。","此去非名利，孤帆任白頭。"]', '["初程风信好，迴望失津楼。","日带潮声晚，煙含楚色秋。","戍旗當远客，島樹轉驚鷗。","此去非名利，孤帆任白头。"]', '诗', 'shi', '', NULL, '江行二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('928167f0-6d43-49ce-b79e-430769b40442', '長安贈王注', '长安贈王注', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["正下搜賢詔，多君獨避名。","客來當意愜，花發遇歌成。","樂地留高趣，權門讓後生。","東方御閑駟，園外好同行。"]', '["正下搜賢詔，多君独避名。","客来當意愜，花發遇歌成。","乐地留高趣，權门讓後生。","东方御闲駟，园外好同行。"]', '诗', 'shi', '', NULL, '長安贈王注 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc69017-db2e-4c60-b6c3-241fd9eb1450', '贈步寄李員外', '贈步寄李員外', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["危橋轉溪路，經雨石叢荒。","幽瀑下仙果，孤巢懸夕陽。","病辭青瑣祕，心在紫芝房。","更喜諧招隱，詩家有望郎。"]', '["危橋轉溪路，經雨石叢荒。","幽瀑下仙果，孤巢懸夕陽。","病辞青瑣祕，心在紫芝房。","更喜諧招隐，诗家有望郎。"]', '诗', 'shi', '', NULL, '贈步寄李員外 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b73496-a4d7-4fbf-8dc8-765978255e84', '寄鄭仁規', '寄鄭仁規', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["清才鄭小戎，標的貴遊中。","萬里雲無侶，三山鶴不籠。","香和丹地暖，晚着綵衣風。","榮路期經濟，唯應在至公。"]', '["清才鄭小戎，標的貴游中。","万里云無侶，三山鹤不籠。","香和丹地暖，晚着綵衣风。","榮路期經濟，唯應在至公。"]', '诗', 'shi', '', NULL, '寄鄭仁規 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54395fd2-5b20-4b7e-88c8-8b9086fc8059', '寄考功王員外', '寄考功王員外', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["喜聞三字耗，閑客是陪遊。","白鳥閑疎索，青山日滯留。","琴如高韻稱，詩愧逸才酬。","更勉匡君志，論思在獻謀。"]', '["喜闻三字耗，闲客是陪游。","白鸟闲疎索，青山日滯留。","琴如高韻稱，诗愧逸才酬。","更勉匡君志，論思在獻謀。"]', '诗', 'shi', '', NULL, '寄考功王員外 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b076717-ce79-4aa5-bf69-1b9e8e1562d4', '雜言', '杂言', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["鳥飛飛，兔蹶蹶，朝來暮去驅時節。","女媧只解補青天，不解煎膠黏日月。"]', '["鸟飞飞，兔蹶蹶，朝来暮去驱时節。","女媧只解補青天，不解煎膠黏日月。"]', '诗', 'shi', '', NULL, '雜言 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5256e95b-1288-4a1b-934b-253319c6eba1', '陳疾', '陳疾', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["自憐旅舍亦酣歌，世路無機奈爾何。","霄漢逼來心不動，鬢毛白盡興猶多。","殘陽暫照鄉關近，遠鳥因投嶽廟過。","閑得此身歸未得，磬聲深夏隔煙蘿。"]', '["自怜旅舍亦酣歌，世路無機奈爾何。","霄漢逼来心不动，鬢毛白尽兴猶多。","殘陽暫照乡关近，远鸟因投嶽廟過。","闲得此身归未得，磬声深夏隔煙蘿。"]', '诗', 'shi', '', NULL, '陳疾 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d31c75c-98e3-45f4-bd77-25b52e6534db', '淅上 一', '淅上 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["華下支離已隔河，又來此地避干戈。","山田漸廣猨時到，邨舍新添燕亦多。","丹桂石楠宜並長，秦雲楚雨暗相和。","兒童栗熟迷歸路，歸得仍隨牧豎歌。"]', '["华下支離已隔河，又来此地避干戈。","山田漸廣猨时到，邨舍新添燕亦多。","丹桂石楠宜並长，秦云楚雨暗相和。","兒童栗熟迷归路，归得仍隨牧豎歌。"]', '诗', 'shi', '', NULL, '淅上 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05d9f2e3-da4c-4e13-959d-22bd7b6a6565', '淅上 二', '淅上 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["西北鄉關近帝京，煙塵一片正傷情。","愁看地色連空色，靜聽歌聲似哭聲。","紅蓼滿邨人不在，青山遶檻路難平。","從他煙棹更南去，休向津頭問去程。"]', '["西北乡关近帝京，煙塵一片正傷情。","愁看地色連空色，静听歌声似哭声。","紅蓼满邨人不在，青山遶檻路难平。","從他煙棹更南去，休向津头问去程。"]', '诗', 'shi', '', NULL, '淅上 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee7331d3-f67c-4339-8071-0dff54723b5e', '山中', '山中', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["全家與我戀孤岑，蹋得蒼苔一徑深。","逃難人多分隙地，放生麋大出寒林。","名應不朽輕仙骨，理到忘機近佛心。","昨夜前溪驟雷雨，晚晴閑步數峰吟。"]', '["全家與我戀孤岑，蹋得蒼苔一徑深。","逃难人多分隙地，放生麋大出寒林。","名應不朽轻仙骨，理到忘機近佛心。","昨夜前溪驟雷雨，晚晴闲步數峰吟。"]', '诗', 'shi', '', NULL, '山中 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('486407cc-1e55-4d48-9ec4-a114294100da', '寄贈詩僧秀公', '寄贈诗僧秀公', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["靈一心傳清塞心，可公吟後礎公吟。","近來雅道相親少，惟仰吾師所得深。","好句未停無暇日，舊山歸老有東林。","冷曹孤宦甘寥落，多謝攜筇數訪尋。"]', '["靈一心傳清塞心，可公吟後礎公吟。","近来雅道相親少，惟仰吾師所得深。","好句未停無暇日，旧山归老有东林。","冷曹孤宦甘寥落，多謝携筇數訪尋。"]', '诗', 'shi', '', NULL, '寄贈詩僧秀公 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47dd5e5a-784c-4887-807f-0f11239b63fa', '重陽日訪元秀上人', '重陽日訪元秀上人', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["紅葉黃花秋景寬，醉吟朝夕在樊川。","却嫌今日登山俗，且共高僧對榻眠。","別畫長懷吳寺壁，宜茶偏賞霅溪泉。","歸來童穉爭相笑，何事無人與酒船。"]', '["紅葉黄花秋景寬，醉吟朝夕在樊川。","却嫌今日登山俗，且共高僧对榻眠。","別畫长懷吳寺壁，宜茶偏賞霅溪泉。","归来童穉爭相笑，何事無人與酒船。"]', '诗', 'shi', '', NULL, '重陽日訪元秀上人 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191a514d-cf9d-4a6d-b5e6-d80e34e324b9', '丁未歲歸王官谷', '丁未歲归王官谷', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["家山牢落戰塵西，匹馬偷歸路已迷。","塚上卷旗人簇立，花邊移寨鳥驚啼。","本來薄俗輕文字，却致中原動鼓鼙。","將取一壺閑日月，長歌深入武陵溪。"]', '["家山牢落戰塵西，匹马偷归路已迷。","塚上卷旗人簇立，花邊移寨鸟驚啼。","本来薄俗轻文字，却致中原动鼓鼙。","將取一壺闲日月，长歌深入武陵溪。"]', '诗', 'shi', '', NULL, '丁未歲歸王官谷 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b98a2b0e-47b3-4b61-bfdb-ed90e776418e', '書懷', '书懷', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["病來猶強引雛行，力上東原欲試耕。","幾處馬嘶春麥長，一川人喜雪峰晴。","閑知有味心難肯，道貴謀安迹易平。","陶令若能兼不飲，無弦琴亦是沽名。"]', '["病来猶強引雛行，力上东原欲試耕。","幾处马嘶春麦长，一川人喜雪峰晴。","闲知有味心难肯，道貴謀安迹易平。","陶令若能兼不饮，無弦琴亦是沽名。"]', '诗', 'shi', '', NULL, '書懷 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86178605-1edd-42bd-be95-27e83bd73670', '退棲', '退棲', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["宦遊蕭索爲無能，移住中條最上層。","得劒乍如添健僕，亡書久似失良朋。","燕昭不是空憐馬，支遁何妨亦愛鷹。","自此致身繩檢外，肯教世路日兢兢。"]', '["宦游蕭索爲無能，移住中條最上層。","得劒乍如添健僕，亡书久似失良朋。","燕昭不是空怜马，支遁何妨亦愛鷹。","自此致身繩檢外，肯教世路日兢兢。"]', '诗', 'shi', '', NULL, '退棲 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9fd7852-b42a-4812-bf67-b5e8c8016eb9', '五十', '五十', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["閑身事少只題詩，五十今來覺陡衰。","清秩偶叨非養望，丹方頻試更堪疑。","髭鬚強染三分折，弦管遙聽一半悲。","漉酒有巾無黍釀，負他黃菊滿東籬。"]', '["闲身事少只題诗，五十今来覺陡衰。","清秩偶叨非養望，丹方頻試更堪疑。","髭鬚強染三分折，弦管遙听一半悲。","漉酒有巾無黍釀，負他黄菊满东籬。"]', '诗', 'shi', '', NULL, '五十 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55d268f-15d6-4e13-b0b1-f4a7ae60729a', '新歲對寫真', '新歲对寫真', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["得見明時下壽身，須甘歲酒更移巡。","生情暗結千重恨，寒勢常欺一半春。","文武輕銷丹竈火，市朝偏貴黑頭人。","自傷衰颯慵開鏡，擬與兒童別寫真。"]', '["得见明时下壽身，須甘歲酒更移巡。","生情暗結千重恨，寒勢常欺一半春。","文武轻銷丹竈火，市朝偏貴黑头人。","自傷衰颯慵开镜，擬與兒童別寫真。"]', '诗', 'shi', '', NULL, '新歲對寫真 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eef68a3-594a-4f31-b0d7-97096d3ecac7', '華下', '华下', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["籜冠新帶步池塘，逸韻偏宜夏景長。","扶起綠荷承早露，驚迴白鳥入殘陽。","久無書去干時貴，時有僧來自故鄉。","不用名山訪真訣，退休便是養生方。"]', '["籜冠新带步池塘，逸韻偏宜夏景长。","扶起綠荷承早露，驚迴白鸟入殘陽。","久無书去干时貴，时有僧来自故乡。","不用名山訪真訣，退休便是養生方。"]', '诗', 'shi', '', NULL, '華下 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4798e715-e669-4f0f-b63c-650c15095569', '重陽山居', '重陽山居', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["詩人自古恨難窮，暮節登臨且喜同。","四望交親兵亂後，一川風物笛聲中。","菊殘深處迴幽蝶，陂動晴光下早鴻。","明日更期來此醉，不堪寂寞對衰翁。"]', '["诗人自古恨难窮，暮節登臨且喜同。","四望交親兵亂後，一川风物笛声中。","菊殘深处迴幽蝶，陂动晴光下早鴻。","明日更期来此醉，不堪寂寞对衰翁。"]', '诗', 'shi', '', NULL, '重陽山居 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3837af-569a-4108-b84b-690ef095c674', '爭名', '爭名', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["爭名豈在更搜奇，不朽纔消一句詩。","窮辱未甘英氣阻，乖疎還有正人知。","荷香浥露侵衣潤，松影和風傍枕移。","只此共棲塵外境，無妨亦戀好文時。"]', '["爭名豈在更搜奇，不朽纔消一句诗。","窮辱未甘英氣阻，乖疎還有正人知。","荷香浥露侵衣潤，松影和风傍枕移。","只此共棲塵外境，無妨亦戀好文时。"]', '诗', 'shi', '', NULL, '爭名 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06857fee-89de-4dd0-9da7-c337450a5be4', '光啓四年春戊申', '光啓四年春戊申', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["亂後燒殘數架書，峰前猶自戀吾廬。","忘機漸喜逢人少，覽鏡空憐待鶴疎。","孤嶼池痕春漲滿，小闌花韻午晴初。","酣歌自適逃名久，不必門多長者車。"]', '["亂後燒殘數架书，峰前猶自戀吾廬。","忘機漸喜逢人少，覽镜空怜待鹤疎。","孤嶼池痕春漲满，小闌花韻午晴初。","酣歌自適逃名久，不必门多长者车。"]', '诗', 'shi', '', NULL, '光啓四年春戊申 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5605e1-f5a3-459a-916c-5121b03f1b93', '丁巳重陽', '丁巳重陽', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["重陽未到已登臨，探得黃花且獨斟。","客舍喜逢連日雨，家山似響隔河砧。","亂來已失耕桑計，病後休論濟活心。","自賀逢時能自棄，歸鞭唯拍馬韉吟。"]', '["重陽未到已登臨，探得黄花且独斟。","客舍喜逢連日雨，家山似响隔河砧。","亂来已失耕桑計，病後休論濟活心。","自賀逢时能自棄，归鞭唯拍马韉吟。"]', '诗', 'shi', '', NULL, '丁巳重陽 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9fc1bf6-82ba-4faa-8a47-f4fb0c9b72ca', '喜王駕小儀重陽相訪', '喜王駕小儀重陽相訪', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["白菊初開臥內明，聞君相訪病身輕。","樽前且撥傷心事，谿上還隨覓句行。","幽鶴傍人疑舊識，殘蟬向日噪新晴。","擬將寂寞同留住，且勸康時立大名。"]', '["白菊初开臥內明，闻君相訪病身轻。","樽前且撥傷心事，谿上還隨覓句行。","幽鹤傍人疑旧識，殘蟬向日噪新晴。","擬將寂寞同留住，且勸康时立大名。"]', '诗', 'shi', '', NULL, '喜王駕小儀重陽相訪 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311fbc4b-0fa4-41ae-a87d-8c80e6ab9ea1', '酬張芬赦後見寄', '酬張芬赦後见寄', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["紫鳳朝銜五色書，陽春忽布網羅除。","已將心變寒灰後，豈料光生腐草餘。","建水風煙收客淚，杜陵花燭夢郊居。","勞君故有詩相贈，欲報瓊瑤愧不如。"]', '["紫鳳朝銜五色书，陽春忽布網羅除。","已將心变寒灰後，豈料光生腐草餘。","建水风煙收客泪，杜陵花燭梦郊居。","勞君故有诗相贈，欲報瓊瑤愧不如。"]', '诗', 'shi', '', NULL, '酬張芬赦後見寄 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3780be15-71e7-4891-b170-b6ea710d9e79', '上元放二雉', '上元放二雉', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["嬰網雖皆困，搴籠喜共歸。","無心期爾報，相見莫驚飛。"]', '["嬰網雖皆困，搴籠喜共归。","無心期爾報，相见莫驚飞。"]', '诗', 'shi', '', NULL, '上元放二雉 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3319c91e-c9de-4525-bf10-f4e20620460b', '中秋', '中秋', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["閑吟秋景外，萬事覺悠悠。","此夜若無月，一年虛過秋。"]', '["闲吟秋景外，万事覺悠悠。","此夜若無月，一年虛過秋。"]', '诗', 'shi', '', NULL, '中秋 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f641475-5695-4fad-b613-2e1ebba9a655', '偶題', '偶題', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["水榭花繁處，春晴日午前。","鳥窺臨檻鏡，馬過隔墻鞭。"]', '["水榭花繁处，春晴日午前。","鸟窺臨檻镜，马過隔墻鞭。"]', '诗', 'shi', '', NULL, '偶題 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a92319-5a60-4ab0-b00d-ada73b9aa429', '閑步', '闲步', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["幾處白煙斷，一川紅樹時。","壞橋侵轍水，殘照背邨碑。"]', '["幾处白煙斷，一川紅樹时。","壞橋侵轍水，殘照背邨碑。"]', '诗', 'shi', '', NULL, '閑步 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31065db0-80c1-472a-b746-e6e6547ce025', '春中', '春中', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["伏溜侵堦潤，繁花隔竹香。","嬌鶯方曉聽，無事過南塘。"]', '["伏溜侵堦潤，繁花隔竹香。","嬌鶯方晓听，無事過南塘。"]', '诗', 'shi', '', NULL, '春中 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ee39cd-082e-4a6d-b9e6-8eb4c59b0fd8', '獨望', '独望', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["綠樹連邨暗，黃花出陌稀。","遠陂春草綠，猶有水禽飛。"]', '["綠樹連邨暗，黄花出陌稀。","远陂春草綠，猶有水禽飞。"]', '诗', 'shi', '', NULL, '獨望 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a1f262-ccbc-4fc2-9d56-2ef38a836e7e', '雜題', '杂題', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["孤枕聞鶯起，幽懷獨悄然。","地融春力潤，花泛曉光鮮。"]', '["孤枕闻鶯起，幽懷独悄然。","地融春力潤，花泛晓光鲜。"]', '诗', 'shi', '', NULL, '雜題 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a3f7b0-2a46-4f86-b8d1-0163b7ef8333', '漫題三首 一', '漫題三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["亂後他鄉節，燒殘故國春。","自憐垂白首，猶伴踏青人。"]', '["亂後他乡節，燒殘故国春。","自怜垂白首，猶伴踏青人。"]', '诗', 'shi', '', NULL, '漫題三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ec9936-6a2f-4279-bd89-b6f98a88e0a5', '漫題三首 二', '漫題三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["齒落傷情久，心驚健忘頻。","蝸廬經歲客，蠶市異鄉人。"]', '["齒落傷情久，心驚健忘頻。","蝸廬經歲客，蠶市異乡人。"]', '诗', 'shi', '', NULL, '漫題三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b144bf27-207a-4850-8ebe-2146dd09c47b', '漫題三首 三', '漫題三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["率怕人言謹，閑宜酒韻高。","山林若無慮，名利不難逃。"]', '["率怕人言謹，闲宜酒韻高。","山林若無慮，名利不难逃。"]', '诗', 'shi', '', NULL, '漫題三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280ea713-4b90-40a5-abde-b4da4f41e038', '河上二首 一', '河上二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["慘慘日將暮，驅羸獨到莊。","沙痕傍墟落，風色入牛羊。"]', '["慘慘日將暮，驱羸独到莊。","沙痕傍墟落，风色入牛羊。"]', '诗', 'shi', '', NULL, '河上二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a52c449-1a0a-4aa0-894a-9e0adb611ca9', '河上二首 二', '河上二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["新霽田園處，夕陽禾黍明。","沙邨平見水，深巷有鷗聲。"]', '["新霽田园处，夕陽禾黍明。","沙邨平见水，深巷有鷗声。"]', '诗', 'shi', '', NULL, '河上二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a17e69-5eb2-435e-9c5b-2cf161a0f166', '早朝', '早朝', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["白日新年好，青春上國多。","街平雙闕近，塵起五雲和。"]', '["白日新年好，青春上国多。","街平雙闕近，塵起五云和。"]', '诗', 'shi', '', NULL, '早朝 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('717745d8-0e3c-445b-a0f0-156c33154365', '即事二首 一', '即事二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["茶爽添詩句，天清瑩道心。","只留鶴一隻，此外是空林。"]', '["茶爽添诗句，天清瑩道心。","只留鹤一隻，此外是空林。"]', '诗', 'shi', '', NULL, '即事二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('617d8bb0-d736-4c4e-a5d6-a9a0be6dd30e', '即事二首 二', '即事二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["御禮徵奇策，人心注盛時。","從來留振滯，只待濟臨危。"]', '["御禮徵奇策，人心注盛时。","從来留振滯，只待濟臨危。"]', '诗', 'shi', '', NULL, '即事二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7050c522-8aa5-4448-aaaf-973b8ae92e2f', '永夜', '永夜', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["永夜疑無日，危時只賴山。","曠懷休戚外，孤跡是非間。"]', '["永夜疑無日，危时只賴山。","曠懷休戚外，孤跡是非间。"]', '诗', 'shi', '', NULL, '永夜 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4292c5dd-41ce-4d02-9217-92be3c63ec3f', '秦關', '秦关', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["形勝今雖在，荒涼恨不窮。","虎狼秦國破，狐兔漢陵空。"]', '["形勝今雖在，荒涼恨不窮。","虎狼秦国破，狐兔漢陵空。"]', '诗', 'shi', '', NULL, '秦關 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944a15cc-9601-4597-b386-0321203bba65', '渡江', '渡江', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["秋江共僧渡，鄉淚滴船回。","一夜吳船夢，家書立馬開。"]', '["秋江共僧渡，乡泪滴船回。","一夜吳船梦，家书立马开。"]', '诗', 'shi', '', NULL, '渡江 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fff0b93-48bd-4150-bbca-3b0b4361c708', '退居漫題七首 一', '退居漫題七首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["花缺傷難綴，鶯喧奈細聽。","惜春春已晚，珍重草青青。"]', '["花缺傷难綴，鶯喧奈細听。","惜春春已晚，珍重草青青。"]', '诗', 'shi', '', NULL, '退居漫題七首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25119b26-d21f-4e1e-bf06-0f1f95756dbb', '退居漫題七首 二', '退居漫題七首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["堤柳自綿綿，幽人無恨牽。","只憂詩病發，莫寄校書牋。"]', '["堤柳自綿綿，幽人無恨牽。","只憂诗病發，莫寄校书牋。"]', '诗', 'shi', '', NULL, '退居漫題七首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642434a5-f200-4aeb-8e5a-ebbc865b7388', '退居漫題七首 三', '退居漫題七首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["燕語曾來客，花催欲別人。","莫愁春又過，看著又新春。"]', '["燕語曾来客，花催欲別人。","莫愁春又過，看著又新春。"]', '诗', 'shi', '', NULL, '退居漫題七首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('396d028e-3b74-4aa6-9dc6-3925946fb683', '退居漫題七首 四', '退居漫題七首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["身外都無事，山中久避喧。","破巢看乳燕，留果待啼猨。"]', '["身外都無事，山中久避喧。","破巢看乳燕，留果待啼猨。"]', '诗', 'shi', '', NULL, '退居漫題七首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1461e938-82d2-49d2-aa04-5b73297345cb', '退居漫題七首 五', '退居漫題七首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["詩家通籍美，工部與司勳。","高賈雖難敵，微官偶勝君。"]', '["诗家通籍美，工部與司勳。","高賈雖难敵，微官偶勝君。"]', '诗', 'shi', '', NULL, '退居漫題七首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deae5910-8623-45d8-89af-a575d1375064', '退居漫題七首 六', '退居漫題七首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["努力省前非，人生上壽稀。","青雲無直道，暗室有危機。"]', '["努力省前非，人生上壽稀。","青云無直道，暗室有危機。"]', '诗', 'shi', '', NULL, '退居漫題七首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f3f3134-b1eb-491d-bde2-70d1bedcc008', '退居漫題七首 七', '退居漫題七首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["燕拙營巢苦，魚貪觸網驚。","豈緣身外事，亦似我勞形。"]', '["燕拙營巢苦，鱼貪觸網驚。","豈緣身外事，亦似我勞形。"]', '诗', 'shi', '', NULL, '退居漫題七首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb908820-e2ba-4788-9750-8bf7eb1430f7', '即事九首 一', '即事九首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["宿雨川原霽，憑高景物新。","陂痕侵牧馬，雲影帶耕人。"]', '["宿雨川原霽，憑高景物新。","陂痕侵牧马，云影带耕人。"]', '诗', 'shi', '', NULL, '即事九首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35829ea4-b74c-40b2-8752-f567b510952c', '即事九首 二', '即事九首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["十年深隱地，一雨太平心。","匣澀休看劒，窗明復上琴。"]', '["十年深隐地，一雨太平心。","匣澀休看劒，窗明复上琴。"]', '诗', 'shi', '', NULL, '即事九首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d343c673-5610-4d3b-90b0-aabab2e55652', '即事九首 三', '即事九首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["明時那棄置，多病自遲留。","疎磬和吟斷，殘燈照臥幽。"]', '["明时那棄置，多病自遲留。","疎磬和吟斷，殘灯照臥幽。"]', '诗', 'shi', '', NULL, '即事九首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e835e0a-55bf-4543-95f5-01226f0a4178', '即事九首 四', '即事九首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["衰鬢閑生少，丹梯望覺危。","松須依石長，鶴不傍人卑。"]', '["衰鬢闲生少，丹梯望覺危。","松須依石长，鹤不傍人卑。"]', '诗', 'shi', '', NULL, '即事九首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47aada3f-adea-49a9-8a3a-d8bb68d0dd0e', '即事九首 五', '即事九首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["落葉頻驚鹿，連峰欲映鵰。","此生詩病苦，此病更蕭條。"]', '["落葉頻驚鹿，連峰欲映鵰。","此生诗病苦，此病更蕭條。"]', '诗', 'shi', '', NULL, '即事九首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdeb6658-1969-42fb-a884-c04a37a751c6', '即事九首 六', '即事九首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["旅思又驚夏，庭前長小松。","遠峰生貴氣，殘月歛衰容。"]', '["旅思又驚夏，庭前长小松。","远峰生貴氣，殘月歛衰容。"]', '诗', 'shi', '', NULL, '即事九首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45efd508-a8b7-4be9-8657-1c5d75233f30', '即事九首 七', '即事九首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["林鳥頻窺靜，家人亦笑慵。","舊居留穩枕，歸臥聽秋鐘。"]', '["林鸟頻窺静，家人亦笑慵。","旧居留穩枕，归臥听秋鐘。"]', '诗', 'shi', '', NULL, '即事九首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab0ff33-b2f1-4e02-a686-e69bc20b33c0', '即事九首 八', '即事九首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["華宇知難保，燒來又却修。","只應巢燕惜，未必主人留。"]', '["华宇知难保，燒来又却修。","只應巢燕惜，未必主人留。"]', '诗', 'shi', '', NULL, '即事九首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe868feb-a0d9-4aaf-b680-09846e7a152b', '即事九首 九', '即事九首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["幽鳥穿籬去，鄰翁採藥回。","雲從潭底出，花向佛前開。"]', '["幽鸟穿籬去，鄰翁採藥回。","云從潭底出，花向佛前开。"]', '诗', 'shi', '', NULL, '即事九首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e03e8d-d53e-40cb-818a-90548f16eac6', '松滋渡二首 一', '松滋渡二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["步上短亭久，看回官渡船。","江鄉宜晚霽，楚老語豐年。"]', '["步上短亭久，看回官渡船。","江乡宜晚霽，楚老語豐年。"]', '诗', 'shi', '', NULL, '松滋渡二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9476398e-ebee-4f59-a76e-f0a0e4208dca', '松滋渡二首 二', '松滋渡二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["楚岫接鄉思，茫茫歸路迷。","更堪斑竹驛，初聽鷓鴣啼。"]', '["楚岫接乡思，茫茫归路迷。","更堪斑竹驛，初听鷓鴣啼。"]', '诗', 'shi', '', NULL, '松滋渡二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('589ba6ca-57a8-44ac-9dde-cdc35813252e', '華清宮', '华清宮', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["帝業山河固，離宮宴幸頻。","豈知驅戰馬，只是太平人。"]', '["帝業山河固，離宮宴幸頻。","豈知驱戰马，只是太平人。"]', '诗', 'shi', '', NULL, '華清宮 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cac16a1-a82a-4259-864c-87a1b6e37604', '牛頭寺', '牛头寺', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["終南最佳處，禪誦出青霄。","羣木澄幽寂，疎煙泛泬寥。"]', '["終南最佳处，禪誦出青霄。","羣木澄幽寂，疎煙泛泬寥。"]', '诗', 'shi', '', NULL, '牛頭寺 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280521a5-744f-4ddc-ade6-bbc6e6b54661', '感時上盧相', '感时上盧相', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["兵待皇威振，人隨國步安。","萬方休望幸，封岳始鳴鑾。"]', '["兵待皇威振，人隨国步安。","万方休望幸，封岳始鳴鑾。"]', '诗', 'shi', '', NULL, '感時上盧相 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f2f842-d2a2-49b7-b638-cc4aa837dda1', '亂後三首 一', '亂後三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["喪亂家難保，艱虞病懶醫。","空將憂國淚，猶擬灑丹墀。"]', '["喪亂家难保，艱虞病懶醫。","空將憂国泪，猶擬灑丹墀。"]', '诗', 'shi', '', NULL, '亂後三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8df6375-2d0d-4030-9736-b92ad3941eba', '亂後三首 二', '亂後三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["流芳能幾日，惆悵又聞蟬。","行在多新貴，幽棲獨長年。"]', '["流芳能幾日，惆悵又闻蟬。","行在多新貴，幽棲独长年。"]', '诗', 'shi', '', NULL, '亂後三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5991324-5a5b-4c5b-95b8-f0fc8c1471b3', '亂後三首 三', '亂後三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["世事嘗艱險，僧居慣寂寥。","美香聞夜合，清景見寅朝。"]', '["世事嘗艱險，僧居慣寂寥。","美香闻夜合，清景见寅朝。"]', '诗', 'shi', '', NULL, '亂後三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c08ec4-d704-4984-b048-a5d21ef8bff8', '秋景', '秋景', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["景物皆難駐，傷春復怨秋。","旋書紅葉落，擬畫碧雲收。"]', '["景物皆难駐，傷春复怨秋。","旋书紅葉落，擬畫碧云收。"]', '诗', 'shi', '', NULL, '秋景 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43bf48f2-6c81-48ae-9235-9524d609cd4c', '避亂', '避亂', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["離亂身偶在，竄跡任浮沈。","虎暴荒居逈，螢孤黑夜深。"]', '["離亂身偶在，竄跡任浮沈。","虎暴荒居逈，螢孤黑夜深。"]', '诗', 'shi', '', NULL, '避亂 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed8f343-abdd-42b4-9693-4aaca392e76e', '長亭', '长亭', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["梅雨和鄉淚，終年共酒衣。","殷勤華表鶴，羨爾亦曾歸。"]', '["梅雨和乡泪，終年共酒衣。","殷勤华表鹤，羨爾亦曾归。"]', '诗', 'shi', '', NULL, '長亭 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf6fa2f9-6739-4685-81d3-6a93a61547da', '邨西杏花二首 一', '邨西杏花二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["薄膩力偏羸，看看愴別時。","東風狂不惜，西子病難醫。"]', '["薄膩力偏羸，看看愴別时。","东风狂不惜，西子病难醫。"]', '诗', 'shi', '', NULL, '邨西杏花二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05d06cb0-941d-4e87-82d5-bc3bb89562a6', '邨西杏花二首 二', '邨西杏花二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["肌細分紅脉，香濃破紫苞。","無因留得翫，爭忍折來拋。"]', '["肌細分紅脉，香濃破紫苞。","無因留得翫，爭忍折来拋。"]', '诗', 'shi', '', NULL, '邨西杏花二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc1b07d-cf86-49f1-ab28-cede8b546e49', '獨坐', '独坐', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["幽徑入桑麻，塢西逢一家。","編籬薪帶繭，補屋草和花。"]', '["幽徑入桑麻，塢西逢一家。","編籬薪带繭，補屋草和花。"]', '诗', 'shi', '', NULL, '獨坐 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bab43e-247f-437c-be6c-a7e0b0c02516', '借居', '借居', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["借住郊園久，仍逢夏景新。","綠苔行屐穩，黃鳥傍窗頻。"]', '["借住郊园久，仍逢夏景新。","綠苔行屐穩，黄鸟傍窗頻。"]', '诗', 'shi', '', NULL, '借居 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b02b95ac-9edf-42a1-ae06-84810e653035', '重陽', '重陽', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["菊開猶阻雨，蝶意切於人。","亦應知暮節，不比惜殘春。"]', '["菊开猶阻雨，蝶意切於人。","亦應知暮節，不比惜殘春。"]', '诗', 'shi', '', NULL, '重陽 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5def74-0479-43f6-bc6d-7d96f1d96f86', '偶書五首 一', '偶书五首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["衰榭當何懺，惟應悔壯圖。","磬聲花外遠，人影塔前孤。"]', '["衰榭當何懺，惟應悔壯圖。","磬声花外远，人影塔前孤。"]', '诗', 'shi', '', NULL, '偶書五首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52aa3c65-0bdb-4c7e-9f79-f3a80baec277', '偶書五首 二', '偶书五首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["色變鶯雛長，竿齊笋籜垂。","白頭身偶在，清夏景還移。"]', '["色变鶯雛长，竿齊笋籜垂。","白头身偶在，清夏景還移。"]', '诗', 'shi', '', NULL, '偶書五首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1291bf17-2ee8-4fed-bf18-62a9e1a8ef3f', '偶書五首 三', '偶书五首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["蜀妓輕成妙，吳娃狎共纖。","晚妝留拜月，卷上水精簾。"]', '["蜀妓轻成妙，吳娃狎共纖。","晚妝留拜月，卷上水精簾。"]', '诗', 'shi', '', NULL, '偶書五首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfb13c0f-9ec2-4183-a7ee-987f7e958ada', '偶書五首 四', '偶书五首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["獨步荒郊暮，沉思遠墅幽。","平生多少事，彈指一時休。"]', '["独步荒郊暮，沉思远墅幽。","平生多少事，彈指一时休。"]', '诗', 'shi', '', NULL, '偶書五首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e1c650-9206-45f0-9546-9bed669ba92b', '偶書五首 五', '偶书五首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["掩謗知迎吠，欺心見強顏。","有名人易困，無契債難還。"]', '["掩謗知迎吠，欺心见強顏。","有名人易困，無契債难還。"]', '诗', 'shi', '', NULL, '偶書五首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56978f6f-77ef-4734-a9f0-9a4f9fd5b0ea', '雜題九首 一', '杂題九首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["病來勝未病，名縛便忘名。","今日甘爲客，當時注愍征。"]', '["病来勝未病，名縛便忘名。","今日甘爲客，當时注愍征。"]', '诗', 'shi', '', NULL, '雜題九首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f263db70-5f4a-4d41-95b0-36339911b199', '雜題九首 二', '杂題九首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["暑濕深山雨，荒居破屋燈。","此生無懺處，此去作高僧。"]', '["暑濕深山雨，荒居破屋灯。","此生無懺处，此去作高僧。"]', '诗', 'shi', '', NULL, '雜題九首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcba4f27-75c3-4eec-8240-d2b5d391de9a', '雜題九首 三', '杂題九首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不須頻悵望，且喜脫喧囂。","亦有終焉意，陂南看稻苗。"]', '["不須頻悵望，且喜脫喧囂。","亦有終焉意，陂南看稻苗。"]', '诗', 'shi', '', NULL, '雜題九首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d15f99-939a-4aa7-a0b8-aa7a3d33b72e', '雜題九首 四', '杂題九首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["樓帶猨吟迥，庭容鶴舞寬。","曬書因閱畫，封藥偶和丹。"]', '["楼带猨吟迥，庭容鹤舞寬。","曬书因閱畫，封藥偶和丹。"]', '诗', 'shi', '', NULL, '雜題九首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b739bfd-6cf4-4d2e-b84e-4c68cd612ef4', '雜題九首 五', '杂題九首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["宴罷論詩久，亭高拜表頻。","岸香蕃舶月，洲色海煙春。"]', '["宴罷論诗久，亭高拜表頻。","岸香蕃舶月，洲色海煙春。"]', '诗', 'shi', '', NULL, '雜題九首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad739a0-15e5-422a-a6fe-82d49ae24763', '雜題九首 六', '杂題九首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["驛步堤縈閣，軍城鼓振橋。","鷗和湖鴈下，雪隔嶺梅飄。"]', '["驛步堤縈閣，軍城鼓振橋。","鷗和湖鴈下，雪隔嶺梅飄。"]', '诗', 'shi', '', NULL, '雜題九首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d763ed4-d066-4824-8a67-e4fe216ca6d5', '雜題九首 七', '杂題九首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["帶雪南山道，和鐘北闕明。","太平當共賀，開化喝來聲。"]', '["带雪南山道，和鐘北闕明。","太平當共賀，开化喝来声。"]', '诗', 'shi', '', NULL, '雜題九首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c3bfe79-4324-4e22-bf74-b3d4b5fe54bd', '雜題九首 八', '杂題九首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["舴艋猨偷上，蜻蜓燕競飛。","樵香燒桂子，苔濕挂莎衣。"]', '["舴艋猨偷上，蜻蜓燕競飞。","樵香燒桂子，苔濕挂莎衣。"]', '诗', 'shi', '', NULL, '雜題九首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('632a0629-2933-452f-ad6b-c423730ce5f7', '雜題九首 九', '杂題九首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["溪漲漁家近，煙收鳥道高。","松花飄可惜，睡裏灑離騷。"]', '["溪漲漁家近，煙收鸟道高。","松花飄可惜，睡裏灑離騷。"]', '诗', 'shi', '', NULL, '雜題九首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216be6e1-15de-4193-bd53-392c27719db8', '古樂府', '古乐府', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["一葉隨西風，君行亦向東。","知妾飛書意，無勞待早鴻。"]', '["一葉隨西风，君行亦向东。","知妾飞书意，無勞待早鴻。"]', '诗', 'shi', '', NULL, '古樂府 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51582f27-77ec-44f5-b0c2-a74ff9278b41', '有感', '有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["燈影看鬚黑，墻陰惜草青。","歲闌悲物我，同是冒霜螢。"]', '["灯影看鬚黑，墻陰惜草青。","歲闌悲物我，同是冒霜螢。"]', '诗', 'shi', '', NULL, '有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502bb117-0aa5-40f3-985a-55756f00aca2', '休休亭', '休休亭', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["且喜安能保，那堪病更憂。","可憐藜杖者，真箇種瓜侯。"]', '["且喜安能保，那堪病更憂。","可怜藜杖者，真箇種瓜侯。"]', '诗', 'shi', '', NULL, '休休亭 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a30945-1d6c-45d1-a890-07a69c70a863', '漫書二首 一', '漫书二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["剩欲逢花折，判須冒雨頻。","晴明開漸少，莫怕濕新巾。"]', '["剩欲逢花折，判須冒雨頻。","晴明开漸少，莫怕濕新巾。"]', '诗', 'shi', '', NULL, '漫書二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd395574-33d7-4941-b512-0d98be448ab5', '漫書二首 二', '漫书二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["小蝶爾何競，追飛不憚勞。","遠教羣雀見，寧悟禍梯高。"]', '["小蝶爾何競，追飞不憚勞。","远教羣雀见，寧悟禍梯高。"]', '诗', 'shi', '', NULL, '漫書二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef87aeac-ac09-4e9a-ba85-2d0e2915e710', '歲盡二首 一', '歲尽二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["明日添一歲，端憂奈爾何。","衝寒出洞口，猶校夕陽多。"]', '["明日添一歲，端憂奈爾何。","衝寒出洞口，猶校夕陽多。"]', '诗', 'shi', '', NULL, '歲盡二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7085cebb-39b9-400c-b54a-e0f1e9c23e35', '歲盡二首 二', '歲尽二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["莫話傷心事，投春滿鬢霜。","殷勤共尊酒，今歲只殘陽。"]', '["莫話傷心事，投春满鬢霜。","殷勤共尊酒，今歲只殘陽。"]', '诗', 'shi', '', NULL, '歲盡二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9c1ad39-6d59-40b8-8c9d-e08580af84de', '牡丹', '牡丹', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["得地牡丹盛，曉添龍麝香。","主人猶自惜，錦幕護春霜。"]', '["得地牡丹盛，晓添龙麝香。","主人猶自惜，錦幕護春霜。"]', '诗', 'shi', '', NULL, '牡丹 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d715f39-ece2-4776-aee4-312bc9cd7426', '亂後', '亂後', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["羽書傳棧道，風火隔鄉關。","病眼那堪泣，傷心不到間。"]', '["羽书傳棧道，风火隔乡关。","病眼那堪泣，傷心不到间。"]', '诗', 'shi', '', NULL, '亂後 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17332ff8-9ca9-4252-b70d-f3ecd563c434', '春山', '春山', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["可是武陵溪，春芳著路迷。","花明催曙早，雲膩惹空低。"]', '["可是武陵溪，春芳著路迷。","花明催曙早，云膩惹空低。"]', '诗', 'shi', '', NULL, '春山 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b599f1b5-293c-40df-a1b9-4d9f2992a126', '樂府', '乐府', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["寶馬跋塵光，雙馳照路旁。","喧傳報戚里，明日幸長楊。"]', '["寶马跋塵光，雙驰照路旁。","喧傳報戚里，明日幸长楊。"]', '诗', 'shi', '', NULL, '樂府 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a607651e-e710-41c9-b3fc-a690d292a2d9', '亂前上盧相', '亂前上盧相', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["虜黠雖多變，兵驕即易乘。","猶須勞斥候，勿遣大河冰。"]', '["虜黠雖多变，兵驕即易乘。","猶須勞斥候，勿遣大河冰。"]', '诗', 'shi', '', NULL, '亂前上盧相 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b76d72-7227-4ea6-aca7-6d5d36144e18', '有感', '有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["國事皆須救未然，漢家高閣漫凌煙。","功臣盡遣詞人贊，不省滄洲畫魯連。"]', '["国事皆須救未然，漢家高閣漫凌煙。","功臣尽遣词人贊，不省滄洲畫魯連。"]', '诗', 'shi', '', NULL, '有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06e4deb-de9a-4e0e-b049-2bc45cac3f8c', '歌', '歌', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["處處亭臺只壞墻，軍營人學內人妝。","太平故事因君唱，馬上曾聽隔教坊。"]', '["处处亭台只壞墻，軍營人学內人妝。","太平故事因君唱，马上曾听隔教坊。"]', '诗', 'shi', '', NULL, '歌 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b43154e3-9026-403a-9753-3a8d58617911', '偈', '偈', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["人若憎時我亦憎，逃名最要是無能。","後生乞汝殘風月，自作深林不語僧。"]', '["人若憎时我亦憎，逃名最要是無能。","後生乞汝殘风月，自作深林不語僧。"]', '诗', 'shi', '', NULL, '偈 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c624e66-ddcc-4576-8e59-aac837f45fc6', '鸝', '鸝', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不是流鶯獨占春，林間綵翠四時新。","應知擬上屏風畫，偏坐橫枝亦向人。"]', '["不是流鶯独占春，林间綵翠四时新。","應知擬上屏风畫，偏坐橫枝亦向人。"]', '诗', 'shi', '', NULL, '鸝 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff17b57b-4f6b-4190-93b4-72829ac0e3d3', '白菊雜書四首 一', '白菊杂书四首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["黃昏寒立更披襟，露浥清香悅道心。","却笑誰家扃繡戶，正薰龍麝暖鴛衾。"]', '["黄昏寒立更披襟，露浥清香悅道心。","却笑誰家扃繡戶，正薰龙麝暖鴛衾。"]', '诗', 'shi', '', NULL, '白菊雜書四首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13410de4-30e9-4c47-96f8-df7dd6d6e543', '白菊雜書四首 二', '白菊杂书四首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["四面雲屏一帶天，是非斷得自翛然。","此生只是償詩債，白菊開時最不眠。"]', '["四面云屏一带天，是非斷得自翛然。","此生只是償诗債，白菊开时最不眠。"]', '诗', 'shi', '', NULL, '白菊雜書四首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2986234c-d484-47aa-b566-f370e03f2602', '白菊雜書四首 三', '白菊杂书四首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["狂才不足自英雄，僕妾驅令學販舂。","侯印幾人封萬戶，儂家只辦買孤峰。"]', '["狂才不足自英雄，僕妾驱令学販舂。","侯印幾人封万戶，儂家只辦買孤峰。"]', '诗', 'shi', '', NULL, '白菊雜書四首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef63c450-f64a-4b8b-8284-78685e90601d', '白菊雜書四首 四', '白菊杂书四首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["黃鸝囀處誰同聽，白菊開時且剩過。","漫道南朝足流品，由來叔寶不宜多。"]', '["黄鸝囀处誰同听，白菊开时且剩過。","漫道南朝足流品，由来叔寶不宜多。"]', '诗', 'shi', '', NULL, '白菊雜書四首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5e117da-6d26-4752-803e-38f13cad1404', '漫題', '漫題', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["經亂年年厭別離，歌聲喜似太平時。","詞臣更有中興頌，磨取蓮峰便作碑。"]', '["經亂年年厭別離，歌声喜似太平时。","词臣更有中兴頌，磨取蓮峰便作碑。"]', '诗', 'shi', '', NULL, '漫題 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db0dbbc-8061-4c64-a7d3-e9b42a5a6d54', '率題', '率題', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["宦路前銜閑不記，醉鄉佳境興方濃。","一林高竹長遮日，四壁寒山更閏冬。"]', '["宦路前銜闲不記，醉乡佳境兴方濃。","一林高竹长遮日，四壁寒山更閏冬。"]', '诗', 'shi', '', NULL, '率題 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930194ed-c473-45a9-9eec-a6fb9f1c9f70', '磵戶', '磵戶', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["磵戶芳煙接水邨，亂來歸得道仍存。","數竿新竹當軒上，不羨侯家立戟門。"]', '["磵戶芳煙接水邨，亂来归得道仍存。","數竿新竹當軒上，不羨侯家立戟门。"]', '诗', 'shi', '', NULL, '磵戶 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5258d9d9-72fd-4f7e-a80b-544f593e9402', '故鄉杏花', '故乡杏花', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["寄花寄酒喜新開，左把花枝右把杯。","欲問花枝與杯酒，故人何得不同來。"]', '["寄花寄酒喜新开，左把花枝右把杯。","欲问花枝與杯酒，故人何得不同来。"]', '诗', 'shi', '', NULL, '故鄉杏花 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d49baa-4477-49ba-b526-0ee096645387', '華下二首 一', '华下二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["故國春歸未有涯，小欄高檻別人家。","五更惆悵回孤枕，猶自殘燈照落花。"]', '["故国春归未有涯，小欄高檻別人家。","五更惆悵回孤枕，猶自殘灯照落花。"]', '诗', 'shi', '', NULL, '華下二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f52e288d-964f-4f68-8974-fb61ea11b785', '華下二首 二', '华下二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["關外風昏欲雨天，薺花耕倒枕河壖。","邨南寂寞時回望，一隻鴛鴦下渡船。"]', '["关外风昏欲雨天，薺花耕倒枕河壖。","邨南寂寞时回望，一隻鴛鴦下渡船。"]', '诗', 'shi', '', NULL, '華下二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ede65138-f7ae-4820-8c86-83f6df887e47', '夢中', '梦中', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["幾多親愛在人間，上徹霞梯會却還。","須是蓬瀛長買得，一家同占作家山。"]', '["幾多親愛在人间，上徹霞梯會却還。","須是蓬瀛长買得，一家同占作家山。"]', '诗', 'shi', '', NULL, '夢中 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7212f954-9201-45a4-8ade-f37c8169944b', '牓下', '牓下', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["三十功名志未伸，初將文字競通津。","春風漫折一枝桂，煙閣英雄笑殺人。"]', '["三十功名志未伸，初將文字競通津。","春风漫折一枝桂，煙閣英雄笑殺人。"]', '诗', 'shi', '', NULL, '牓下 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5ad583-c9b8-49d9-84d9-dca9a7352037', '涔陽渡', '涔陽渡', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["楚田人立帶殘暉，驛逈邨幽客路微。","兩岸蘆花正蕭颯，渚煙深處白牛歸。"]', '["楚田人立带殘暉，驛逈邨幽客路微。","兩岸蘆花正蕭颯，渚煙深处白牛归。"]', '诗', 'shi', '', NULL, '涔陽渡 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('292e2f46-1484-4957-9911-04e67b3e0d6a', '偶作', '偶作', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["索得身歸未保閒，亂來道在辱來頑。","留侯萬戶雖無分，病骨應消一片山。"]', '["索得身归未保閒，亂来道在辱来頑。","留侯万戶雖無分，病骨應消一片山。"]', '诗', 'shi', '', NULL, '偶作 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5182a2c3-644a-4df4-bb80-02b86a3e7d21', '寓居有感三首 一', '寓居有感三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["亦知世路薄忠貞，不忍殘年負聖明。","只待東封沾慶賜，碑陰別刻老臣名。"]', '["亦知世路薄忠貞，不忍殘年負聖明。","只待东封沾慶賜，碑陰別刻老臣名。"]', '诗', 'shi', '', NULL, '寓居有感三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f66ced3-6f1f-4dd0-b2ba-8d42edb89807', '寓居有感三首 二', '寓居有感三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不放殘年却到家，銜杯懶更問生涯。","河堤往往人相送，一曲晴川隔蓼花。"]', '["不放殘年却到家，銜杯懶更问生涯。","河堤往往人相送，一曲晴川隔蓼花。"]', '诗', 'shi', '', NULL, '寓居有感三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd3a0eb2-6662-484c-8d55-ed58e2ce606b', '寓居有感三首 三', '寓居有感三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["黑鬚寄在白鬚生，一度秋風減幾莖。","客處不堪頻送別，無多情緒更傷情。"]', '["黑鬚寄在白鬚生，一度秋风減幾莖。","客处不堪頻送別，無多情緒更傷情。"]', '诗', 'shi', '', NULL, '寓居有感三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f082a741-f916-4f63-8936-90a015f7f73d', '淮西', '淮西', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["鼇冠三山安海浪，龍盤九鼎鎮皇都。","莫誇十萬兵威盛，消箇忠良效順無。"]', '["鼇冠三山安海浪，龙盤九鼎鎮皇都。","莫誇十万兵威盛，消箇忠良效順無。"]', '诗', 'shi', '', NULL, '淮西 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('859d2638-c6f6-4bf9-9487-47723442af8a', '河湟有感', '河湟有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["一自蕭關起戰塵，河湟隔斷異鄉春。","漢兒盡作胡兒語，却向城頭駡漢人。"]', '["一自蕭关起戰塵，河湟隔斷異乡春。","漢兒尽作胡兒語，却向城头駡漢人。"]', '诗', 'shi', '', NULL, '河湟有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceef05e3-d8d0-4172-87d4-10ae07ff58f9', '自䢵鄉北歸', '自䢵乡北归', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["巴煙冪冪久縈恨，楚柳綿綿今送歸。","回避江邊同去鴈，莫教驚起錯南飛。"]', '["巴煙冪冪久縈恨，楚柳綿綿今送归。","回避江邊同去鴈，莫教驚起錯南飞。"]', '诗', 'shi', '', NULL, '自䢵鄉北歸 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9be1961-6ec3-410a-8942-a605daae89a5', '青龍師安上人', '青龙師安上人', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["災曜偏臨許國人，雨中衰菊病中身。","清香一炷知師意，應爲昭陵惜老臣。"]', '["災曜偏臨許国人，雨中衰菊病中身。","清香一炷知師意，應爲昭陵惜老臣。"]', '诗', 'shi', '', NULL, '青龍師安上人 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ca8898e-6e11-4d22-b3fb-25f78cdd37d2', '山中', '山中', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["凡鳥愛喧人靜處，閑雲似妬月明時。","世間萬事非吾事，只愧秋來未有詩。"]', '["凡鸟愛喧人静处，闲云似妬月明时。","世间万事非吾事，只愧秋来未有诗。"]', '诗', 'shi', '', NULL, '山中 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd46271e-d4ef-463f-8de6-18363afd3a2f', '有感二首 一', '有感二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["自古經綸足是非，陰謀最忌奪天機。","留侯却粒商翁去，甲第何人意氣歸。"]', '["自古經綸足是非，陰謀最忌奪天機。","留侯却粒商翁去，甲第何人意氣归。"]', '诗', 'shi', '', NULL, '有感二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727d0915-4736-4487-854a-d84e5bf29f1c', '有感二首 二', '有感二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["古來賢俊共悲辛，長是豪家拒要津。","從此當歌唯痛飲，不須經世爲閑人。"]', '["古来賢俊共悲辛，长是豪家拒要津。","從此當歌唯痛饮，不須經世爲闲人。"]', '诗', 'shi', '', NULL, '有感二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d332fa57-9ced-4073-be51-1f7fe5491ea1', '閑夜二首 一', '闲夜二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["道侶難留爲虐棋，鄰家聞說厭吟詩。","前峰月照分明見，夜合香中露臥時。"]', '["道侶难留爲虐棋，鄰家闻说厭吟诗。","前峰月照分明见，夜合香中露臥时。"]', '诗', 'shi', '', NULL, '閑夜二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34529b19-9e8d-4a0b-8c56-09f2cd368b9d', '閑夜二首 二', '闲夜二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["此身閑得易爲家，業是吟詩與看花。","若使他生拋筆硯，更應無事老煙霞。"]', '["此身闲得易爲家，業是吟诗與看花。","若使他生拋笔硯，更應無事老煙霞。"]', '诗', 'shi', '', NULL, '閑夜二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2805f52e-b4be-46a5-b56a-68d41bb68cbe', '雨中', '雨中', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["維摩居士陶居士，盡說高情未足誇。","簷外蓮峰堦下菊，碧蓮黃菊是吾家。"]', '["維摩居士陶居士，尽说高情未足誇。","簷外蓮峰堦下菊，碧蓮黄菊是吾家。"]', '诗', 'shi', '', NULL, '雨中 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb13728-4f0f-4f06-8b28-174e7558a61d', '送道者二首 一', '送道者二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["洞天真侶昔曾逢，西嶽今居第幾峰。","峰頂他時教我認，相招須把碧芙蓉。"]', '["洞天真侶昔曾逢，西嶽今居第幾峰。","峰頂他时教我認，相招須把碧芙蓉。"]', '诗', 'shi', '', NULL, '送道者二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331e20c0-0fdf-4888-8dd2-7f07215e6f4b', '送道者二首 二', '送道者二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["殷勤不爲學燒金，道侶惟應識此心。","雪裏千山訪君易，微微鹿迹入深林。"]', '["殷勤不爲学燒金，道侶惟應識此心。","雪裏千山訪君易，微微鹿迹入深林。"]', '诗', 'shi', '', NULL, '送道者二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29b1e42-31eb-4971-81a0-2fd32475faa2', '重陽阻雨', '重陽阻雨', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["重陽阻雨獨銜杯，移得山家菊未開。","猶勝登高閑望斷，孤煙殘照馬嘶回。"]', '["重陽阻雨独銜杯，移得山家菊未开。","猶勝登高闲望斷，孤煙殘照马嘶回。"]', '诗', 'shi', '', NULL, '重陽阻雨 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a52c8d7-d4f9-4955-8bdf-4e763935dbd1', '省試', '省試', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["粉闈深鎖唱同人，正是終南雪霽春。","閑繫長安千匹馬，今朝似減六街塵。"]', '["粉闈深鎖唱同人，正是終南雪霽春。","闲繫长安千匹马，今朝似減六街塵。"]', '诗', 'shi', '', NULL, '省試 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59adafe3-ccf5-4d80-9c45-11b836a59d75', '有贈', '有贈', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["有詩有酒有高歌，春色年年奈我何。","試問羲和能駐否，不勞頻借魯陽戈。"]', '["有诗有酒有高歌，春色年年奈我何。","試问羲和能駐否，不勞頻借魯陽戈。"]', '诗', 'shi', '', NULL, '有贈 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c18119-505c-45f1-a140-8b9167a330a5', '證因亭', '證因亭', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["峰北幽亭願證因，他生此地却容身。","上方僧在時應到，笑認前銜記寫真。"]', '["峰北幽亭願證因，他生此地却容身。","上方僧在时應到，笑認前銜記寫真。"]', '诗', 'shi', '', NULL, '證因亭 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93dc5533-b0ff-48c8-a093-6c7eed3951a4', '頃年陪恩地赴甘棠之召感動留題', '頃年陪恩地赴甘棠之召感动留題', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["去時憔悴青衿在，歸路淒涼絳帳空。","無限酬恩心未展，又將孤劒別從公。"]', '["去时憔悴青衿在，归路淒涼絳帳空。","無限酬恩心未展，又將孤劒別從公。"]', '诗', 'shi', '', NULL, '頃年陪恩地赴甘棠之召感動留題 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d17e8d0f-927e-4bda-859f-999d23d458ec', '九月八日', '九月八日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["已是人間寂寞花，解憐寂寞傍貧家。","老來不得登高看，更甚殘春惜歲華。"]', '["已是人间寂寞花，解怜寂寞傍貧家。","老来不得登高看，更甚殘春惜歲华。"]', '诗', 'shi', '', NULL, '九月八日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fdd4d7b-0300-4404-aeaf-a5909b96fb48', '敷溪橋院有感', '敷溪橋院有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["昔歲攀遊景物同，藥爐今在鶴歸空。","青山滿眼淚堪碧，絳帳無人花自紅。"]', '["昔歲攀游景物同，藥爐今在鹤归空。","青山满眼泪堪碧，絳帳無人花自紅。"]', '诗', 'shi', '', NULL, '敷溪橋院有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a937a27-94ca-4571-9934-2eba1d00f19d', '寺閣', '寺閣', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["昔歲登臨未衰颯，不知何事愛傷情。","今來攬鏡翻堪喜，亂後霜鬚長幾莖。"]', '["昔歲登臨未衰颯，不知何事愛傷情。","今来攬镜翻堪喜，亂後霜鬚长幾莖。"]', '诗', 'shi', '', NULL, '寺閣 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e05b47-90ae-4d42-a1da-36feeb03f365', '武陵路', '武陵路', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["橘岸舟間罾網挂，茶坡日暖鷓鴣啼。","女郎指點行人笑，知向花間路已迷。"]', '["橘岸舟间罾網挂，茶坡日暖鷓鴣啼。","女郎指点行人笑，知向花间路已迷。"]', '诗', 'shi', '', NULL, '武陵路 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906f8e3e-2bc8-4b7c-aa10-59d00072a7ad', '南北史感遇十首 一', '南北史感遇十首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["雨淋麟閣名臣畫，雪臥龍庭猛將碑。","不用黃金鑄侯印，盡輸公子買蛾眉。"]', '["雨淋麟閣名臣畫，雪臥龙庭猛將碑。","不用黄金鑄侯印，尽輸公子買蛾眉。"]', '诗', 'shi', '', NULL, '南北史感遇十首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b90861b-84a5-4bff-b9db-5e0152343858', '南北史感遇十首 二', '南北史感遇十首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["漢世頻封萬戶侯，雲臺空峻謝風流。","江南不有名儒相，齒冷中原笑未休。"]', '["漢世頻封万戶侯，云台空峻謝风流。","江南不有名儒相，齒冷中原笑未休。"]', '诗', 'shi', '', NULL, '南北史感遇十首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('196a5473-1878-47b3-971f-8b676a4f0089', '南北史感遇十首 三', '南北史感遇十首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["天風斡海怒長鯨，永固南來百萬兵。","若向滄洲猶笑傲，江山虛有石頭城。"]', '["天风斡海怒长鯨，永固南来百万兵。","若向滄洲猶笑傲，江山虛有石头城。"]', '诗', 'shi', '', NULL, '南北史感遇十首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51d6824-3f6c-4804-9c50-f6a2bea8307c', '南北史感遇十首 四', '南北史感遇十首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["花迷公子玉樓恩，鏡弄佳人紅粉春。","不信關山勞遠戍，綺羅香外任行塵。"]', '["花迷公子玉楼恩，镜弄佳人紅粉春。","不信关山勞远戍，綺羅香外任行塵。"]', '诗', 'shi', '', NULL, '南北史感遇十首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6f11a2-86ac-44d5-aeaf-85e0efef4074', '南北史感遇十首 五', '南北史感遇十首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["兵圍梁殿金甌破，火發陳宮玉樹摧。","姦佞豈能慚誤國，空令懷古更徘徊。"]', '["兵圍梁殿金甌破，火發陳宮玉樹摧。","姦佞豈能慚誤国，空令懷古更徘徊。"]', '诗', 'shi', '', NULL, '南北史感遇十首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a177949c-8394-4a23-9dc2-d2a3d73b81ce', '南北史感遇十首 六', '南北史感遇十首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["行樂最宜連夜景，太平方覺有春風。","千金盡把酬歌舞，猶勝三邊賞戰功。"]', '["行乐最宜連夜景，太平方覺有春风。","千金尽把酬歌舞，猶勝三邊賞戰功。"]', '诗', 'shi', '', NULL, '南北史感遇十首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2131923f-4e69-48a9-8da9-9083b0fd922a', '南北史感遇十首 七', '南北史感遇十首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["桃芳李豔年年發，羌管蠻弦處處多。","海上應無三島路，人間惟有一聲歌。"]', '["桃芳李豔年年發，羌管蠻弦处处多。","海上應無三島路，人间惟有一声歌。"]', '诗', 'shi', '', NULL, '南北史感遇十首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a3e3f2-5695-4f3f-a8b5-d1b9fd6d9463', '南北史感遇十首 八', '南北史感遇十首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["佳人自折一枝紅，把唱新詞曲未終。","惟向眼前憐易落，不如拋擲任春風。"]', '["佳人自折一枝紅，把唱新词曲未終。","惟向眼前怜易落，不如拋擲任春风。"]', '诗', 'shi', '', NULL, '南北史感遇十首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63b9f6d-b4f6-4f72-9c79-65373572e93b', '南北史感遇十首 九', '南北史感遇十首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["景陽樓下花鈿鏡，玄武湖邊錦繡旗。","昔日繁華今日恨，雉媒聲晚草芳時。"]', '["景陽楼下花鈿镜，玄武湖邊錦繡旗。","昔日繁华今日恨，雉媒声晚草芳时。"]', '诗', 'shi', '', NULL, '南北史感遇十首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c5b23b-d12b-4634-8349-5b32b1049ade', '南北史感遇十首 十', '南北史感遇十首 十', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["亂後人間盡不平，秦川花木最傷情。","無窮紅豔紅塵裏，驟馬分香散入營。"]', '["亂後人间尽不平，秦川花木最傷情。","無窮紅豔紅塵裏，驟马分香散入營。"]', '诗', 'shi', '', NULL, '南北史感遇十首 十 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af34609-ac40-474d-b32c-1916f502c9af', '狂題二首 一', '狂題二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["草堂舊隱猶招我，煙閣英才不見君。","惆悵故山歸未得，酒狂呌斷暮天雲。"]', '["草堂旧隐猶招我，煙閣英才不见君。","惆悵故山归未得，酒狂呌斷暮天云。"]', '诗', 'shi', '', NULL, '狂題二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7fd028c-93d4-42c0-b94a-7f758e204277', '狂題二首 二', '狂題二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["須知世亂身難保，莫喜天晴菊併開。","長短此身長是客，黃花更助白頭催。"]', '["須知世亂身难保，莫喜天晴菊併开。","长短此身长是客，黄花更助白头催。"]', '诗', 'shi', '', NULL, '狂題二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab2f15b1-089b-487d-ad97-9b0701863901', '紅茶花', '紅茶花', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["景物詩人見即誇，豈憐高韻說紅茶。","牡丹枉用三春力，開得方知不是花。"]', '["景物诗人见即誇，豈怜高韻说紅茶。","牡丹枉用三春力，开得方知不是花。"]', '诗', 'shi', '', NULL, '紅茶花 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6eb289e-bb50-431a-999a-18ba72044392', '秋燕', '秋燕', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["從撲香塵拂面飛，憐渠只爲解相依。","經冬好近深爐暖，何必千巖萬水歸。"]', '["從撲香塵拂面飞，怜渠只爲解相依。","經冬好近深爐暖，何必千巖万水归。"]', '诗', 'shi', '', NULL, '秋燕 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb19962-a9bc-4d38-98ea-ffbae58ac842', '見後鴈有感', '见後鴈有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["笑爾窮通亦似人，高飛偶滯莫悲辛。","却緣風雪頻相阻，只向關中待得春。"]', '["笑爾窮通亦似人，高飞偶滯莫悲辛。","却緣风雪頻相阻，只向关中待得春。"]', '诗', 'shi', '', NULL, '見後鴈有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3d738c0-0e82-4a31-b70a-2396690083a9', '移桃栽', '移桃栽', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["獨臨官路易傷摧，從遣春風恣意開。","禪客笑移山上看，流鶯直到檻前來。"]', '["独臨官路易傷摧，從遣春风恣意开。","禪客笑移山上看，流鶯直到檻前来。"]', '诗', 'shi', '', NULL, '移桃栽 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3edf7c1e-4b19-417e-b178-25b711542bdb', '憶中條', '憶中條', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["燕辭旅舍人空在，螢出疎籬菊正芳。","堪恨昔年聯句地，念經僧掃過重陽。"]', '["燕辞旅舍人空在，螢出疎籬菊正芳。","堪恨昔年聯句地，念經僧掃過重陽。"]', '诗', 'shi', '', NULL, '憶中條 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f75b4a85-1195-4795-bb42-4d7d52303414', '樂府', '乐府', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["五更窗下簇妝臺，已怕堂前阿母催。","滿鴨香薰鸚鵡睡，隔簾燈照牡丹開。"]', '["五更窗下簇妝台，已怕堂前阿母催。","满鴨香薰鸚鵡睡，隔簾灯照牡丹开。"]', '诗', 'shi', '', NULL, '樂府 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54df2b6a-ecb1-4a11-a567-0dfbc1370d40', '放龜二首 一', '放龟二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["却爲多知自不靈，今朝教汝卜長生。","若求深處無深處，只有依人會有情。"]', '["却爲多知自不靈，今朝教汝卜长生。","若求深处無深处，只有依人會有情。"]', '诗', 'shi', '', NULL, '放龜二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b050df-3193-4236-ba0c-67c2d361dcd9', '放龜二首 二', '放龟二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["世外猶迷不死庭，人間莫恃自無營。","本期滄海堪投跡，却向朱門待放生。"]', '["世外猶迷不死庭，人间莫恃自無營。","本期滄海堪投跡，却向朱门待放生。"]', '诗', 'shi', '', NULL, '放龜二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9e8098f-844e-4ffa-bb18-c83c83c4bb79', '燈花三首 一', '灯花三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["蜀柳絲絲冪畫樓，窗塵滿鏡不梳頭。","幾時金鴈傳歸信，剪斷香魂一縷愁。"]', '["蜀柳絲絲冪畫楼，窗塵满镜不梳头。","幾时金鴈傳归信，剪斷香魂一縷愁。"]', '诗', 'shi', '', NULL, '燈花三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a943e422-5bc0-451f-9b29-1e1ad75a9a12', '燈花三首 二', '灯花三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["姊姊教人且抱兒，逐他女伴卸頭遲。","明朝鬬草多應喜，剪得燈花自掃眉。"]', '["姊姊教人且抱兒，逐他女伴卸头遲。","明朝鬬草多應喜，剪得灯花自掃眉。"]', '诗', 'shi', '', NULL, '燈花三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a0aa0c-00d8-47e7-bcb5-38532790c332', '燈花三首 三', '灯花三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["閏前小雪過經旬，猶自依依向主人。","開盡菊花憐強舞，與教弟子待新春。"]', '["閏前小雪過經旬，猶自依依向主人。","开尽菊花怜強舞，與教弟子待新春。"]', '诗', 'shi', '', NULL, '燈花三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e27ba0b4-74a1-46d2-8684-23b3060e3a15', '偶題三首 一', '偶題三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["浮世悠悠旋一空，多情偏解挫英雄。","風光只在歌聲裏，不必樓前萬樹紅。"]', '["浮世悠悠旋一空，多情偏解挫英雄。","风光只在歌声裏，不必楼前万樹紅。"]', '诗', 'shi', '', NULL, '偶題三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c7220f-25ff-4ffa-af79-2474714bf7d9', '偶題三首 二', '偶題三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["小池隨事有風荷，燒酹傾壺一曲歌。","欲待秋塘擎露看，自憐生意已無多。"]', '["小池隨事有风荷，燒酹傾壺一曲歌。","欲待秋塘擎露看，自怜生意已無多。"]', '诗', 'shi', '', NULL, '偶題三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481ce1c7-296d-4125-b08c-f147b30e70f8', '偶題三首 三', '偶題三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["遼陽音信近來稀，縱有虛傳逼節歸。","永日無人新睡覺，小窗晴暖螖蟲飛。"]', '["遼陽音信近来稀，縱有虛傳逼節归。","永日無人新睡覺，小窗晴暖螖蟲飞。"]', '诗', 'shi', '', NULL, '偶題三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b2a898c-bb52-463e-8a8a-989eacb2ce54', '華下對菊', '华下对菊', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["清香裛露對高齋，泛酒偏能浣旅懷。","不似春風逞紅豔，鏡前空墜玉人釵。"]', '["清香裛露对高斋，泛酒偏能浣旅懷。","不似春风逞紅豔，镜前空墜玉人釵。"]', '诗', 'shi', '', NULL, '華下對菊 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a4b6b4-2408-4827-ae5d-91a91e098389', '與都統參謀書有感', '與都統參謀书有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["驚鸞迸鷺盡歸林，弱羽低垂分獨沈。","帶病深山猶草檄，昭陵應識老臣心。"]', '["驚鸾迸鷺尽归林，弱羽低垂分独沈。","带病深山猶草檄，昭陵應識老臣心。"]', '诗', 'shi', '', NULL, '與都統參謀書有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c875271f-d47b-4010-b4b4-d9b3f3b9c5f5', '漫題', '漫題', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["無宦無名拘逸興，有歌有酒任他鄉。","看看萬里休征戍，莫向新詞寄斷腸。"]', '["無宦無名拘逸兴，有歌有酒任他乡。","看看万里休征戍，莫向新词寄斷腸。"]', '诗', 'shi', '', NULL, '漫題 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e3ad85-c2f1-4ea3-bd10-52b921888b99', '商山二首 一', '商山二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["清溪一路照羸身，不似雲臺畫像人。","國史數行猶有志，只將談笑繼英塵。"]', '["清溪一路照羸身，不似云台畫像人。","国史數行猶有志，只將談笑繼英塵。"]', '诗', 'shi', '', NULL, '商山二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25326f18-48cc-4720-af69-b2aa233f1ac7', '商山二首 二', '商山二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["馬上搜奇已數篇，籍中猶愧是頑仙。","關頭傳說開元事，指點多疑孟浩然。"]', '["马上搜奇已數篇，籍中猶愧是頑仙。","关头傳说开元事，指点多疑孟浩然。"]', '诗', 'shi', '', NULL, '商山二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca92128a-9106-4005-b434-e67244e6f007', '與伏牛長老偈二首 一', '與伏牛长老偈二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不算菩提與闡提，惟應執著便生迷。","無端指箇清涼地，凍殺胡僧雪嶺西。"]', '["不算菩提與闡提，惟應執著便生迷。","無端指箇清涼地，凍殺胡僧雪嶺西。"]', '诗', 'shi', '', NULL, '與伏牛長老偈二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b7899bb-1a57-4288-964b-7bdeeda5ed36', '與伏牛長老偈二首 二', '與伏牛长老偈二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["長繩不見繫空虛，半偈傳心亦未疎。","推倒我山無一事，莫將文字縛真如。"]', '["长繩不见繫空虛，半偈傳心亦未疎。","推倒我山無一事，莫將文字縛真如。"]', '诗', 'shi', '', NULL, '與伏牛長老偈二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdaacef-225a-4e18-be7b-6858ab7c563d', '客中重九', '客中重九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["楚老相逢淚滿衣，片名薄宦已知非。","他鄉不似人間路，應共東流更不歸。"]', '["楚老相逢泪满衣，片名薄宦已知非。","他乡不似人间路，應共东流更不归。"]', '诗', 'shi', '', NULL, '客中重九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67ffac96-3f1d-4458-9b34-ff8451c58b08', '柳二首 一', '柳二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["誰家按舞傍池塘，已見繁枝嫩眼黃。","漫說早梅先得意，不知春力暗分張。"]', '["誰家按舞傍池塘，已见繁枝嫩眼黄。","漫说早梅先得意，不知春力暗分張。"]', '诗', 'shi', '', NULL, '柳二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea4fbda-55b6-4644-bdfb-bb55ade4b775', '柳二首 二', '柳二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["似擬凌寒妬早梅，無端弄色傍高臺。","折來未有新枝長，莫遣佳人更折來。"]', '["似擬凌寒妬早梅，無端弄色傍高台。","折来未有新枝长，莫遣佳人更折来。"]', '诗', 'shi', '', NULL, '柳二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c703eead-d107-4bbd-a80e-ef5dc643249b', '光啓丁未別山', '光啓丁未別山', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["草堂琴畫已判燒，猶託鄰僧護燕巢。","此去不緣名利去，若逢逋客莫相嘲。"]', '["草堂琴畫已判燒，猶託鄰僧護燕巢。","此去不緣名利去，若逢逋客莫相嘲。"]', '诗', 'shi', '', NULL, '光啓丁未別山 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf2eff6a-4ba8-4cc5-bbd0-20db73deea71', '石楠', '石楠', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["客處偷閑未是閑，石楠雖好懶頻攀。","如何風葉西歸路，吹斷寒雲見故山。"]', '["客处偷闲未是闲，石楠雖好懶頻攀。","如何风葉西归路，吹斷寒云见故山。"]', '诗', 'shi', '', NULL, '石楠 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e404e90-20f9-41d9-8679-47823e26ae7c', '力疾馬上走筆', '力疾马上走笔', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["釀黍長添不盡杯，只憂花盡客空回。","垂楊且爲晴遮日，留遇重陽即放開。"]', '["釀黍长添不尽杯，只憂花尽客空回。","垂楊且爲晴遮日，留遇重陽即放开。"]', '诗', 'shi', '', NULL, '力疾馬上走筆 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2168941-acbf-4852-8bb5-500827b47458', '華陰縣樓', '华陰縣楼', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["丹霄能有幾層梯，懶更揚鞭聳翠蜺。","偶凭危欄且南望，不勞高掌欲相攜。"]', '["丹霄能有幾層梯，懶更揚鞭聳翠蜺。","偶凭危欄且南望，不勞高掌欲相携。"]', '诗', 'shi', '', NULL, '華陰縣樓 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49bb7bf9-2594-4a85-a84e-f9cf96751952', '南至四首 一', '南至四首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["今冬臘後無殘日，故國燒來有幾家。","却恨早梅添旅思，強偷春力報年華。"]', '["今冬臘後無殘日，故国燒来有幾家。","却恨早梅添旅思，強偷春力報年华。"]', '诗', 'shi', '', NULL, '南至四首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bedbeff9-86b6-44f6-9c03-a1de472ca63e', '南至四首 二', '南至四首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["花時不是偏愁我，好事應難總取他。","已被詩魔長役思，眼中莫厭早梅多。"]', '["花时不是偏愁我，好事應难總取他。","已被诗魔长役思，眼中莫厭早梅多。"]', '诗', 'shi', '', NULL, '南至四首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfd3ec4-eaa3-4d89-b90e-6b023d1a4d7a', '南至四首 三', '南至四首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["年華亂後偏堪惜，世路拋來已自生。","猶有玉真長命縷，樽前時唱緩羇情。"]', '["年华亂後偏堪惜，世路拋来已自生。","猶有玉真长命縷，樽前时唱緩羇情。"]', '诗', 'shi', '', NULL, '南至四首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2896779-22ab-4794-b6a1-c7e8584a1e7a', '南至四首 四', '南至四首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["一任喧闐遶四鄰，閑忙皆是自由身。","人來客去還須議，莫遣他人作主人。"]', '["一任喧闐遶四鄰，闲忙皆是自由身。","人来客去還須議，莫遣他人作主人。"]', '诗', 'shi', '', NULL, '南至四首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a528c2bf-ede7-4fe5-9b32-4e1ce6ae204f', '蓮峰前軒', '蓮峰前軒', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["人間上壽若能添，只向人間也不嫌。","看著四鄰花競發，高樓從此莫垂簾。"]', '["人间上壽若能添，只向人间也不嫌。","看著四鄰花競發，高楼從此莫垂簾。"]', '诗', 'shi', '', NULL, '蓮峰前軒 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3831d44-dbc6-4ad8-87e2-d39388ddc2f2', '步虛', '步虛', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["阿母親教學步虛，三元長遣下蓬壺。","雲韶韻俗停瑤瑟，鸞鶴飛低拂寶爐。"]', '["阿母親教学步虛，三元长遣下蓬壺。","云韶韻俗停瑤瑟，鸾鹤飞低拂寶爐。"]', '诗', 'shi', '', NULL, '步虛 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f93b1bc-5812-499c-a335-d1d21f21ee76', '劒器', '劒器', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["樓下公孫昔擅場，空教女子愛軍裝。","潼關一敗吳兒喜，簇馬驪山看御湯。"]', '["楼下公孫昔擅場，空教女子愛軍裝。","潼关一敗吳兒喜，簇马驪山看御湯。"]', '诗', 'shi', '', NULL, '劒器 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14dc4dda-013d-450d-89a9-274d48be6d06', '乙丑人日', '乙丑人日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["自怪扶持七十身，歸來又見故鄉春。","今朝人日逢人喜，不料偷生作老人。"]', '["自怪扶持七十身，归来又见故乡春。","今朝人日逢人喜，不料偷生作老人。"]', '诗', 'shi', '', NULL, '乙丑人日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ddc9c94-c95c-47fb-b52f-6b9a2ee94b25', '攜仙籙九首 一', '携仙籙九首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["嶽北秋空渭北川，晴雲漸薄薄如煙。","坐來還見微風起，吹散殘陽一片蟬。"]', '["嶽北秋空渭北川，晴云漸薄薄如煙。","坐来還见微风起，吹散殘陽一片蟬。"]', '诗', 'shi', '', NULL, '攜仙籙九首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ffd8c76-a8f3-481f-8282-0af4b34af10a', '攜仙籙九首 二', '携仙籙九首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["一半晴空一半雲，遠籠仙掌日初曛。","洞天有路不知處，絕頂異香難更聞。"]', '["一半晴空一半云，远籠仙掌日初曛。","洞天有路不知处，絕頂異香难更闻。"]', '诗', 'shi', '', NULL, '攜仙籙九首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1212ae62-bd88-49c2-b180-3aadadbb7ea6', '攜仙籙九首 三', '携仙籙九首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["決事還須更事酬，清譚妙理一時休。","漁翁亦被機心誤，眼暗汀邊結釣鉤。"]', '["決事還須更事酬，清譚妙理一时休。","漁翁亦被機心誤，眼暗汀邊結釣鉤。"]', '诗', 'shi', '', NULL, '攜仙籙九首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb5eddd-72e5-4568-817b-f1d147bd5b95', '攜仙籙九首 四', '携仙籙九首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["迹不趨時分不侯，功名身外最悠悠。","聽君總畫麒麟閣，還我閑眠舴艋舟。"]', '["迹不趨时分不侯，功名身外最悠悠。","听君總畫麒麟閣，還我闲眠舴艋舟。"]', '诗', 'shi', '', NULL, '攜仙籙九首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b760d250-680a-4cee-9c94-b5b3be2045aa', '攜仙籙九首 五', '携仙籙九首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["仙凡路阻兩難留，煙樹人間一片秋。","若道陰功能濟活，且將方寸自焚修。"]', '["仙凡路阻兩难留，煙樹人间一片秋。","若道陰功能濟活，且將方寸自焚修。"]', '诗', 'shi', '', NULL, '攜仙籙九首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e4b7cc-0c92-475c-bc45-eef841195088', '攜仙籙九首 六', '携仙籙九首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["若有陰功救未然，玉皇品籍亦搜賢。","應知譚笑還高謝，別就滄洲贊上仙。"]', '["若有陰功救未然，玉皇品籍亦搜賢。","應知譚笑還高謝，別就滄洲贊上仙。"]', '诗', 'shi', '', NULL, '攜仙籙九首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1002cb9-95e8-4407-af27-605ce4cc42ca', '攜仙籙九首 七', '携仙籙九首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["英名何用苦搜奇，不朽才銷一句詩。","却賴風波阻三島，老臣猶得戀明時。"]', '["英名何用苦搜奇，不朽才銷一句诗。","却賴风波阻三島，老臣猶得戀明时。"]', '诗', 'shi', '', NULL, '攜仙籙九首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21a2d8ee-081e-4e5d-a6bd-fc816d1fc598', '攜仙籙九首 八', '携仙籙九首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["剪取紅雲剩寫詩，年年高會趂花時。","水精樓閣分明見，只欠霞漿別着旗。"]', '["剪取紅云剩寫诗，年年高會趂花时。","水精楼閣分明见，只欠霞漿別着旗。"]', '诗', 'shi', '', NULL, '攜仙籙九首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc4f2355-6494-4a20-9294-d00f856064a2', '攜仙籙九首 九', '携仙籙九首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["此生得作太平人，只向塵中便出塵。","移取碧桃花萬樹，年年自樂故鄉春。"]', '["此生得作太平人，只向塵中便出塵。","移取碧桃花万樹，年年自乐故乡春。"]', '诗', 'shi', '', NULL, '攜仙籙九首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958de4ab-6af8-4f35-9242-286f7fdeda4a', '浪淘沙', '浪淘沙', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不必長漂玉洞花，曲中偏愛浪淘沙。","黃河却勝天河水，萬里縈紆入漢家。"]', '["不必长漂玉洞花，曲中偏愛浪淘沙。","黄河却勝天河水，万里縈紆入漢家。"]', '诗', 'shi', '', NULL, '浪淘沙 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fae27a5-d0fc-40ef-83b2-c93f921d8c99', '贈日東鑒禪師', '贈日东鑒禪師', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["故國無心度海潮，老禪方丈倚中條。","夜深雨絕松堂靜，一點飛螢照寂寥。"]', '["故国無心度海潮，老禪方丈倚中條。","夜深雨絕松堂静，一点飞螢照寂寥。"]', '诗', 'shi', '', NULL, '贈日東鑒禪師 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2704fd10-b4df-4513-933b-f9b3098cd33a', '暮春對柳二首 一', '暮春对柳二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["縈愁惹恨奈楊花，閉戶垂簾亦滿家。","惱得閑人作酒病，剛須又撲越溪茶。"]', '["縈愁惹恨奈楊花，閉戶垂簾亦满家。","惱得闲人作酒病，剛須又撲越溪茶。"]', '诗', 'shi', '', NULL, '暮春對柳二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62909bd-51e3-4666-a2a4-d5185a50f331', '暮春對柳二首 二', '暮春对柳二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["洞中猶說看桃花，輕絮狂飛自俗家。","正是階前開遠信，小娥旋拂碾新茶。"]', '["洞中猶说看桃花，轻絮狂飞自俗家。","正是階前开远信，小娥旋拂碾新茶。"]', '诗', 'shi', '', NULL, '暮春對柳二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361bc5af-cc1c-47d5-a5ba-1f66e2e69dc2', '戊午三月晦二首 一', '戊午三月晦二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["隨風逐浪劇蓬萍，圓首何曾解最靈。","筆硯近來多自棄，不關妖氣暗文星。"]', '["隨风逐浪劇蓬萍，圓首何曾解最靈。","笔硯近来多自棄，不关妖氣暗文星。"]', '诗', 'shi', '', NULL, '戊午三月晦二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da82f6b2-0628-4572-b66d-dbc5c16a8185', '戊午三月晦二首 二', '戊午三月晦二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["牛誇棋品無勍敵，謝占詩家作上流。","豈似小敷春水漲，年年鸞鶴待仙舟。"]', '["牛誇棋品無勍敵，謝占诗家作上流。","豈似小敷春水漲，年年鸾鹤待仙舟。"]', '诗', 'shi', '', NULL, '戊午三月晦二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c0d7433-4a8a-4602-954f-04287b3ec27f', '偶書五首 一', '偶书五首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["情知了得未如僧，客處高樓莫強登。","鶯也解啼花也發，不關心事最堪憎。"]', '["情知了得未如僧，客处高楼莫強登。","鶯也解啼花也發，不关心事最堪憎。"]', '诗', 'shi', '', NULL, '偶書五首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e619df05-df8e-4ff2-a5bf-26e7c6e5c9f3', '偶書五首 二', '偶书五首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["自有池荷作扇搖，不關風動愛芭蕉。","只憐直上抽紅蘂，似我丹心向本朝。"]', '["自有池荷作扇搖，不关风动愛芭蕉。","只怜直上抽紅蘂，似我丹心向本朝。"]', '诗', 'shi', '', NULL, '偶書五首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e399cb40-2190-4b8c-ae1a-20940e59d16f', '偶書五首 三', '偶书五首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["曾看輕舟渡遠津，無風著岸不經旬。","只緣命蹇須知命，却是人爭阻得人。"]', '["曾看轻舟渡远津，無风著岸不經旬。","只緣命蹇須知命，却是人爭阻得人。"]', '诗', 'shi', '', NULL, '偶書五首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e7ddeba-3e22-440f-b112-38b84cb3fd57', '偶書五首 四', '偶书五首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["上谷何曾解有情，有情人自惜君行。","證因池上今生願，的的他生作化生。"]', '["上谷何曾解有情，有情人自惜君行。","證因池上今生願，的的他生作化生。"]', '诗', 'shi', '', NULL, '偶書五首 四 司空圖 shi');
